#[derive(Debug, Default)]
struct SessionDiagnosticsCounters {
    operation_count: AtomicU64,
    registry_lock_wait_us: AtomicU64,
    session_lock_wait_us: AtomicU64,
    session_lock_hold_us: AtomicU64,
    snapshot_projection_count: AtomicU64,
    app_ui_projection_count: AtomicU64,
    settings_projection_count: AtomicU64,
    weather_projection_count: AtomicU64,
    map_projection_count: AtomicU64,
    situation_projection_count: AtomicU64,
    flight_plan_projection_count: AtomicU64,
    package_projection_count: AtomicU64,
    cloud_projection_count: AtomicU64,
    data_status_projection_count: AtomicU64,
    last_session_payload_serialized_bytes: AtomicU64,
    session_update_projection_count: AtomicU64,
    session_update_projection_total_us: AtomicU64,
    session_update_projection_max_us: AtomicU64,
    session_update_group_counts: [AtomicU64; UiSessionUpdateGroup::COUNT],
    transaction_commit_count: AtomicU64,
    transaction_rollback_count: AtomicU64,
}

impl SessionDiagnosticsCounters {
    fn snapshot(
        &self,
        generation: u64,
        phase: UiSessionPhase,
        settings_revision: u64,
        weather_revision: u64,
        map_revision: u64,
        situation_revision: u64,
        flight_plan_revision: u64,
        nav_data_revision: u64,
        package_revision: u64,
        cloud_revision: u64,
        data_status_revision: u64,
    ) -> UiSessionDiagnostics {
        UiSessionDiagnostics {
            generation,
            phase,
            operation_count: self.operation_count.load(Ordering::Relaxed),
            registry_lock_wait_us: self.registry_lock_wait_us.load(Ordering::Relaxed),
            session_lock_wait_us: self.session_lock_wait_us.load(Ordering::Relaxed),
            session_lock_hold_us: self.session_lock_hold_us.load(Ordering::Relaxed),
            snapshot_projection_count: self.snapshot_projection_count.load(Ordering::Relaxed),
            app_ui_projection_count: self.app_ui_projection_count.load(Ordering::Relaxed),
            settings_projection_count: self.settings_projection_count.load(Ordering::Relaxed),
            weather_projection_count: self.weather_projection_count.load(Ordering::Relaxed),
            map_projection_count: self.map_projection_count.load(Ordering::Relaxed),
            situation_projection_count: self.situation_projection_count.load(Ordering::Relaxed),
            flight_plan_projection_count: self.flight_plan_projection_count.load(Ordering::Relaxed),
            settings_revision,
            weather_revision,
            map_revision,
            situation_revision,
            flight_plan_revision,
            nav_data_revision,
            package_revision,
            package_projection_count: self.package_projection_count.load(Ordering::Relaxed),
            cloud_revision,
            cloud_projection_count: self.cloud_projection_count.load(Ordering::Relaxed),
            data_status_revision,
            data_status_projection_count: self.data_status_projection_count.load(Ordering::Relaxed),
            last_session_payload_serialized_bytes: self
                .last_session_payload_serialized_bytes
                .load(Ordering::Relaxed),
            session_updates: UiSessionUpdateDiagnostics {
                projection_count: self.session_update_projection_count.load(Ordering::Relaxed),
                projection_total_us: self
                    .session_update_projection_total_us
                    .load(Ordering::Relaxed),
                projection_max_us: self
                    .session_update_projection_max_us
                    .load(Ordering::Relaxed),
                nav_data_count: self.session_update_group_count(UiSessionUpdateGroup::NavData),
                application_shell_count: self
                    .session_update_group_count(UiSessionUpdateGroup::ApplicationShell),
                flight_plan_count: self
                    .session_update_group_count(UiSessionUpdateGroup::FlightPlan),
                ownship_count: self.session_update_group_count(UiSessionUpdateGroup::Ownship),
                flight_data_count: self
                    .session_update_group_count(UiSessionUpdateGroup::FlightData),
                situation_count: self.session_update_group_count(UiSessionUpdateGroup::Situation),
                charts_count: self.session_update_group_count(UiSessionUpdateGroup::Charts),
                map_count: self.session_update_group_count(UiSessionUpdateGroup::Map),
                status_count: self.session_update_group_count(UiSessionUpdateGroup::Status),
                settings_count: self.session_update_group_count(UiSessionUpdateGroup::Settings),
                cloud_count: self.session_update_group_count(UiSessionUpdateGroup::Cloud),
                packages_count: self.session_update_group_count(UiSessionUpdateGroup::Packages),
                home_count: self.session_update_group_count(UiSessionUpdateGroup::Home),
                debug_count: self.session_update_group_count(UiSessionUpdateGroup::Debug),
            },
            transaction_commit_count: self.transaction_commit_count.load(Ordering::Relaxed),
            transaction_rollback_count: self.transaction_rollback_count.load(Ordering::Relaxed),
        }
    }

    fn record_session_update(&self, update: &UiSessionUpdate, projection_us: u64) {
        self.session_update_projection_count
            .fetch_add(1, Ordering::Relaxed);
        self.session_update_projection_total_us
            .fetch_add(projection_us, Ordering::Relaxed);
        self.session_update_projection_max_us
            .fetch_max(projection_us, Ordering::Relaxed);

        for (group, patch) in update.projection_patches() {
            if patch.is_some() {
                self.session_update_group_counts[group as usize].fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    fn session_update_group_count(&self, group: UiSessionUpdateGroup) -> u64 {
        self.session_update_group_counts[group as usize].load(Ordering::Relaxed)
    }
}

