fn upsert_data_status_record(session: &mut UiSession, record: DataStatusRecord) -> bool {
    session.data_status.upsert(record)
}

fn clear_data_status_record(session: &mut UiSession, id: &str) -> bool {
    session.data_status.clear(id)
}

fn sync_adsb_ownship_status_record(session: &mut UiSession) {
    if !session.coordinator.debug_state.internet_adsb || !adsb_ownship_selected(session) {
        clear_data_status_record(session, ADSB_OWNSHIP_STATUS_ID);
        return;
    }
    let failed = session.runtime.adsb.ownship_last_error().is_some();
    upsert_data_status_record(
        session,
        DataStatusRecord::new(
            ADSB_OWNSHIP_STATUS_ID,
            "ADS-B",
            Some(if failed { "UNAVAILABLE" } else { "ACTIVE" }.to_string()),
            if failed {
                UiStatusSeverity::Warning
            } else {
                UiStatusSeverity::Info
            },
            failed,
            session
                .runtime
                .adsb
                .ownship_status_detail(session.coordinator.wall_clock_epoch_ms),
        ),
    );
}

fn sync_cloud_status_record(session: &mut UiSession, record: Option<DataStatusRecord>) {
    if let Some(record) = record {
        upsert_data_status_record(session, record);
    } else {
        clear_data_status_record(session, CLOUD_STATUS_ID);
    }
}

fn project_cloud_for_session(session: &mut UiSession) -> CloudProjection {
    let projection = session.cloud.project(CloudProjectionInput {
        now_epoch_ms: session.coordinator.wall_clock_epoch_ms,
        qr_scanner_available: session
            .coordinator
            .platform_capabilities
            .cloud
            .as_ref()
            .is_some_and(|cloud| cloud.qr_scan),
    });
    if projection.rebuilt {
        session
            .diagnostics
            .cloud_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    projection.projection
}

fn data_status_page_input(
    session: &UiSession,
    cloud_projection: &CloudProjection,
) -> DataStatusPageInput {
    let live_feeds = session.weather.live_feeds();
    let index_loaded = live_feeds.current_loaded();
    let product =
        |product_id: &str,
         loaded: bool,
         collected_utc: Option<DateTime<Utc>>,
         loaded_version: Option<String>| DataStatusLiveFeedProductInput {
            loaded,
            listed: live_feeds.has_product_current_version(product_id),
            index_loaded,
            collected_utc,
            loaded_version,
        };
    let metars = metar_live_feed_status_source(session);
    let tafs = taf_live_feed_status_source(session);
    let pireps = pirep_live_feed_status_source(session);
    let tfrs_collected_utc = live_feed_status_timestamp(session, "tfrs").or_else(|| {
        session
            .weather
            .runtime()
            .tfr_payload
            .as_ref()
            .and_then(|payload| payload.generated_at_utc)
    });
    let obstacles_collected_utc = live_feed_status_timestamp(session, "obstacles").or_else(|| {
        live_feeds
            .product_state_manifest("obstacles")
            .and_then(json_generated_at_utc)
    });
    let nexrad_collected_utc = live_feed_status_timestamp(session, "nexrad")
        .or_else(|| nexrad_status_manifest(session).and_then(json_observed_at_utc));
    let mut live_feed_products = BTreeMap::new();
    live_feed_products.insert(
        "tfrs".to_string(),
        product(
            "tfrs",
            session.weather.runtime().tfr_payload.is_some(),
            tfrs_collected_utc,
            live_feeds
                .product_loaded_version("tfrs")
                .map(str::to_string),
        ),
    );
    live_feed_products.insert(
        "notams".to_string(),
        product(
            "notams",
            session.weather.runtime().airport_notam_index.is_some(),
            live_feed_status_timestamp(session, "notams"),
            live_feeds
                .product_loaded_version("notams")
                .map(str::to_string),
        ),
    );
    live_feed_products.insert(
        "metars".to_string(),
        product(
            "metars",
            metars.loaded,
            metars.collected_utc,
            metars.loaded_version,
        ),
    );
    live_feed_products.insert(
        "pireps".to_string(),
        product(
            "pireps",
            pireps.loaded,
            pireps.collected_utc,
            pireps.loaded_version,
        ),
    );
    live_feed_products.insert(
        "tafs".to_string(),
        product("tafs", tafs.loaded, tafs.collected_utc, tafs.loaded_version),
    );
    live_feed_products.insert(
        "nexrad".to_string(),
        product(
            "nexrad",
            nexrad_status_manifest(session).is_some(),
            nexrad_collected_utc,
            latest_installed_nexrad(session)
                .map(|installed| installed.version.clone())
                .or_else(|| {
                    live_feeds
                        .product_loaded_version("nexrad")
                        .map(str::to_string)
                }),
        ),
    );
    live_feed_products.insert(
        "obstacles".to_string(),
        product(
            "obstacles",
            session.weather.runtime().obstacle_had.is_some()
                || live_feeds.product_state_manifest("obstacles").is_some(),
            obstacles_collected_utc,
            session
                .weather
                .runtime()
                .obstacle_had
                .as_ref()
                .map(|had| had.source.version.clone())
                .or_else(|| {
                    live_feeds
                        .product_loaded_version("obstacles")
                        .map(str::to_string)
                }),
        ),
    );

    let connection = session.weather.connection();
    let forecast_manifest = session
        .weather
        .runtime()
        .forecast_atmosphere
        .as_ref()
        .map(crate::InstalledForecastAtmosphere::manifest)
        .or_else(|| {
            session
                .weather
                .runtime()
                .forecast_atmosphere_state
                .as_ref()
                .map(|state| &state.manifest)
        });
    DataStatusPageInput {
        now_epoch_ms: session.coordinator.wall_clock_epoch_ms,
        time_display_mode: session.coordinator.time_display_mode,
        local_time_zone: session_local_time_zone(session).unwrap_or(chrono_tz::UTC),
        client_build: session
            .coordinator
            .platform_capabilities
            .client_build
            .clone(),
        nav_db_available: session.nav_data.store().is_some(),
        active_nav_db: session.nav_data.active_artifact().map(|artifact| {
            DataStatusNavDbArtifactInput {
                package_id: artifact.package_id.clone(),
                filename: artifact.filename.clone(),
                cycle: artifact.cycle.clone(),
                cycle_version: artifact.cycle_version.clone(),
                contract_id: artifact.contract_id.clone(),
                effective_date: artifact.effective_date.clone(),
                expiration_date: artifact.expiration_date.clone(),
            }
        }),
        nav_db_packages: nav_db_package_records(session),
        published_packages: session.packages.loaded_bundle_packages().cloned().collect(),
        publication: session.packages.current_artifacts().map(|current| {
            DataStatusPublicationInput {
                bundle_count: current.bundles.len(),
                loaded_manifest_count: session.packages.loaded_bundle_manifest_count(),
                as_of_utc: current.as_of_utc.clone(),
                checked_epoch_ms: session.packages.current_artifacts_checked_epoch_ms(),
            }
        }),
        cloud: session
            .coordinator
            .platform_capabilities
            .cloud
            .as_ref()
            .map(|_| cloud_projection.status_summary.clone()),
        live_feed_connection: DataStatusLiveFeedConnectionInput {
            mode: match connection.mode {
                LiveFeedConnectionMode::Unknown => DataStatusLiveFeedConnectionMode::Unknown,
                LiveFeedConnectionMode::Connecting => DataStatusLiveFeedConnectionMode::Connecting,
                LiveFeedConnectionMode::Connected => DataStatusLiveFeedConnectionMode::Connected,
                LiveFeedConnectionMode::Error => DataStatusLiveFeedConnectionMode::Error,
                LiveFeedConnectionMode::Closed => DataStatusLiveFeedConnectionMode::Closed,
            },
            source_url: connection.source_url.clone(),
            status_url: connection.status_url.clone(),
            last_heard_epoch_ms: connection.last_heard_epoch_ms,
            last_error_epoch_ms: connection.last_error_epoch_ms,
            last_error_message: connection.last_error_message.clone(),
            last_resource_error_epoch_ms: connection.last_resource_error_epoch_ms,
            last_resource_error_message: connection.last_resource_error_message.clone(),
            network_status: connection.network_status,
        },
        live_feed_products,
        forecast: DataStatusForecastInput {
            loaded: session.weather.runtime().forecast_atmosphere.is_some(),
            listed: live_feeds.has_product_current_version("winds-aloft"),
            index_loaded,
            version_label: forecast_manifest.map(|manifest| manifest.version_label.clone()),
            model_id: forecast_manifest.map(|manifest| manifest.model_id.clone()),
            cycle_time_epoch_ms: forecast_manifest.map(|manifest| manifest.cycle_time_epoch_ms),
            valid_through_epoch_ms: forecast_manifest
                .and_then(|manifest| manifest.valid_times_epoch_ms.last().copied()),
        },
        nexrad_frame_age_summary: nexrad_frame_age_summary(session),
    }
}

fn enqueue_session_resource_effect(
    session: &mut UiSession,
    resource: CoreResourceRequest,
    completion_invalidations: impl IntoIterator<Item = UiInvalidation>,
) {
    let mut invalidations = completion_invalidations.into_iter().collect::<Vec<_>>();
    if let Some(existing) = session
        .runtime
        .pending_resource_effects
        .iter_mut()
        .find(|effect| effect.resource.id == resource.id)
    {
        for invalidation in invalidations.drain(..) {
            if !existing.completion_invalidations.contains(&invalidation) {
                existing.completion_invalidations.push(invalidation);
            }
        }
        return;
    }
    session
        .runtime
        .pending_resource_effects
        .push(UiSessionResourceEffect {
            resource,
            completion_invalidations: invalidations,
        });
}

pub fn drain_session_resource_effects(handle: u32) -> AppResult<Vec<UiSessionResourceEffect>> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    Ok(std::mem::take(
        &mut session.runtime.pending_resource_effects,
    ))
}

fn sync_layer_unavailable_status_record(
    session: &mut UiSession,
    visible_and_unavailable: bool,
    status_id: &str,
    record: DataStatusRecord,
) -> Vec<UiInvalidation> {
    let changed = if visible_and_unavailable {
        upsert_data_status_record(session, record)
    } else {
        clear_data_status_record(session, status_id)
    };
    if changed {
        vec![UiInvalidation::SessionSnapshot]
    } else {
        Vec::new()
    }
}

fn sync_live_feed_product_status_record(
    session: &mut UiSession,
    visible: bool,
    payload_loaded: bool,
    product: &str,
    generic_detail: &str,
    collected_utc: Option<DateTime<Utc>>,
    freshness_policy: crate::freshness::AgeFreshnessPolicy,
) -> Vec<UiInvalidation> {
    let status_id = live_feed_unavailable_status_record(product, String::new()).id;
    if !visible {
        let changed = clear_data_status_record(session, &status_id);
        return if changed {
            vec![UiInvalidation::SessionSnapshot]
        } else {
            Vec::new()
        };
    }
    if payload_loaded {
        let label = live_feed_unavailable_status_record(product, String::new()).label;
        let changed = sync_live_feed_age_status_record(
            session,
            true,
            &status_id,
            &label,
            &label,
            collected_utc,
            freshness_policy,
        );
        return if changed {
            vec![UiInvalidation::SessionSnapshot]
        } else {
            Vec::new()
        };
    }
    if session.data_status.contains(&status_id) {
        return Vec::new();
    }
    sync_layer_unavailable_status_record(
        session,
        true,
        &status_id,
        live_feed_unavailable_status_record(product, generic_detail.to_string()),
    )
}

fn sync_live_feed_overlay_status_records(session: &mut UiSession) -> Vec<UiInvalidation> {
    let mut invalidations = Vec::new();
    let metars_visible = session.map.layer_state().metars.visible;
    let metars_status = metar_live_feed_status_source(session);
    invalidations.extend(sync_live_feed_product_status_record(
        session,
        metars_visible,
        metars_status.loaded,
        "metars",
        "METAR live feed unavailable: no current METAR product is loaded",
        metars_status.collected_utc,
        DATA_FRESHNESS_POLICIES.live_feeds.metars,
    ));

    let pireps_status = pirep_live_feed_status_source(session);
    invalidations.extend(sync_live_feed_product_status_record(
        session,
        metars_visible,
        pireps_status.loaded,
        "pireps",
        "PIREP live feed unavailable: no current PIREP product is loaded",
        pireps_status.collected_utc,
        DATA_FRESHNESS_POLICIES.live_feeds.pireps,
    ));

    let tfrs_visible = session.map.layer_state().vectors.visible;
    let tfrs_collected_utc = live_feed_status_timestamp(session, "tfrs").or_else(|| {
        session
            .weather
            .runtime()
            .tfr_payload
            .as_ref()
            .and_then(|payload| payload.generated_at_utc)
    });
    let tfrs_loaded = session.weather.runtime().tfr_payload.is_some();
    invalidations.extend(sync_live_feed_product_status_record(
        session,
        tfrs_visible,
        tfrs_loaded,
        "tfrs",
        "TFR live feed unavailable: no current TFR product is loaded",
        tfrs_collected_utc,
        DATA_FRESHNESS_POLICIES.live_feeds.tfrs,
    ));

    let obstacles_visible = session.map.layer_state().vectors.visible;
    let obstacles_collected_utc = live_feed_status_timestamp(session, "obstacles").or_else(|| {
        session
            .weather
            .live_feeds()
            .product_state_manifest("obstacles")
            .and_then(json_generated_at_utc)
    });
    let obstacles_loaded = session.weather.runtime().obstacle_had.is_some();
    invalidations.extend(sync_live_feed_product_status_record(
        session,
        obstacles_visible,
        obstacles_loaded,
        "obstacles",
        "Obstacle live feed unavailable: no current obstacle product is loaded",
        obstacles_collected_utc,
        DATA_FRESHNESS_POLICIES.live_feeds.obstacles,
    ));

    dedupe_invalidations(&mut invalidations);
    invalidations
}

fn json_generated_at_utc(value: &serde_json::Value) -> Option<DateTime<Utc>> {
    value
        .get("generated_at_utc")
        .and_then(serde_json::Value::as_str)
        .and_then(parse_utc_instant)
}

#[derive(Debug, Clone)]
struct LiveFeedProductStatusSource {
    loaded: bool,
    collected_utc: Option<DateTime<Utc>>,
    loaded_version: Option<String>,
}

fn metar_live_feed_status_source(session: &UiSession) -> LiveFeedProductStatusSource {
    if let Some(payload) = session.weather.runtime().metar_payload.as_ref() {
        return LiveFeedProductStatusSource {
            loaded: true,
            collected_utc: live_feed_status_timestamp(session, "metars")
                .or(payload.generated_at_utc),
            loaded_version: Some(payload.version_label.clone()),
        };
    }
    LiveFeedProductStatusSource {
        loaded: false,
        collected_utc: None,
        loaded_version: session
            .weather
            .live_feeds()
            .product_loaded_version("metars")
            .map(str::to_string),
    }
}

