pub fn complete_cloud_provider_request_in_session(
    handle: u32,
    request_id: u64,
    response: CloudHttpResponse,
    now_epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    run_session_model_transaction(session, |session| {
        advance_session_wall_clock(session, now_epoch_ms);
        let updates =
            session
                .cloud
                .complete_provider_request(request_id, response, now_epoch_ms)?;
        if let Some(preferences) = updates.offline_package_preferences {
            session.packages.replace_preferences(preferences);
        }
        let mut invalidations = vec![UiInvalidation::SessionSnapshot];
        if let Some(remote_plan) = updates.remote_flight_plan {
            let navigation_active = session
                .flight_plan
                .active_plan()
                .as_ref()
                .is_some_and(|plan| plan.guidance.is_some());
            if navigation_active {
                session.cloud.set_pending_remote_flight_plan(remote_plan)?;
            } else {
                replace_session_flight_plan(session, remote_plan)?;
                sync_guidance_geometry_for_session(session, &crate::CoreDebugTimer::start())?;
                invalidations.extend([UiInvalidation::FlightPlanRoute, UiInvalidation::MapOverlay]);
            }
        }
        Ok(invalidations)
    })
}

enum SessionModelTransactionError {
    App(AppError),
    Had(HadReadError),
    Snapshot(SessionSnapshotProjectionError),
}

struct SessionModelTransactionCheckpoint {
    coordinator: SessionCoordinatorModel,
    projection_versions: SessionProjectionVersionState,
    settings: SettingsModelCheckpoint,
    flight_plan: FlightPlanModelCheckpoint,
    nav_data: NavDataModelCheckpoint,
    packages: PackageModelCheckpoint,
    cloud: CloudModelCheckpoint,
    data_status: DataStatusModelCheckpoint,
    situation: SituationModelCheckpoint,
    weather: WeatherModelCheckpoint,
    map: MapModelCheckpoint,
    pending_effect_count: usize,
}

impl SessionModelTransactionCheckpoint {
    fn capture(session: &UiSession) -> Self {
        Self {
            coordinator: session.coordinator.clone(),
            projection_versions: session.projection_versions.clone(),
            settings: session.settings.checkpoint_model(),
            flight_plan: session.flight_plan.checkpoint_model(),
            nav_data: session.nav_data.checkpoint_model(),
            packages: session.packages.checkpoint_model(),
            cloud: session.cloud.checkpoint_model(),
            data_status: session.data_status.checkpoint_model(),
            situation: session.situation.checkpoint_model(),
            weather: session.weather.checkpoint_model(),
            map: session.map.checkpoint_model(),
            pending_effect_count: session.runtime.pending_resource_effects.len(),
        }
    }

    fn rollback(self, session: &mut UiSession) {
        session.coordinator = self.coordinator;
        session.projection_versions = self.projection_versions;
        session.settings.rollback_model(self.settings);
        session.flight_plan.rollback_model(self.flight_plan);
        session.nav_data.rollback_model(self.nav_data);
        session.packages.rollback_model(self.packages);
        session.cloud.rollback_model(self.cloud);
        session.data_status.rollback_model(self.data_status);
        session.situation.rollback_model(self.situation);
        session.weather.rollback_model(self.weather);
        session.map.rollback_model(self.map);
        session
            .runtime
            .pending_resource_effects
            .truncate(self.pending_effect_count);
        session
            .diagnostics
            .transaction_rollback_count
            .fetch_add(1, Ordering::Relaxed);
    }
}

fn record_session_transaction_commit(session: &UiSession) {
    session
        .diagnostics
        .transaction_commit_count
        .fetch_add(1, Ordering::Relaxed);
}

fn run_durable_session_model_value_transaction<T>(
    session: &mut UiSession,
    mutate: impl FnOnce(&mut UiSession) -> AppResult<T>,
    should_write_persistence: impl FnOnce(&T) -> bool,
) -> AppResult<T> {
    let checkpoint = SessionModelTransactionCheckpoint::capture(session);
    let result = mutate(session).and_then(|value| {
        if should_write_persistence(&value) {
            write_session_persistence_to_storage(session)?;
        }
        Ok(value)
    });
    match result {
        Ok(value) => {
            record_session_transaction_commit(session);
            Ok(value)
        }
        Err(error) => {
            checkpoint.rollback(session);
            Err(error)
        }
    }
}

impl From<AppError> for SessionModelTransactionError {
    fn from(error: AppError) -> Self {
        Self::App(error)
    }
}

impl From<HadReadError> for SessionModelTransactionError {
    fn from(error: HadReadError) -> Self {
        Self::Had(error)
    }
}

impl From<SessionSnapshotProjectionError> for SessionModelTransactionError {
    fn from(error: SessionSnapshotProjectionError) -> Self {
        Self::Snapshot(error)
    }
}

fn run_session_model_transaction(
    session: &mut UiSession,
    mutate: impl FnOnce(&mut UiSession) -> Result<Vec<UiInvalidation>, SessionModelTransactionError>,
) -> AppResult<HadOperationOutcome> {
    run_session_model_transaction_with_persistence(session, mutate, true)
}

fn run_session_model_transaction_without_persistence(
    session: &mut UiSession,
    mutate: impl FnOnce(&mut UiSession) -> Result<Vec<UiInvalidation>, SessionModelTransactionError>,
) -> AppResult<HadOperationOutcome> {
    run_session_model_transaction_with_persistence(session, mutate, false)
}

fn run_session_model_transaction_with_persistence(
    session: &mut UiSession,
    mutate: impl FnOnce(&mut UiSession) -> Result<Vec<UiInvalidation>, SessionModelTransactionError>,
    write_persistence: bool,
) -> AppResult<HadOperationOutcome> {
    run_session_model_transaction_projecting(
        session,
        mutate,
        |session, previous_versions| {
            let update = try_project_session_update(session, previous_versions)?;
            serde_json::to_value(update).map_err(|error| {
                SessionModelTransactionError::App(AppError {
                    kind: AppErrorKind::Internal,
                    message: error.to_string(),
                })
            })
        },
        write_persistence,
    )
}

fn run_session_model_transaction_projecting(
    session: &mut UiSession,
    mutate: impl FnOnce(&mut UiSession) -> Result<Vec<UiInvalidation>, SessionModelTransactionError>,
    project: impl FnOnce(
        &mut UiSession,
        SessionProjectionVersions,
    ) -> Result<serde_json::Value, SessionModelTransactionError>,
    write_persistence: bool,
) -> AppResult<HadOperationOutcome> {
    let previous_versions = session.projection_versions.versions();
    let checkpoint = SessionModelTransactionCheckpoint::capture(session);
    let result = (|| {
        let invalidations = mutate(session)?;
        advance_session_revision(session);
        let result = project(session, previous_versions)?;
        if write_persistence {
            write_session_persistence_to_storage(session)?;
        }
        Ok::<_, SessionModelTransactionError>(HadOperationOutcome::complete_with_invalidations(
            result,
            invalidations,
        ))
    })();

    match result {
        Ok(outcome) => {
            record_session_transaction_commit(session);
            Ok(outcome)
        }
        Err(error) => {
            checkpoint.rollback(session);
            match error {
                SessionModelTransactionError::App(error) => Err(error),
                SessionModelTransactionError::Had(HadReadError::NeedPages(pages)) => {
                    Ok(HadOperationOutcome::NeedResources {
                        resources: nav_kv_page_resources(pages),
                    })
                }
                SessionModelTransactionError::Had(HadReadError::Fatal(message)) => Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message,
                }),
                SessionModelTransactionError::Snapshot(
                    SessionSnapshotProjectionError::NeedResources(resources),
                ) => Ok(HadOperationOutcome::NeedResources { resources }),
                SessionModelTransactionError::Snapshot(SessionSnapshotProjectionError::Had(
                    HadReadError::NeedPages(pages),
                )) => Ok(HadOperationOutcome::NeedResources {
                    resources: nav_kv_page_resources(pages),
                }),
                SessionModelTransactionError::Snapshot(SessionSnapshotProjectionError::Had(
                    HadReadError::Fatal(message),
                )) => Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message,
                }),
            }
        }
    }
}

pub fn perform_settings_action_in_session(
    handle: u32,
    action: UiSettingsAction,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    run_session_model_transaction(session, move |session| {
        if let Some((flag_id, enabled)) = debug_flag_settings_action(&action)? {
            apply_debug_flag(session, flag_id, enabled)?;
        } else {
            let display_policy_available = session
                .coordinator
                .platform_capabilities
                .display_policy
                .is_some();
            session
                .settings
                .perform_action(&action, display_policy_available)?;
        }
        Ok(vec![UiInvalidation::SessionSnapshot])
    })
}

