pub fn get_raster_tile_plan_in_session(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
) -> AppResult<RasterTilePlan> {
    get_raster_tile_plan_in_session_at_epoch_ms(handle, viewport, width_px, height_px, 0)
}

pub fn get_raster_tile_plan_in_session_at_epoch_ms(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
    epoch_ms: i64,
) -> AppResult<RasterTilePlan> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    advance_session_wall_clock(session, epoch_ms);
    let Some(catalog) = session.map.raster_catalog() else {
        return Err(AppError {
            kind: AppErrorKind::Internal,
            message: "session missing raster map catalog".to_string(),
        });
    };
    let options = crate::RasterTilePlanOptions {
        max_tile_display_multiplier: if session.coordinator.debug_state.fast_tiles {
            2.0
        } else {
            1.0
        },
        resource_mode: raster_resource_mode_for_policy(session.packages.resource_policy()),
        device_pixel_ratio: 1.0,
    };
    let catalog = raster_catalog_for_layer_state(
        catalog,
        session.map.layer_state(),
        session.packages.resource_policy(),
        session.packages.installed_package_ids(),
    );
    let mut plan =
        crate::raster_tile_plan_with_options(&catalog, &viewport, width_px, height_px, options);
    resolve_raster_tile_plan_public_urls(session, &mut plan)?;
    Ok(plan)
}

