fn perform_altitude_planner_action_in_session(
    handle: u32,
    action_uid: String,
) -> AppResult<HadOperationOutcome> {
    if let Some(selection) = crate::had_ops::planner_aircraft_from_action_uid(&action_uid) {
        let slot = session_slot(handle)?;
        let session_guard = slot.lock_running()?;
        let session = &*session_guard;
        let private_aircraft_definitions = session_aircraft_definitions(session)?;
        let cruise_altitude_ft = match crate::had_ops::planner_aircraft_selection_cruise_altitude(
            session_nav_kv_store(session)?,
            &private_aircraft_definitions,
            &selection,
            session_plan(session)?.cruise_altitude_ft,
        ) {
            Ok(cruise_altitude_ft) => cruise_altitude_ft,
            Err(HadReadError::NeedPages(pages)) => {
                return Ok(HadOperationOutcome::NeedResources {
                    resources: nav_kv_page_resources(pages),
                })
            }
            Err(HadReadError::Fatal(message)) => {
                return Err(AppError {
                    kind: AppErrorKind::InvalidCatalog,
                    message,
                })
            }
        };
        drop(session_guard);
        let Some(cruise_altitude_ft) = cruise_altitude_ft else {
            return Err(AppError {
                kind: AppErrorKind::UnsupportedOperation,
                message: "unknown or unavailable aircraft/profile selection".to_string(),
            });
        };
        return mutate_session_flight_plan_definition_controller(handle, |controller| {
            controller.plan_after_set_aircraft(selection, cruise_altitude_ft)
        });
    }
    if let Some(altitude_ft) = crate::had_ops::planner_altitude_from_action_uid(&action_uid) {
        return mutate_session_flight_plan_definition_controller(handle, |controller| {
            controller.plan_after_set_cruise_altitude(altitude_ft)
        });
    }

    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    if let Some(outcome) = preflight_session_snapshot_resources(session)? {
        return Ok(outcome);
    }
    session.coordinator.altitude_planner_wind_selection = match action_uid.as_str() {
        crate::had_ops::SELECT_NO_WIND_ACTION_UID => AltitudePlannerWindSelection::NoWind,
        crate::had_ops::SELECT_GFS_WIND_ACTION_UID
            if session.weather.runtime().forecast_atmosphere.is_some() =>
        {
            AltitudePlannerWindSelection::Gfs
        }
        _ => {
            return Err(AppError {
                kind: AppErrorKind::UnsupportedOperation,
                message: format!("unknown or unavailable altitude-planner action: {action_uid}"),
            })
        }
    };
    changed_session_update_outcome(session)
}

fn session_local_time_zone(session: &UiSession) -> AppResult<Tz> {
    session
        .coordinator
        .platform_capabilities
        .local_time_zone
        .as_deref()
        .unwrap_or("UTC")
        .parse::<Tz>()
        .map_err(|_| AppError {
            kind: AppErrorKind::InvalidCatalog,
            message: "configured platform local time zone is invalid".to_string(),
        })
}

fn set_altitude_planner_departure_input_in_session(
    handle: u32,
    field: crate::AltitudePlannerDepartureInputField,
    input: String,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let plan = session_plan(session)?;
    if plan.guidance.is_some() {
        return Err(AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: "active navigation always models departure from ownship now".to_string(),
        });
    }
    let parsed = crate::parse_altitude_planner_departure_input(
        field,
        &input,
        session.coordinator.wall_clock_epoch_ms,
        session.coordinator.time_display_mode,
        session_local_time_zone(session)?,
    )
    .map_err(|message| AppError {
        kind: AppErrorKind::InvalidFlightPlan,
        message,
    })?;
    let mut next = plan;
    next.planned_departure_time_epoch_ms = parsed.departure_time_epoch_ms;
    let previous_basis = session.coordinator.time_display_mode;
    session.coordinator.time_display_mode = parsed.basis;
    match commit_session_flight_plan_edit_with_invalidations_outcome(session, next) {
        Ok(outcome) => Ok(outcome),
        Err(error) => {
            session.coordinator.time_display_mode = previous_basis;
            Err(error)
        }
    }
}

pub fn perform_time_display_action_in_session(
    handle: u32,
    action_id: String,
) -> AppResult<HadOperationOutcome> {
    if action_id != crate::TOGGLE_TIME_DISPLAY_MODE_ACTION_ID {
        return Err(AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: format!("unknown time-display action: {action_id}"),
        });
    }
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    session.coordinator.time_display_mode = session.coordinator.time_display_mode.toggled();
    changed_session_update_outcome(session)
}

