pub(crate) fn insert_airway_at_flight_plan_row_in_session(
    handle: u32,
    row_uid: String,
    selection: AirwayPresentationSelection,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let plan = session_plan(session)?;
    let ui = crate::project_ui_state(&plan);
    let row = ui
        .display_rows
        .iter()
        .find(|row| row.uid == row_uid)
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: format!("flight-plan airway insert target is stale: {row_uid}"),
        })?;
    if row.origin_anchor.is_none() {
        return Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: "airway insert row has no origin anchor".to_string(),
        });
    }
    let component_uid = row.component_uid.as_deref().ok_or_else(|| AppError {
        kind: AppErrorKind::InvalidFlightPlan,
        message: "airway insert row has no route component uid".to_string(),
    })?;
    let start_component_index = plan
        .route_component_uids
        .iter()
        .position(|uid| uid == component_uid)
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: format!("airway insert target component is stale: {component_uid}"),
        })?;
    let end_component_index = if row.destination_anchor.is_some() {
        Some(start_component_index + 1)
    } else {
        None
    };
    let store = session_nav_kv_store(session)?;
    let materialized =
        match materialize_airway_presentation_selection(store, start_component_index, selection) {
            Ok(materialized) => materialized,
            Err(HadReadError::NeedPages(pages)) => {
                return Ok(HadOperationOutcome::NeedResources {
                    resources: nav_kv_page_resources(pages),
                })
            }
            Err(HadReadError::Fatal(message)) => {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message,
                });
            }
        };
    let mutation = crate::insert_airway_materialized(
        &plan,
        start_component_index,
        end_component_index,
        materialized.airway,
        materialized.resolved_legs,
    )?;
    commit_session_flight_plan_edit_with_invalidations_outcome(session, mutation)
}

pub(crate) fn select_procedure_at_flight_plan_row_in_session(
    handle: u32,
    row_uid: String,
    airport_id: String,
    procedure_id: String,
    kind: ProcedureKind,
    runway_transition: Option<String>,
    enroute_transition: Option<String>,
) -> AppResult<HadOperationOutcome> {
    let started = crate::CoreDebugTimer::start();
    let trace = serde_json::json!({
        "row_uid": &row_uid,
        "airport_id": &airport_id,
        "procedure_id": &procedure_id,
        "kind": &kind,
        "runway_transition": runway_transition.as_ref(),
        "enroute_transition": enroute_transition.as_ref(),
    });
    crate::core_debug_log(
        "plan.procedure.select.core_phase",
        &serde_json::json!({
            "phase": "start",
            "trace": trace,
        }),
    );
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let plan = session_plan(session)?;
    let ui = crate::project_ui_state(&plan);
    crate::core_debug_log(
        "plan.procedure.select.core_phase",
        &serde_json::json!({
            "phase": "project_ui_state",
            "elapsed_ms": started.elapsed_ms(),
        }),
    );
    let row = ui
        .display_rows
        .iter()
        .find(|row| row.uid == row_uid)
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: format!("flight-plan procedure target is stale: {row_uid}"),
        })?;
    let row_airport_id = row.chart_airport_id.as_deref().ok_or_else(|| AppError {
        kind: AppErrorKind::InvalidFlightPlan,
        message: "procedure target row has no airport".to_string(),
    })?;
    if row_airport_id != airport_id {
        return Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: format!(
                "procedure airport mismatch: row has {row_airport_id}, requested {airport_id}"
            ),
        });
    }
    let component_uid = row.component_uid.as_deref().ok_or_else(|| AppError {
        kind: AppErrorKind::InvalidFlightPlan,
        message: "procedure target row has no route component uid".to_string(),
    })?;
    let airport_component_index = plan
        .route_component_uids
        .iter()
        .position(|uid| uid == component_uid)
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: format!("procedure target component is stale: {component_uid}"),
        })?;
    let is_departure = kind == ProcedureKind::Sid;
    if is_departure && airport_component_index != 0 {
        return Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message: "departures can be selected at the flight-plan origin only".to_string(),
        });
    }
    let replace_component_index =
        crate::attached_procedure_component_index(&plan, airport_component_index, kind.clone());
    crate::core_debug_log(
        "plan.procedure.select.core_phase",
        &serde_json::json!({
            "phase": "target_resolved",
            "airport_component_index": airport_component_index,
            "replace_component_index": replace_component_index,
            "elapsed_ms": started.elapsed_ms(),
        }),
    );
    let store = session_nav_kv_store(session)?;
    let procedure_component_index =
        crate::procedure_component_index_for_load(&plan, airport_component_index, kind.clone())?;
    let materialize_started = crate::CoreDebugTimer::start();
    let built = match materialize_procedure(
        store,
        &airport_id,
        &procedure_id,
        kind.clone(),
        runway_transition.as_deref(),
        enroute_transition.as_deref(),
        procedure_component_index,
    ) {
        Ok(built) => {
            crate::core_debug_log(
                "plan.procedure.select.core_phase",
                &serde_json::json!({
                    "phase": "materialize_done",
                    "elapsed_ms": materialize_started.elapsed_ms(),
                    "total_ms": started.elapsed_ms(),
                }),
            );
            built
        }
        Err(HadReadError::NeedPages(pages)) => {
            crate::core_debug_log(
                "plan.procedure.select.core_phase",
                &serde_json::json!({
                    "phase": "materialize_need_pages",
                    "resource_count": pages.len(),
                    "pages": pages,
                    "elapsed_ms": materialize_started.elapsed_ms(),
                    "total_ms": started.elapsed_ms(),
                }),
            );
            return Ok(HadOperationOutcome::NeedResources {
                resources: nav_kv_page_resources(pages),
            });
        }
        Err(HadReadError::Fatal(message)) => {
            return Err(AppError {
                kind: AppErrorKind::InvalidFlightPlan,
                message,
            });
        }
    };
    let mutation_started = crate::CoreDebugTimer::start();
    let mutation = if let Some(replace_component_index) = replace_component_index {
        crate::replace_procedure_materialized(&plan, replace_component_index, built)?
    } else if is_departure {
        crate::insert_departure_materialized(&plan, airport_component_index, built)?
    } else {
        crate::insert_procedure_materialized(
            &plan,
            airport_component_index.saturating_sub(1),
            airport_component_index,
            built,
        )?
    };
    crate::core_debug_log(
        "plan.procedure.select.core_phase",
        &serde_json::json!({
            "phase": "mutation_done",
            "elapsed_ms": mutation_started.elapsed_ms(),
            "total_ms": started.elapsed_ms(),
        }),
    );
    let commit_started = crate::CoreDebugTimer::start();
    let outcome = commit_session_flight_plan_edit_with_invalidations_outcome(session, mutation);
    crate::core_debug_log(
        "plan.procedure.select.core_phase",
        &serde_json::json!({
            "phase": "commit_done",
            "ok": outcome.is_ok(),
            "elapsed_ms": commit_started.elapsed_ms(),
            "total_ms": started.elapsed_ms(),
        }),
    );
    outcome
}

pub(crate) fn load_plate_procedure_in_session(
    handle: u32,
    load_id: String,
) -> AppResult<HadOperationOutcome> {
    let command: ProcedureLoadCommand = serde_json::from_str(&load_id).map_err(|err| AppError {
        kind: AppErrorKind::InvalidFlightPlan,
        message: format!("invalid procedure load id: {err}"),
    })?;
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let mut plan = session_plan(session)?;
    let is_departure = command.kind == ProcedureKind::Sid;
    let airport_component_index = match &command.target {
        ProcedureLoadPlanTarget::ExistingOrigin { row_uid } => {
            if !is_departure {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: "only a departure may use an origin load target".to_string(),
                });
            }
            let ui = crate::project_ui_state(&plan);
            let row = ui
                .display_rows
                .iter()
                .find(|row| row.uid == *row_uid)
                .ok_or_else(|| AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!("procedure load target row is stale: {row_uid}"),
                })?;
            if row.chart_airport_id.as_deref() != Some(command.airport_id.as_str())
                || row.component_index != Some(0)
            {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!(
                        "departure load target is no longer the origin: {}",
                        command.airport_id
                    ),
                });
            }
            0
        }
        ProcedureLoadPlanTarget::PrependOrigin => {
            if !is_departure {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: "only a departure may prepend a flight-plan origin".to_string(),
                });
            }
            plan = crate::prepend_plate_origin(&plan, &command.airport_id)?;
            0
        }
        ProcedureLoadPlanTarget::ExistingDestination { row_uid } => {
            if is_departure {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: "a departure may not use a destination load target".to_string(),
                });
            }
            let ui = crate::project_ui_state(&plan);
            let row = ui
                .display_rows
                .iter()
                .find(|row| row.uid == *row_uid)
                .ok_or_else(|| AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!("procedure load target row is stale: {row_uid}"),
                })?;
            let row_airport_id = row.chart_airport_id.as_deref().ok_or_else(|| AppError {
                kind: AppErrorKind::InvalidFlightPlan,
                message: "procedure load target row has no airport".to_string(),
            })?;
            if row_airport_id != command.airport_id {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!(
                        "procedure load airport mismatch: row has {row_airport_id}, requested {}",
                        command.airport_id
                    ),
                });
            }
            let component_uid = row.component_uid.as_deref().ok_or_else(|| AppError {
                kind: AppErrorKind::InvalidFlightPlan,
                message: "procedure load target row has no route component uid".to_string(),
            })?;
            let component_index = plan
                .route_component_uids
                .iter()
                .position(|uid| uid == component_uid)
                .ok_or_else(|| AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!("procedure load target component is stale: {component_uid}"),
                })?;
            if component_index + 1 != plan.route_components.len() {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: format!(
                        "procedure load target is no longer the destination: {}",
                        command.airport_id
                    ),
                });
            }
            component_index
        }
        ProcedureLoadPlanTarget::AppendDestination => {
            if is_departure {
                return Err(AppError {
                    kind: AppErrorKind::InvalidFlightPlan,
                    message: "a departure may not append a flight-plan destination".to_string(),
                });
            }
            plan = crate::append_plate_destination(&plan, &command.airport_id)?;
            plan.route_components.len() - 1
        }
    };
    let replace_component_index = crate::attached_procedure_component_index(
        &plan,
        airport_component_index,
        command.kind.clone(),
    );
    let store = session_nav_kv_store(session)?;
    let procedure_component_index = crate::procedure_component_index_for_load(
        &plan,
        airport_component_index,
        command.kind.clone(),
    )?;
    let mut built = match materialize_procedure(
        store,
        &command.airport_id,
        &command.procedure_id,
        command.kind.clone(),
        command.runway_transition.as_deref(),
        command.enroute_transition.as_deref(),
        procedure_component_index,
    ) {
        Ok(built) => built,
        Err(HadReadError::NeedPages(pages)) => {
            return Ok(HadOperationOutcome::NeedResources {
                resources: nav_kv_page_resources(pages),
            })
        }
        Err(HadReadError::Fatal(message)) => {
            return Err(AppError {
                kind: AppErrorKind::InvalidFlightPlan,
                message,
            });
        }
    };
    if let Some(display_label) = command
        .display_label
        .as_deref()
        .map(str::trim)
        .filter(|label| !label.is_empty())
    {
        built.procedure.display_label = Some(display_label.to_string());
    }
    let mutation = if let Some(replace_component_index) = replace_component_index {
        crate::replace_procedure_materialized(&plan, replace_component_index, built)?
    } else if is_departure {
        crate::insert_departure_materialized(&plan, airport_component_index, built)?
    } else {
        crate::insert_procedure_materialized(
            &plan,
            airport_component_index.saturating_sub(1),
            airport_component_index,
            built,
        )?
    };
    commit_session_flight_plan_edit_with_invalidations_outcome(session, mutation)
}

fn activate_direct_to_nav_ref_in_session_outcome(
    handle: u32,
    target: NavRef,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let from_position = session
        .situation
        .ownship()
        .render
        .position
        .ok_or_else(|| AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: "cannot activate direct-to without ownship position".to_string(),
        })?;
    let next_plan = session
        .flight_plan
        .plan_after_direct_to(from_position, target)?;
    commit_session_navigation_update_with_invalidations_outcome(session, next_plan)
}

pub fn perform_status_action_in_session(
    handle: u32,
    action_id: String,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    match session
        .data_status
        .perform_action(&action_id)
        .ok_or_else(|| invalid_status_action(&action_id))?
    {
        DataStatusActionIntent::ProjectionChanged | DataStatusActionIntent::ReloadApplication => {}
    }
    changed_session_update_outcome(session)
}

fn invalid_status_action(action_id: &str) -> AppError {
    AppError {
        kind: AppErrorKind::UnsupportedOperation,
        message: format!("unknown status action: {action_id}"),
    }
}

pub(crate) fn perform_flight_plan_row_action_in_session(
    handle: u32,
    row_uid: String,
    action_uid: String,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let (next_plan, domain) = session.flight_plan.plan_after_row_action(
        &row_uid,
        &action_uid,
        session.situation.ownship().render.position,
    )?;
    match domain {
        crate::flight_plan_controller::FlightPlanMutationDomain::Definition => {
            commit_session_flight_plan_edit_with_invalidations_outcome(session, next_plan)
        }
        crate::flight_plan_controller::FlightPlanMutationDomain::Navigation => {
            commit_session_navigation_update_with_invalidations_outcome(session, next_plan)
        }
    }
}

pub(crate) fn restore_direct_to_in_session(handle: u32) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let next_plan = session.flight_plan.plan_after_restore_direct_to()?;
    commit_session_navigation_update_with_invalidations_outcome(session, next_plan)
}

pub fn attach_nav_kv_store_to_session(
    handle: u32,
    store_id: u32,
    store: &NavKvStore,
) -> AppResult<()> {
    attach_nav_kv_store_to_session_with_open_result(handle, store_id, store, None)
}

pub fn attach_nav_kv_store_to_session_with_open_result(
    handle: u32,
    store_id: u32,
    store: &NavKvStore,
    open_result: Option<&NavDbOpenResult>,
) -> AppResult<()> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    session.nav_data.attach(store_id, store, open_result);
    session.flight_plan.invalidate_nav_data();
    session.weather.invalidate_nav_data();
    rebuild_metar_tile_cache(session);
    sync_cycle_product_freshness_status_records(session);
    Ok(())
}

pub fn advance_nav_kv_store_in_session_with_open_result(
    handle: u32,
    store_id: u32,
    store: &NavKvStore,
    open_result: &NavDbOpenResult,
    installed_package_ids: Vec<String>,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let live = &mut *session_guard;
    let previous_versions = live.projection_versions.versions();
    if live.nav_data.advance_blocked() {
        let active_artifact_filename = live
            .nav_data
            .active_artifact()
            .map(|artifact| artifact.filename.clone());
        let result = NavDbAdvanceResult {
            disposition: NavDbAdvanceDisposition::Rejected,
            session_update: None,
            active_artifact_filename: active_artifact_filename.clone(),
            retained_artifact_filenames: active_artifact_filename.into_iter().collect(),
            rejection_reason: Some("NAVDB advance is blocked until application reload".to_string()),
        };
        return Ok(HadOperationOutcome::complete(
            serde_json::to_value(result).map_err(|err| AppError {
                kind: AppErrorKind::Internal,
                message: err.to_string(),
            })?,
        ));
    }
    let previous_filename = live
        .nav_data
        .active_artifact()
        .map(|artifact| artifact.filename.clone());
    let nav_db_changed = previous_filename.as_deref() != Some(&open_result.selected_filename);
    let selected_map_id = live
        .map
        .raster_catalog()
        .map(|catalog| catalog.selected_map_id.clone());
    let selected_family_id = live.map.raster_catalog().and_then(|catalog| {
        catalog
            .family_options
            .iter()
            .find(|family| family.active)
            .map(|family| family.id.clone())
    });
    let previous_map_model = live.map.checkpoint_model();
    let previous_situation_model = live.situation.checkpoint_model();
    let previous_flight_plan_model = live.flight_plan.checkpoint_model();
    let previous_package_model = live.packages.checkpoint_model();
    let previous_data_status_model = live.data_status.checkpoint_model();

    let mut candidate = UiSession {
        coordinator: live.coordinator.clone(),
        projection_versions: live.projection_versions.clone(),
        settings: std::mem::take(&mut live.settings),
        flight_plan: std::mem::take(&mut live.flight_plan),
        nav_data: live.nav_data.candidate(store_id, store, open_result),
        packages: std::mem::take(&mut live.packages),
        cloud: std::mem::take(&mut live.cloud),
        data_status: std::mem::take(&mut live.data_status),
        situation: std::mem::take(&mut live.situation),
        weather: std::mem::take(&mut live.weather),
        map: std::mem::take(&mut live.map),
        runtime: std::mem::take(&mut live.runtime),
        diagnostics: Arc::clone(&live.diagnostics),
    };
    candidate
        .packages
        .set_installed_package_ids(installed_package_ids);
    candidate
        .packages
        .insert_installed_package_id(open_result.selected_package_id.clone());
    candidate.map.invalidate_nav_data();
    candidate.weather.invalidate_nav_data();
    rebuild_metar_tile_cache(&mut candidate);
    mark_cycle_product_freshness_dirty(&mut candidate);

    let rebuild = (|| -> Result<UiSessionUpdate, SessionSnapshotProjectionError> {
        if let Some(plan) = candidate.flight_plan.active_plan() {
            let rebuilt_plan = crate::had_ops::rebuild_flight_plan_from_nav_kv(store, plan)?;
            replace_session_flight_plan(&mut candidate, rebuilt_plan)
                .map_err(HadReadError::from)?;
        }
        candidate
            .map
            .replace_raster_catalog(Some(crate::had_ops::raster_map_catalog_from_nav_kv(
                store,
                selected_map_id.as_deref(),
                selected_family_id.as_deref(),
            )?));
        ensure_vector_manifest_loaded(&mut candidate)?;
        if !candidate
            .coordinator
            .chart_page_state
            .selected_chart_id
            .is_empty()
        {
            read_chart_asset_by_id(
                store,
                &candidate.coordinator.chart_page_state.selected_chart_id,
            )?;
        }
        for airport_id in [
            candidate
                .coordinator
                .chart_page_state
                .selected_airport_id
                .as_str(),
            candidate
                .coordinator
                .chart_page_state
                .plate_target_airport_id
                .as_deref()
                .unwrap_or_default(),
        ] {
            if !airport_id.is_empty() {
                let _ = airport_plate_availability(store, airport_id)?;
            }
        }
        sync_guidance_geometry_for_session(&mut candidate, &crate::CoreDebugTimer::start())?;
        sync_cycle_product_freshness_status_records(&mut candidate);
        clear_data_status_record(&mut candidate, NAV_DB_ADVANCE_STATUS_ID);
        advance_session_revision(&mut candidate);
        try_project_session_update(&mut candidate, previous_versions)
    })();

    match rebuild {
        Ok(update) => {
            let active_artifact_filename = Some(open_result.selected_filename.clone());
            *live = candidate;
            let result = NavDbAdvanceResult {
                disposition: NavDbAdvanceDisposition::Adopted,
                session_update: Some(update),
                active_artifact_filename: active_artifact_filename.clone(),
                retained_artifact_filenames: active_artifact_filename.into_iter().collect(),
                rejection_reason: None,
            };
            let mut invalidations = vec![
                UiInvalidation::SessionSnapshot,
                UiInvalidation::RasterTiles,
                UiInvalidation::MapOverlay,
                UiInvalidation::TerrainOverlay,
                UiInvalidation::FlightPlanRoute,
            ];
            if nav_db_changed {
                invalidations.insert(0, UiInvalidation::NavData);
            }
            Ok(HadOperationOutcome::complete_with_invalidations(
                serde_json::to_value(result).map_err(|err| AppError {
                    kind: AppErrorKind::Internal,
                    message: err.to_string(),
                })?,
                invalidations,
            ))
        }
        Err(SessionSnapshotProjectionError::NeedResources(resources)) => {
            live.settings = candidate.settings;
            candidate
                .packages
                .rollback_model(previous_package_model.clone());
            live.packages = candidate.packages;
            live.cloud = candidate.cloud;
            candidate
                .data_status
                .rollback_model(previous_data_status_model.clone());
            live.data_status = candidate.data_status;
            candidate
                .flight_plan
                .rollback_model(previous_flight_plan_model);
            live.flight_plan = candidate.flight_plan;
            candidate.situation.rollback_model(previous_situation_model);
            live.situation = candidate.situation;
            live.weather = candidate.weather;
            candidate.map.rollback_model(previous_map_model);
            candidate.map.clear_runtime_caches();
            live.map = candidate.map;
            live.runtime = candidate.runtime;
            live.runtime.pending_resource_effects.clear();
            live.weather.invalidate_nav_data();
            rebuild_metar_tile_cache(live);
            Ok(HadOperationOutcome::NeedResources { resources })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::NeedPages(pages))) => {
            live.settings = candidate.settings;
            candidate.packages.rollback_model(previous_package_model);
            live.packages = candidate.packages;
            live.cloud = candidate.cloud;
            candidate
                .data_status
                .rollback_model(previous_data_status_model.clone());
            live.data_status = candidate.data_status;
            candidate
                .flight_plan
                .rollback_model(previous_flight_plan_model);
            live.flight_plan = candidate.flight_plan;
            candidate.situation.rollback_model(previous_situation_model);
            live.situation = candidate.situation;
            live.weather = candidate.weather;
            candidate.map.rollback_model(previous_map_model);
            candidate.map.clear_runtime_caches();
            live.map = candidate.map;
            live.runtime = candidate.runtime;
            live.runtime.pending_resource_effects.clear();
            live.weather.invalidate_nav_data();
            rebuild_metar_tile_cache(live);
            Ok(HadOperationOutcome::NeedResources {
                resources: nav_kv_page_resources(pages),
            })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::Fatal(message))) => {
            let candidate_label = open_result
                .selected_cycle
                .as_deref()
                .unwrap_or(&open_result.selected_filename);
            let mut warning = DataStatusRecord::new(
                NAV_DB_ADVANCE_STATUS_ID,
                "NAV DB",
                Some("ADVANCE FAILED".to_string()),
                UiStatusSeverity::Warning,
                true,
                format!(
                    "Could not advance to new NAVDB {candidate_label}. Reload application when not flying. {message}"
                ),
            )
            .with_action(UiStatusAction {
                id: RELOAD_APPLICATION_ACTION_ID.to_string(),
                label: "Reload application".to_string(),
                enabled: true,
                style: UiStatusActionStyle::Normal,
            });
            warning.hushable = false;
            live.settings = candidate.settings;
            live.packages = candidate.packages;
            live.cloud = candidate.cloud;
            candidate
                .data_status
                .rollback_model(previous_data_status_model);
            live.data_status = candidate.data_status;
            candidate
                .flight_plan
                .rollback_model(previous_flight_plan_model);
            live.flight_plan = candidate.flight_plan;
            candidate.situation.rollback_model(previous_situation_model);
            live.situation = candidate.situation;
            live.weather = candidate.weather;
            candidate.map.rollback_model(previous_map_model);
            candidate.map.clear_runtime_caches();
            live.map = candidate.map;
            live.runtime = candidate.runtime;
            live.runtime.pending_resource_effects.clear();
            live.weather.invalidate_nav_data();
            rebuild_metar_tile_cache(live);
            live.nav_data.block_advance();
            let active_package_id = live
                .nav_data
                .active_artifact()
                .map(|artifact| artifact.package_id.clone());
            if let Some(active_package_id) = active_package_id {
                live.packages.insert_installed_package_id(active_package_id);
            }
            upsert_data_status_record(live, warning);
            advance_session_revision(live);
            let update = try_project_session_update(live, previous_versions).map_err(|error| AppError {
                kind: AppErrorKind::InvalidFlightPlan,
                message: match error {
                    SessionSnapshotProjectionError::NeedResources(resources) => format!(
                        "NAVDB advance failed and the retained session needs resources {resources:?}: {message}"
                    ),
                    SessionSnapshotProjectionError::Had(HadReadError::NeedPages(pages)) => format!(
                        "NAVDB advance failed and the retained session needs pages {pages:?}: {message}"
                    ),
                    SessionSnapshotProjectionError::Had(HadReadError::Fatal(snapshot_message)) => format!(
                        "NAVDB advance failed ({message}); retained snapshot failed: {snapshot_message}"
                    ),
                },
            })?;
            let active_artifact_filename = previous_filename;
            let result = NavDbAdvanceResult {
                disposition: NavDbAdvanceDisposition::Rejected,
                session_update: Some(update),
                active_artifact_filename: active_artifact_filename.clone(),
                retained_artifact_filenames: active_artifact_filename.into_iter().collect(),
                rejection_reason: Some(message),
            };
            Ok(HadOperationOutcome::complete_with_invalidations(
                serde_json::to_value(result).map_err(|err| AppError {
                    kind: AppErrorKind::Internal,
                    message: err.to_string(),
                })?,
                vec![UiInvalidation::SessionSnapshot],
            ))
        }
    }
}

pub fn maintain_nav_db_in_session_at_epoch_ms(
    handle: u32,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let previous_versions = session.projection_versions.versions();
    advance_session_wall_clock(session, epoch_ms);
    mark_cycle_product_freshness_dirty_if_deadline_due(session);
    sync_cycle_product_freshness_status_records_if_needed(session);

    let decision = session
        .nav_data
        .maintenance_decision(&session.packages, session.coordinator.wall_clock_epoch_ms)
        .map_err(|message| AppError {
            kind: AppErrorKind::InvalidManifest,
            message,
        })?;
    match decision {
        NavDataMaintenanceDecision::None => {
            nav_db_maintenance_outcome(session, NavDbMaintenanceAction::None, previous_versions)
        }
        NavDataMaintenanceDecision::AttemptAdvance => nav_db_maintenance_outcome(
            session,
            NavDbMaintenanceAction::AttemptAdvance,
            previous_versions,
        ),
        NavDataMaintenanceDecision::NeedResources(resources) => {
            Ok(HadOperationOutcome::NeedResources { resources })
        }
    }
}

fn nav_db_maintenance_outcome(
    session: &mut UiSession,
    action: NavDbMaintenanceAction,
    previous_versions: SessionProjectionVersions,
) -> AppResult<HadOperationOutcome> {
    advance_session_revision(session);
    let update =
        try_project_session_update(session, previous_versions).map_err(|error| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("NAVDB maintenance snapshot failed: {error:?}"),
        })?;
    let result = NavDbMaintenanceResult {
        action,
        session_update: Some(update),
    };
    Ok(HadOperationOutcome::complete(
        serde_json::to_value(result).map_err(|err| AppError {
            kind: AppErrorKind::Internal,
            message: err.to_string(),
        })?,
    ))
}

pub fn insert_nav_kv_page_for_attached_sessions(store_id: u32, page_index: u32, page_bytes: &[u8]) {
    let slots = lock_session_registry()
        .values()
        .cloned()
        .collect::<Vec<_>>();
    for slot in slots {
        let Ok(mut session_guard) = slot.lock_running() else {
            continue;
        };
        let session = &mut *session_guard;
        if session
            .nav_data
            .insert_page_if_attached(store_id, page_index, page_bytes)
        {
            if session
                .coordinator
                .cycle_product_freshness
                .missing_nav_kv_pages
                .remove(&page_index)
            {
                session.coordinator.cycle_product_freshness.dirty = true;
            }
        }
    }
}

pub fn debug_drop_nav_kv_pages_for_attached_sessions(store_id: u32) {
    let slots = lock_session_registry()
        .values()
        .cloned()
        .collect::<Vec<_>>();
    for slot in slots {
        let Ok(mut session_guard) = slot.lock_running() else {
            continue;
        };
        let session = &mut *session_guard;
        session.nav_data.clear_pages_if_attached(store_id);
    }
}

