pub fn install_prepared_live_feed_cache_product_in_session(
    handle: u32,
    installed: &crate::LiveFeedInstalledState,
    prepared_bytes: &[u8],
) -> AppResult<HadOperationOutcome> {
    let envelope = crate::decode_prepared_live_feed(prepared_bytes)?;
    if envelope.product != installed.product
        || envelope.version != installed.version
        || envelope.state_sha256 != installed.state_sha256
    {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "prepared live-feed projection {}/{}/{} does not match installed {}/{}/{}",
                envelope.product,
                envelope.version,
                envelope.state_sha256,
                installed.product,
                installed.version,
                installed.state_sha256
            ),
        });
    }
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    install_prepared_live_feed(session, envelope.payload)?;
    session
        .weather
        .live_feeds_mut()
        .mark_durable_product_loaded(
            installed.product.clone(),
            installed.version.clone(),
            installed.state_sha256.clone(),
            installed.collected_at_utc.clone(),
            installed_live_feed_state_manifest(installed),
        );
    sync_live_feed_overlay_status_records(session);
    changed_session_update_outcome(session)
}

fn install_live_feed_installed_state(
    session: &mut UiSession,
    installed: &crate::LiveFeedInstalledState,
) -> AppResult<()> {
    match (&*installed.product, &installed.payload) {
        ("metars", crate::LiveFeedInstalledPayload::Json { bytes }) => {
            let payload: MetarProductPayload =
                serde_json::from_slice(bytes).map_err(|err| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed METAR live feed: {err}"),
                })?;
            session.weather.runtime_mut().metar_payload = Some(payload);
            session.weather.runtime_mut().prepared_metar_tiles = None;
            rebuild_metar_tile_cache(session);
            clear_data_status_record(session, LIVE_FEED_METARS_STATUS_ID);
        }
        ("pireps", crate::LiveFeedInstalledPayload::Json { bytes }) => {
            let payload: crate::PirepProductPayload =
                serde_json::from_slice(bytes).map_err(|err| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed PIREP live feed: {err}"),
                })?;
            session.weather.runtime_mut().pirep_payload = Some(payload);
            session.weather.runtime_mut().prepared_pirep_tiles = None;
            rebuild_metar_tile_cache(session);
            clear_data_status_record(session, LIVE_FEED_PIREPS_STATUS_ID);
        }
        ("tafs", crate::LiveFeedInstalledPayload::Json { bytes }) => {
            let payload: TafProductPayload =
                serde_json::from_slice(bytes).map_err(|err| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed TAF live feed: {err}"),
                })?;
            session.weather.runtime_mut().taf_payload = Some(payload);
            let status_id = live_feed_unavailable_status_record("tafs", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
        ("tfrs", crate::LiveFeedInstalledPayload::Json { bytes }) => {
            let payload: TfrProductPayload =
                serde_json::from_slice(bytes).map_err(|err| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed TFR live feed: {err}"),
                })?;
            session.weather.runtime_mut().tfr_payload = Some(payload);
            clear_data_status_record(session, LIVE_FEED_TFRS_STATUS_ID);
        }
        ("notams", crate::LiveFeedInstalledPayload::NotamResources { .. }) => {
            return Err(AppError {
                kind: AppErrorKind::InvalidManifest,
                message: "NOTAM resources must be prepared off-thread before session install"
                    .to_string(),
            });
        }
        (
            "obstacles",
            crate::LiveFeedInstalledPayload::NavKv {
                manifest,
                root,
                pages,
            },
        ) => {
            let manifest_value: serde_json::Value =
                serde_json::from_slice(manifest).map_err(|err| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed obstacle live feed: {err}"),
                })?;
            let store = nav_kv_store_from_installed_live_feed(
                "obstacles",
                &installed.version,
                &installed.state_sha256,
                root,
                pages,
            )?;
            install_live_obstacle_had_with_store(
                session,
                manifest_value,
                installed.version.clone(),
                format!(
                    "android-installed/obstacles/{}/manifest.json",
                    installed.version
                ),
                Some(store),
            )?;
        }
        (
            "nexrad",
            crate::LiveFeedInstalledPayload::NexradPackage {
                manifest,
                package_blob_sha256,
                ..
            },
        ) => {
            let installed = installed_nexrad_descriptor(
                &installed.version,
                &installed.state_sha256,
                manifest,
                package_blob_sha256,
            )?;
            session
                .weather
                .runtime_mut()
                .nexrad_installed
                .insert(installed.version.clone(), installed);
            while session.weather.runtime().nexrad_installed.len() > NEXRAD_FRAME_WINDOW_SIZE {
                let Some(oldest) = session
                    .weather
                    .runtime()
                    .nexrad_installed
                    .values()
                    .min_by(|left, right| {
                        json_observed_at_utc(&left.manifest)
                            .cmp(&json_observed_at_utc(&right.manifest))
                            .then_with(|| left.version.cmp(&right.version))
                    })
                    .map(|installed| installed.version.clone())
                else {
                    break;
                };
                session
                    .weather
                    .runtime_mut()
                    .nexrad_installed
                    .remove(&oldest);
            }
            let retained_versions = session
                .weather
                .runtime()
                .nexrad_installed
                .keys()
                .cloned()
                .collect::<HashSet<_>>();
            session
                .weather
                .runtime_mut()
                .nexrad_tile_cache
                .retain(|src, _| {
                    nexrad_installed_member(src)
                        .is_some_and(|(version, _)| retained_versions.contains(&version))
                });
            clear_data_status_record(session, LIVE_FEED_NEXRAD_STATUS_ID);
        }
        (
            "winds-aloft",
            crate::LiveFeedInstalledPayload::NavKv {
                manifest,
                root,
                pages,
            },
        ) => {
            let manifest: product_contracts::AtmosphereManifest = serde_json::from_slice(manifest)
                .map_err(|error| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("failed to parse installed atmosphere manifest: {error}"),
                })?;
            if manifest.version_label != installed.version
                || manifest.state_sha256 != installed.state_sha256
            {
                return Err(AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!(
                        "atmosphere manifest {}/{} did not match installed {}/{}",
                        manifest.version_label,
                        manifest.state_sha256,
                        installed.version,
                        installed.state_sha256
                    ),
                });
            }
            let store = nav_kv_store_from_installed_live_feed(
                "winds-aloft",
                &installed.version,
                &installed.state_sha256,
                root,
                pages,
            )?;
            session.weather.runtime_mut().forecast_atmosphere = Some(
                crate::InstalledForecastAtmosphere::new(manifest, store).map_err(|message| {
                    AppError {
                        kind: AppErrorKind::InvalidManifest,
                        message,
                    }
                })?,
            );
            session.weather.runtime_mut().forecast_atmosphere_state = None;
        }
        (product, payload) => {
            return Err(AppError {
                kind: AppErrorKind::InvalidManifest,
                message: format!(
                    "installed live feed {product} has incompatible payload kind {}",
                    payload.kind_name()
                ),
            });
        }
    }
    session
        .weather
        .live_feeds_mut()
        .mark_durable_product_loaded(
            installed.product.clone(),
            installed.version.clone(),
            installed.state_sha256.clone(),
            installed.collected_at_utc.clone(),
            installed_live_feed_state_manifest(installed),
        );
    sync_live_feed_overlay_status_records(session);
    Ok(())
}

pub fn sync_live_feed_catalog_in_session(
    handle: u32,
    live_feeds: &crate::LiveFeedsState,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    session
        .weather
        .live_feeds_mut()
        .merge_catalog_from(live_feeds);
    sync_live_feed_overlay_status_records(session);
    changed_session_update_outcome(session)
}

fn installed_live_feed_state_manifest(
    installed: &crate::LiveFeedInstalledState,
) -> Option<serde_json::Value> {
    match &installed.payload {
        crate::LiveFeedInstalledPayload::Json { bytes } => serde_json::from_slice(bytes).ok(),
        crate::LiveFeedInstalledPayload::NavKv { manifest, .. } => {
            serde_json::from_slice(manifest).ok()
        }
        crate::LiveFeedInstalledPayload::NexradPackage { manifest, .. } => {
            serde_json::from_slice(manifest).ok()
        }
        crate::LiveFeedInstalledPayload::NotamResources { .. } => None,
    }
}

fn install_prepared_live_feed(
    session: &mut UiSession,
    payload: crate::PreparedLiveFeedPayload,
) -> AppResult<()> {
    match payload {
        crate::PreparedLiveFeedPayload::Metars(feed) => {
            if feed.schema_version != 1 {
                return Err(AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("unsupported prepared METAR schema {}", feed.schema_version),
                });
            }
            session.weather.runtime_mut().metar_payload = Some(feed.payload);
            session.weather.runtime_mut().prepared_metar_tiles = Some(feed.tiles);
            rebuild_metar_tile_cache(session);
            clear_data_status_record(session, LIVE_FEED_METARS_STATUS_ID);
        }
        crate::PreparedLiveFeedPayload::Tafs(payload) => {
            session.weather.runtime_mut().taf_payload = Some(payload);
            let status_id = live_feed_unavailable_status_record("tafs", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
        crate::PreparedLiveFeedPayload::Tfrs(payload) => {
            session.weather.runtime_mut().tfr_payload = Some(payload);
            clear_data_status_record(session, LIVE_FEED_TFRS_STATUS_ID);
        }
        crate::PreparedLiveFeedPayload::Notams(message) => {
            match message {
                crate::PreparedNotamPayload::InstallAirportCheckpoint(checkpoint) => {
                    let index = AirportNotamIndex::from_projection_checkpoint(checkpoint).map_err(
                        |error| AppError {
                            kind: AppErrorKind::InvalidManifest,
                            message: format!("failed to install airport NOTAM projection: {error}"),
                        },
                    )?;
                    session.weather.runtime_mut().airport_notam_index = Some(index);
                }
                crate::PreparedNotamPayload::ApplyAirportDelta(delta) => {
                    let index = session
                        .weather
                        .runtime_mut()
                        .airport_notam_index
                        .as_mut()
                        .ok_or_else(|| AppError {
                            kind: AppErrorKind::InvalidManifest,
                            message: "cannot apply NOTAM delta without installed state".to_string(),
                        })?;
                    if let Err(error) = index.apply_projection_delta(delta) {
                        let preserve = matches!(
                            error,
                            notam_state::NotamStateError::Contract(_)
                                | notam_state::NotamStateError::InvalidOrdering(_)
                                | notam_state::NotamStateError::BaseStateMismatch { .. }
                        );
                        if !preserve {
                            session.weather.runtime_mut().airport_notam_index = None;
                        }
                        return Err(AppError {
                            kind: AppErrorKind::InvalidManifest,
                            message: format!("failed to apply NOTAM delta: {error}"),
                        });
                    }
                }
            }
            let status_id = live_feed_unavailable_status_record("notams", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
        crate::PreparedLiveFeedPayload::Pireps(feed) => {
            if feed.schema_version != 1 {
                return Err(AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("unsupported prepared PIREP schema {}", feed.schema_version),
                });
            }
            session.weather.runtime_mut().pirep_payload = Some(feed.payload);
            session.weather.runtime_mut().prepared_pirep_tiles = Some(feed.tiles);
            rebuild_metar_tile_cache(session);
            clear_data_status_record(session, LIVE_FEED_PIREPS_STATUS_ID);
        }
    }
    Ok(())
}

fn installed_nexrad_descriptor(
    version: &str,
    state_sha256: &str,
    manifest_bytes: &[u8],
    package_blob_sha256: &str,
) -> AppResult<LiveNexradInstalledState> {
    let manifest: serde_json::Value =
        serde_json::from_slice(manifest_bytes).map_err(|err| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse installed NEXRAD manifest: {err}"),
        })?;
    let state_id = manifest
        .get("state_id")
        .and_then(serde_json::Value::as_str)
        .unwrap_or(version);
    if state_id != version {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "installed NEXRAD manifest state_id {state_id} did not match {version}"
            ),
        });
    }
    let actual_state_sha256 = canonical_json_sha256_value(&manifest)?;
    if actual_state_sha256 != state_sha256 {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "installed NEXRAD state hash mismatch: expected {state_sha256}, got {actual_state_sha256}"
            ),
        });
    }
    Ok(LiveNexradInstalledState {
        version: version.to_string(),
        package_blob_sha256: package_blob_sha256.to_string(),
        manifest,
    })
}

pub fn report_session_resource_failure_in_session(
    handle: u32,
    resource_id: &str,
    message: &str,
) -> AppResult<HadOperationOutcome> {
    report_session_resource_failure_in_session_at_epoch_ms(handle, resource_id, message, 0)
}

pub fn report_session_resource_failure_in_session_at_epoch_ms(
    handle: u32,
    resource_id: &str,
    message: &str,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    advance_session_wall_clock(session, epoch_ms);
    if LiveFeedsState::handles_resource(resource_id) {
        let wall_clock_epoch_ms = session.coordinator.wall_clock_epoch_ms;
        session
            .weather
            .live_feeds_mut()
            .record_resource_failure(resource_id, wall_clock_epoch_ms);
        record_live_feed_resource_error(
            session,
            live_feed_resource_failure_detail(resource_id, message),
        );
        record_live_feed_fetch_failure(session, resource_id, message);
        sync_live_feed_overlay_status_records(session);
    } else if resource_id.starts_with("terrain/source/")
        && session.map.layer_state().terrain_warning.visible
    {
        upsert_data_status_record(
            session,
            terrain_status_record(format!(
                "Terrain warning unavailable: failed to load terrain source {resource_id}: {message}"
            )),
        );
    } else if resource_id.starts_with(LIVE_NAV_KV_RESOURCE_PREFIX) {
        let product = live_nav_kv_resource_parts(resource_id)
            .map(|(product, _, _)| product)
            .unwrap_or("live NavKv");
        upsert_data_status_record(
            session,
            live_feed_unavailable_status_record(
                product,
                format!(
                    "{product} live feed unavailable: failed to fetch NavKv resource: {message}"
                ),
            ),
        );
    } else if session.coordinator.debug_state.internet_adsb
        && crate::adsb::AdsbSessionState::handles_resource(resource_id)
    {
        let wall_clock_epoch_ms = session.coordinator.wall_clock_epoch_ms;
        let ownship_resource = crate::adsb::AdsbSessionState::is_ownship_resource(resource_id);
        session
            .runtime
            .adsb
            .record_failure(resource_id, message, wall_clock_epoch_ms);
        if ownship_resource {
            let registration = session
                .runtime
                .adsb
                .ownship_registration()
                .unwrap_or("aircraft")
                .to_string();
            set_adsb_ownship_status(
                session,
                crate::SourceConnectionState::Failed,
                format!("Failed to update {registration}: {message}"),
            )?;
            sync_adsb_ownship_status_record(session);
        } else if session.map.layer_state().traffic.visible {
            upsert_data_status_record(
                session,
                DataStatusRecord::new(
                    ADSB_TRAFFIC_STATUS_ID,
                    "TRAFFIC UNAVAIL",
                    None,
                    UiStatusSeverity::Warning,
                    true,
                    format!("ADS-B traffic unavailable: {message}"),
                ),
            );
        }
    } else if resource_id.starts_with(LIVE_OBSTACLE_HAD_RESOURCE_PREFIX) {
        upsert_data_status_record(
            session,
            live_feed_unavailable_status_record(
                "obstacles",
                format!("Obstacle live feed unavailable: failed to fetch HAD resource: {message}"),
            ),
        );
    }
    changed_session_update_outcome(session)
}

fn ingest_live_obstacle_had_resource(
    session: &mut UiSession,
    resource_id: &str,
    bytes: &[u8],
) -> AppResult<()> {
    let Some((version, member)) = live_obstacle_had_resource_parts(resource_id) else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid obstacle HAD resource id: {resource_id}"),
        });
    };
    let Some(had) = session.weather.runtime_mut().obstacle_had.as_mut() else {
        return Ok(());
    };
    if had.source.version != version {
        return Ok(());
    }
    if member == "root" {
        let root = NavKvRoot::parse(bytes).map_err(|message| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse obstacle HAD root: {message}"),
        })?;
        if root.page_count() != had.source.page_count {
            return Err(AppError {
                kind: AppErrorKind::InvalidManifest,
                message: format!(
                    "obstacle HAD root page_count {} did not match manifest page_count {}",
                    root.page_count(),
                    had.source.page_count
                ),
            });
        }
        had.store = Some(NavKvStore::new(root));
        session.weather.runtime_mut().obstacle_tile_cache.clear();
        clear_data_status_record(session, LIVE_FEED_OBSTACLES_STATUS_ID);
        return Ok(());
    }
    let Some(page_text) = member.strip_prefix("page/") else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid obstacle HAD resource id: {resource_id}"),
        });
    };
    let page_index = page_text.parse::<u32>().map_err(|err| AppError {
        kind: AppErrorKind::InvalidManifest,
        message: format!("invalid obstacle HAD page resource id {resource_id}: {err}"),
    })?;
    if page_index >= had.source.page_count {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "obstacle HAD page {page_index} exceeds page_count {}",
                had.source.page_count
            ),
        });
    }
    let Some(store) = had.store.as_mut() else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("obstacle HAD page arrived before root: {resource_id}"),
        });
    };
    let page_bytes = nav_kv_package::decode_xz_if_needed(bytes).map_err(|message| AppError {
        kind: AppErrorKind::InvalidManifest,
        message: format!("failed to decode obstacle HAD page {resource_id}: {message}"),
    })?;
    store.insert_page(page_index, page_bytes.into_owned());
    clear_data_status_record(session, LIVE_FEED_OBSTACLES_STATUS_ID);
    Ok(())
}

fn ingest_live_forecast_atmosphere_resource(
    session: &mut UiSession,
    resource_id: &str,
    bytes: &[u8],
) -> AppResult<()> {
    let Some((product, version, member)) = live_nav_kv_resource_parts(resource_id) else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid live NavKv resource id: {resource_id}"),
        });
    };
    if product != "winds-aloft" {
        return Err(AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: format!("unsupported live NavKv product: {product}"),
        });
    }
    let Some(state) = session.weather.runtime().forecast_atmosphere_state.clone() else {
        return Ok(());
    };
    if state.source.version != version {
        return Ok(());
    }
    if member == "root" {
        let root = NavKvRoot::parse(bytes).map_err(|message| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse winds-aloft NavKv root: {message}"),
        })?;
        if root.page_count() != state.source.page_count {
            return Err(AppError {
                kind: AppErrorKind::InvalidManifest,
                message: format!(
                    "winds-aloft NavKv root page_count {} did not match manifest page_count {}",
                    root.page_count(),
                    state.source.page_count
                ),
            });
        }
        session.weather.runtime_mut().forecast_atmosphere = Some(
            crate::InstalledForecastAtmosphere::new(state.manifest.clone(), NavKvStore::new(root))
                .map_err(|message| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message,
                })?,
        );
        let status_id = live_feed_unavailable_status_record("winds-aloft", String::new()).id;
        clear_data_status_record(session, &status_id);
        return Ok(());
    }
    let Some(page_text) = member.strip_prefix("page/") else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid winds-aloft NavKv resource id: {resource_id}"),
        });
    };
    let page_index = page_text.parse::<u32>().map_err(|error| AppError {
        kind: AppErrorKind::InvalidManifest,
        message: format!("invalid winds-aloft NavKv page resource id {resource_id}: {error}"),
    })?;
    if page_index >= state.source.page_count {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "winds-aloft NavKv page {page_index} exceeds page_count {}",
                state.source.page_count
            ),
        });
    }
    let Some(atmosphere) = session.weather.runtime_mut().forecast_atmosphere.as_mut() else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("winds-aloft NavKv page arrived before root: {resource_id}"),
        });
    };
    let page_bytes = nav_kv_package::decode_xz_if_needed(bytes).map_err(|message| AppError {
        kind: AppErrorKind::InvalidManifest,
        message: format!("failed to decode winds-aloft NavKv page {resource_id}: {message}"),
    })?;
    atmosphere.insert_page(page_index, page_bytes.into_owned());
    let status_id = live_feed_unavailable_status_record("winds-aloft", String::new()).id;
    clear_data_status_record(session, &status_id);
    Ok(())
}

fn install_live_feed_payloads(session: &mut UiSession) -> AppResult<()> {
    if session.weather.live_feeds().current_loaded() {
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("metars")
        {
            session.weather.runtime_mut().metar_tile_cache.clear();
            session.weather.runtime_mut().metar_payload = None;
            session.weather.runtime_mut().prepared_metar_tiles = None;
            clear_data_status_record(session, LIVE_FEED_METARS_STATUS_ID);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("pireps")
        {
            session.weather.runtime_mut().pirep_payload = None;
            session.weather.runtime_mut().prepared_pirep_tiles = None;
            rebuild_metar_tile_cache(session);
            clear_data_status_record(session, LIVE_FEED_PIREPS_STATUS_ID);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("tafs")
        {
            session.weather.runtime_mut().taf_payload = None;
            let status_id = live_feed_unavailable_status_record("tafs", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("notams")
        {
            session.weather.runtime_mut().airport_notam_index = None;
            let status_id = live_feed_unavailable_status_record("notams", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("tfrs")
        {
            session.weather.runtime_mut().tfr_payload = None;
            clear_data_status_record(session, LIVE_FEED_TFRS_STATUS_ID);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("obstacles")
        {
            session.weather.runtime_mut().obstacle_had = None;
            session.weather.runtime_mut().obstacle_tile_cache.clear();
            session.map.set_obstacle_layer(None);
            clear_data_status_record(session, LIVE_FEED_OBSTACLES_STATUS_ID);
        }
        if !session
            .weather
            .live_feeds()
            .has_product_current_version("winds-aloft")
        {
            session.weather.runtime_mut().forecast_atmosphere_state = None;
            session.weather.runtime_mut().forecast_atmosphere = None;
            let status_id = live_feed_unavailable_status_record("winds-aloft", String::new()).id;
            clear_data_status_record(session, &status_id);
        }
    }
    let loaded_metars_version = session
        .weather
        .live_feeds()
        .product_loaded_version("metars");
    let metars_installed = session
        .weather
        .runtime()
        .metar_payload
        .as_ref()
        .and_then(|payload| loaded_metars_version.map(|version| payload.version_label == version))
        .unwrap_or(false);
    if !metars_installed {
        if let Some(metars_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("metars")
            .cloned()
        {
            match serde_json::from_value::<MetarProductPayload>(metars_value) {
                Ok(payload) => {
                    session.weather.runtime_mut().metar_payload = Some(payload);
                    session.weather.runtime_mut().prepared_metar_tiles = None;
                    rebuild_metar_tile_cache(session);
                    clear_data_status_record(session, LIVE_FEED_METARS_STATUS_ID);
                }
                Err(err) => {
                    session.weather.runtime_mut().metar_tile_cache.clear();
                    session.weather.runtime_mut().metar_payload = None;
                    session.weather.runtime_mut().prepared_metar_tiles = None;
                    upsert_data_status_record(
                        session,
                        live_feed_unavailable_status_record(
                            "metars",
                            format!("METAR live feed unavailable: failed to parse state: {err}"),
                        ),
                    );
                }
            }
        }
    }
    let loaded_pireps_version = session
        .weather
        .live_feeds()
        .product_loaded_version("pireps");
    let pireps_installed = session
        .weather
        .runtime()
        .pirep_payload
        .as_ref()
        .and_then(|payload| loaded_pireps_version.map(|version| payload.version_label == version))
        .unwrap_or(false);
    if !pireps_installed {
        if let Some(pireps_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("pireps")
            .cloned()
        {
            match serde_json::from_value::<crate::PirepProductPayload>(pireps_value) {
                Ok(payload) => {
                    session.weather.runtime_mut().pirep_payload = Some(payload);
                    session.weather.runtime_mut().prepared_pirep_tiles = None;
                    rebuild_metar_tile_cache(session);
                    clear_data_status_record(session, LIVE_FEED_PIREPS_STATUS_ID);
                }
                Err(err) => {
                    session.weather.runtime_mut().pirep_payload = None;
                    session.weather.runtime_mut().prepared_pirep_tiles = None;
                    rebuild_metar_tile_cache(session);
                    upsert_data_status_record(
                        session,
                        live_feed_unavailable_status_record(
                            "pireps",
                            format!("PIREP live feed unavailable: failed to parse state: {err}"),
                        ),
                    );
                }
            }
        }
    }
    let loaded_tafs_version = session.weather.live_feeds().product_loaded_version("tafs");
    let tafs_installed = session
        .weather
        .runtime()
        .taf_payload
        .as_ref()
        .and_then(|payload| loaded_tafs_version.map(|version| payload.version_label == version))
        .unwrap_or(false);
    if !tafs_installed {
        if let Some(tafs_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("tafs")
            .cloned()
        {
            match serde_json::from_value::<TafProductPayload>(tafs_value) {
                Ok(payload) => {
                    session.weather.runtime_mut().taf_payload = Some(payload);
                    let status_id = live_feed_unavailable_status_record("tafs", String::new()).id;
                    clear_data_status_record(session, &status_id);
                }
                Err(err) => {
                    session.weather.runtime_mut().taf_payload = None;
                    upsert_data_status_record(
                        session,
                        live_feed_unavailable_status_record(
                            "tafs",
                            format!("TAF live feed unavailable: failed to parse state: {err}"),
                        ),
                    );
                }
            }
        }
    }
    let loaded_tfrs_version = session.weather.live_feeds().product_loaded_version("tfrs");
    let tfrs_installed = session
        .weather
        .runtime()
        .tfr_payload
        .as_ref()
        .and_then(|payload| loaded_tfrs_version.map(|version| payload.version_label == version))
        .unwrap_or(false);
    if !tfrs_installed {
        if let Some(tfrs_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("tfrs")
            .cloned()
        {
            match serde_json::from_value::<TfrProductPayload>(tfrs_value) {
                Ok(payload) => {
                    session.weather.runtime_mut().tfr_payload = Some(payload);
                    clear_data_status_record(session, LIVE_FEED_TFRS_STATUS_ID);
                }
                Err(err) => {
                    session.weather.runtime_mut().tfr_payload = None;
                    upsert_data_status_record(
                        session,
                        live_feed_unavailable_status_record(
                            "tfrs",
                            format!("TFR live feed unavailable: failed to parse state: {err}"),
                        ),
                    );
                }
            }
        }
    }
    let loaded_obstacles_version = session
        .weather
        .live_feeds()
        .product_loaded_version("obstacles")
        .map(str::to_string);
    if let Some(current_obstacles_version) = session
        .weather
        .live_feeds()
        .current_product_version("obstacles")
    {
        if session
            .weather
            .runtime()
            .obstacle_had
            .as_ref()
            .is_some_and(|had| had.source.version != current_obstacles_version)
        {
            session.weather.runtime_mut().obstacle_had = None;
            session.weather.runtime_mut().obstacle_tile_cache.clear();
            session.map.set_obstacle_layer(None);
        }
    }
    let obstacles_installed = session
        .weather
        .runtime()
        .obstacle_had
        .as_ref()
        .and_then(|had| {
            loaded_obstacles_version
                .as_deref()
                .map(|version| had.source.version == version)
        })
        .unwrap_or(false);
    if !obstacles_installed {
        if let Some(obstacles_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("obstacles")
            .cloned()
        {
            if let Err(err) = install_live_obstacle_had(session, obstacles_value) {
                session.weather.runtime_mut().obstacle_had = None;
                session.weather.runtime_mut().obstacle_tile_cache.clear();
                session.map.set_obstacle_layer(None);
                upsert_data_status_record(
                    session,
                    live_feed_unavailable_status_record(
                        "obstacles",
                        format!("Obstacle live feed unavailable: failed to parse state: {err}"),
                    ),
                );
            }
        }
    }
    let loaded_forecast_version = session
        .weather
        .live_feeds()
        .product_loaded_version("winds-aloft")
        .map(str::to_string);
    if let Some(current_forecast_version) = session
        .weather
        .live_feeds()
        .current_product_version("winds-aloft")
    {
        let pending_is_stale = session
            .weather
            .runtime()
            .forecast_atmosphere_state
            .as_ref()
            .is_some_and(|state| state.source.version != current_forecast_version);
        let installed_is_stale = session
            .weather
            .runtime()
            .forecast_atmosphere
            .as_ref()
            .is_some_and(|atmosphere| atmosphere.version_label() != current_forecast_version);
        if pending_is_stale || installed_is_stale {
            session.weather.runtime_mut().forecast_atmosphere_state = None;
            session.weather.runtime_mut().forecast_atmosphere = None;
        }
    }
    let forecast_installed = session
        .weather
        .runtime()
        .forecast_atmosphere
        .as_ref()
        .and_then(|atmosphere| {
            loaded_forecast_version
                .as_deref()
                .map(|version| atmosphere.version_label() == version)
        })
        .unwrap_or(false);
    let forecast_pending = session
        .weather
        .runtime()
        .forecast_atmosphere_state
        .as_ref()
        .and_then(|state| {
            loaded_forecast_version
                .as_deref()
                .map(|version| state.source.version == version)
        })
        .unwrap_or(false);
    if !forecast_installed && !forecast_pending {
        if let Some(forecast_value) = session
            .weather
            .live_feeds()
            .product_state_manifest("winds-aloft")
            .cloned()
        {
            let manifest =
                serde_json::from_value::<product_contracts::AtmosphereManifest>(forecast_value)
                    .map_err(|error| AppError {
                        kind: AppErrorKind::InvalidManifest,
                        message: format!("failed to parse winds-aloft live feed manifest: {error}"),
                    })?;
            install_live_forecast_atmosphere_state(session, manifest)?;
        }
    }
    sync_live_feed_overlay_status_records(session);
    Ok(())
}

fn install_live_forecast_atmosphere_state(
    session: &mut UiSession,
    manifest: product_contracts::AtmosphereManifest,
) -> AppResult<()> {
    manifest
        .validate(&format!("had-nav-kv-v{}", had_nav_kv::VERSION))
        .map_err(|message| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid winds-aloft live feed manifest: {message}"),
        })?;
    let version = session
        .weather
        .live_feeds()
        .product_loaded_version("winds-aloft")
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: "winds-aloft state manifest has no loaded version".to_string(),
        })?
        .to_string();
    let state_url = session
        .weather
        .live_feeds()
        .product_state_url("winds-aloft")
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: "winds-aloft state manifest has no state URL".to_string(),
        })?
        .to_string();
    if manifest.product_id != "winds-aloft" || manifest.version_label != version {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "winds-aloft manifest identified {}/{} instead of winds-aloft/{version}",
                manifest.product_id, manifest.version_label
            ),
        });
    }
    let source = LiveNavKvSource {
        product: "winds-aloft".to_string(),
        version,
        state_url,
        root_member_path: manifest.root.clone(),
        page_path_template: manifest.page_path_template.clone(),
        page_count: manifest.page_count,
        state_sha256: manifest.state_sha256.clone(),
    };
    session.weather.runtime_mut().forecast_atmosphere_state =
        Some(LiveForecastAtmosphereState { source, manifest });
    session.weather.runtime_mut().forecast_atmosphere = None;
    Ok(())
}

fn install_live_obstacle_had(
    session: &mut UiSession,
    manifest_value: serde_json::Value,
) -> AppResult<()> {
    let manifest: LiveObstacleHadManifest = serde_json::from_value(manifest_value.clone())
        .map_err(|err| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse obstacle live feed HAD manifest: {err}"),
        })?;
    let Some(version) = session
        .weather
        .live_feeds()
        .product_loaded_version("obstacles")
        .map(str::to_string)
    else {
        return Ok(());
    };
    let Some(state_url) = session
        .weather
        .live_feeds()
        .product_state_url("obstacles")
        .map(str::to_string)
    else {
        return Ok(());
    };
    install_live_obstacle_had_with_parsed_manifest(
        session,
        manifest_value,
        manifest,
        version,
        state_url,
        None,
    )
}

fn install_live_obstacle_had_with_store(
    session: &mut UiSession,
    manifest_value: serde_json::Value,
    version: String,
    state_url: String,
    store: Option<NavKvStore>,
) -> AppResult<()> {
    let manifest: LiveObstacleHadManifest = serde_json::from_value(manifest_value.clone())
        .map_err(|err| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse obstacle live feed HAD manifest: {err}"),
        })?;
    install_live_obstacle_had_with_parsed_manifest(
        session,
        manifest_value,
        manifest,
        version,
        state_url,
        store,
    )
}

fn install_live_obstacle_had_with_parsed_manifest(
    session: &mut UiSession,
    manifest_value: serde_json::Value,
    manifest: LiveObstacleHadManifest,
    version: String,
    state_url: String,
    store: Option<NavKvStore>,
) -> AppResult<()> {
    if manifest.schema_version != 1 {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "unsupported obstacle live feed HAD manifest schema_version {}",
                manifest.schema_version
            ),
        });
    }
    if manifest.product_id != "obstacles" {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "obstacle live feed HAD manifest contained product_id {}",
                manifest.product_id
            ),
        });
    }
    if manifest.encoding != format!("had-nav-kv-v{}", had_nav_kv::VERSION) {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "unsupported obstacle live feed HAD encoding {}",
                manifest.encoding
            ),
        });
    }
    if manifest.version_label != version {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "obstacle live feed HAD manifest version {} did not match loaded version {version}",
                manifest.version_label
            ),
        });
    }
    let obstacle_layer = obstacle_layer_config_from_live_manifest_value(manifest_value)?;
    let source = LiveNavKvSource {
        product: "obstacles".to_string(),
        version,
        state_url,
        root_member_path: manifest.root,
        page_path_template: manifest.page_path_template,
        page_count: manifest.page_count,
        state_sha256: manifest.state_sha256,
    };
    let same_state = session
        .weather
        .runtime()
        .obstacle_had
        .as_ref()
        .is_some_and(|existing| {
            existing.source.product == source.product
                && existing.source.version == source.version
                && existing.source.state_url == source.state_url
                && existing.source.root_member_path == source.root_member_path
                && existing.source.page_path_template == source.page_path_template
                && existing.source.page_count == source.page_count
                && existing.source.state_sha256 == source.state_sha256
        });
    let preserve_store = store.or_else(|| {
        if same_state {
            session
                .weather
                .runtime()
                .obstacle_had
                .as_ref()
                .and_then(|existing| existing.store.clone())
        } else {
            None
        }
    });
    session.map.set_obstacle_layer(Some(obstacle_layer));
    session.weather.runtime_mut().obstacle_had = Some(LiveObstacleHadState {
        source,
        store: preserve_store,
    });
    if !same_state {
        session.weather.runtime_mut().obstacle_tile_cache.clear();
    }
    clear_data_status_record(session, LIVE_FEED_OBSTACLES_STATUS_ID);
    Ok(())
}

fn nav_kv_store_from_installed_live_feed(
    product: &str,
    version: &str,
    state_sha256: &str,
    root: &[u8],
    pages: &[Vec<u8>],
) -> AppResult<NavKvStore> {
    let root = NavKvRoot::parse(root).map_err(|message| AppError {
        kind: AppErrorKind::InvalidManifest,
        message: format!("failed to parse installed {product} HAD root: {message}"),
    })?;
    if root.page_count() as usize != pages.len() {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "installed {product} HAD root page_count {} did not match payload page_count {}",
                root.page_count(),
                pages.len()
            ),
        });
    }
    let actual = root
        .canonical_sha256(|page| pages.get(page as usize).cloned())
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to hash installed {product} HAD {version}"),
        })?;
    if actual != state_sha256 {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!(
                "installed {product} HAD {version} hash mismatch: expected {state_sha256}, got {actual}"
            ),
        });
    }
    let mut store = NavKvStore::new(root);
    for (page_index, page) in pages.iter().enumerate() {
        store.insert_page(page_index as u32, page.clone());
    }
    Ok(store)
}

fn metar_tile_cache_for_live_feed(
    payload: &MetarProductPayload,
    layer: Option<&crate::map_overlay::PointTileLayerConfig>,
    important_station_ids: &HashSet<String>,
) -> HashMap<String, MetarTilePayload> {
    let Some(layer) = layer else {
        return HashMap::new();
    };
    let mut cache = HashMap::new();
    for zoom in &layer.available_zooms {
        for record in payload.metars_by_station.values() {
            if *zoom == layer.min_zoom && !important_station_ids.contains(&record.station_id) {
                continue;
            }
            let Some((x, y)) = metar_tile_xy(record.latitude, record.longitude, *zoom) else {
                continue;
            };
            let key = crate::tile_key("metars", *zoom, x, y);
            cache
                .entry(key)
                .or_insert_with(|| MetarTilePayload {
                    schema_version: 1,
                    layer: "metars".to_string(),
                    z: *zoom,
                    x,
                    y,
                    records: Vec::new(),
                })
                .records
                .push(MetarTileRecord {
                    kind: "metar".to_string(),
                    id: record.station_id.clone(),
                });
        }
    }
    cache
}

fn metar_tile_cache_for_prepared_live_feed(
    tiles: &[crate::PreparedMetarTile],
    layer: Option<&crate::map_overlay::PointTileLayerConfig>,
    important_station_ids: &HashSet<String>,
) -> Option<HashMap<String, MetarTilePayload>> {
    let Some(layer) = layer else {
        return Some(HashMap::new());
    };
    let available_zooms = layer
        .available_zooms
        .iter()
        .copied()
        .collect::<HashSet<_>>();
    let feed_zooms = tiles.iter().map(|tile| tile.z).collect::<HashSet<_>>();
    if !available_zooms.is_subset(&feed_zooms) {
        return None;
    }
    let mut cache = HashMap::new();
    for tile in tiles {
        if !available_zooms.contains(&tile.z) {
            continue;
        }
        let mut records = Vec::new();
        for station_id in &tile.station_ids {
            if tile.z == layer.min_zoom && !important_station_ids.contains(station_id) {
                continue;
            }
            records.push(MetarTileRecord {
                kind: "metar".to_string(),
                id: station_id.clone(),
            });
        }
        if records.is_empty() {
            continue;
        }
        let key = crate::tile_key("metars", tile.z, tile.x, tile.y);
        cache.insert(
            key,
            MetarTilePayload {
                schema_version: 1,
                layer: "metars".to_string(),
                z: tile.z,
                x: tile.x,
                y: tile.y,
                records,
            },
        );
    }
    Some(cache)
}

fn append_pirep_tile_cache_for_live_feed(
    cache: &mut HashMap<String, MetarTilePayload>,
    payload: &crate::PirepProductPayload,
    layer: Option<&crate::map_overlay::PointTileLayerConfig>,
) {
    let Some(layer) = layer else {
        return;
    };
    for zoom in &layer.available_zooms {
        for record in payload.pireps_by_id.values() {
            let Some((x, y)) = metar_tile_xy(record.latitude, record.longitude, *zoom) else {
                continue;
            };
            let key = crate::tile_key("metars", *zoom, x, y);
            cache
                .entry(key)
                .or_insert_with(|| MetarTilePayload {
                    schema_version: 1,
                    layer: "metars".to_string(),
                    z: *zoom,
                    x,
                    y,
                    records: Vec::new(),
                })
                .records
                .push(MetarTileRecord {
                    kind: "pirep".to_string(),
                    id: record.id.clone(),
                });
        }
    }
}

fn append_pirep_tile_cache_for_prepared_live_feed(
    cache: &mut HashMap<String, MetarTilePayload>,
    tiles: &[crate::PreparedPirepTile],
    layer: Option<&crate::map_overlay::PointTileLayerConfig>,
) -> bool {
    let Some(layer) = layer else {
        return true;
    };
    let available_zooms = layer
        .available_zooms
        .iter()
        .copied()
        .collect::<HashSet<_>>();
    let feed_zooms = tiles.iter().map(|tile| tile.z).collect::<HashSet<_>>();
    if !available_zooms.is_subset(&feed_zooms) {
        return false;
    }
    for tile in tiles {
        if !available_zooms.contains(&tile.z) || tile.pirep_ids.is_empty() {
            continue;
        }
        let key = crate::tile_key("metars", tile.z, tile.x, tile.y);
        let records = &mut cache
            .entry(key)
            .or_insert_with(|| MetarTilePayload {
                schema_version: 1,
                layer: "metars".to_string(),
                z: tile.z,
                x: tile.x,
                y: tile.y,
                records: Vec::new(),
            })
            .records;
        records.extend(tile.pirep_ids.iter().map(|id| MetarTileRecord {
            kind: "pirep".to_string(),
            id: id.clone(),
        }));
    }
    true
}

fn rebuild_metar_tile_cache(session: &mut UiSession) {
    let layer = session.map.overlay_config().metar_layer.clone();
    let important_station_ids = session
        .weather
        .runtime()
        .important_metar_station_ids
        .clone()
        .unwrap_or_default();
    let mut cache = session
        .weather
        .runtime()
        .prepared_metar_tiles
        .as_ref()
        .and_then(|tiles| {
            metar_tile_cache_for_prepared_live_feed(tiles, layer.as_ref(), &important_station_ids)
        })
        .or_else(|| {
            session
                .weather
                .runtime()
                .metar_payload
                .as_ref()
                .map(|payload| {
                    metar_tile_cache_for_live_feed(payload, layer.as_ref(), &important_station_ids)
                })
        })
        .unwrap_or_default();

    let used_prepared_pireps = session
        .weather
        .runtime()
        .prepared_pirep_tiles
        .as_ref()
        .is_some_and(|tiles| {
            append_pirep_tile_cache_for_prepared_live_feed(&mut cache, tiles, layer.as_ref())
        });
    if !used_prepared_pireps {
        if let Some(payload) = session.weather.runtime().pirep_payload.as_ref() {
            append_pirep_tile_cache_for_live_feed(&mut cache, payload, layer.as_ref());
        }
    }
    session.weather.runtime_mut().metar_tile_cache = cache;
}

fn ensure_metar_station_importance_loaded(session: &mut UiSession) -> Result<(), HadReadError> {
    if session
        .weather
        .runtime()
        .important_metar_station_ids
        .is_some()
    {
        return Ok(());
    }
    let Some(store) = session.nav_data.store() else {
        session.weather.runtime_mut().important_metar_station_ids = Some(HashSet::new());
        session
            .weather
            .runtime_mut()
            .metar_station_importance_status = Some(metar_station_importance_status_record(
            "Station importance unavailable",
            UiStatusSeverity::Caution,
            "METAR low-zoom station filtering could not load because no nav-db store is attached.",
        ));
        rebuild_metar_tile_cache(session);
        return Ok(());
    };
    let Some(payload) = read_attached_json_optional::<MetarImportantStationsPayload>(
        store,
        NavKvQuery::MetarImportantStations,
    )?
    else {
        session.weather.runtime_mut().important_metar_station_ids = Some(HashSet::new());
        session.weather.runtime_mut().metar_station_importance_status = Some(metar_station_importance_status_record(
            "Station importance missing",
            UiStatusSeverity::Caution,
            "METAR low-zoom station filtering could not find weather/metar-important-stations in nav-db. Low-zoom METARs are hidden until the current nav-db provides that record.",
        ));
        rebuild_metar_tile_cache(session);
        return Ok(());
    };
    if payload.schema_version != 1 {
        return Err(HadReadError::Fatal(format!(
            "unsupported METAR important station schema version {}",
            payload.schema_version
        )));
    }
    let station_ids = payload
        .station_ids
        .into_iter()
        .map(|station_id| station_id.trim().to_ascii_uppercase())
        .filter(|station_id| !station_id.is_empty())
        .collect::<HashSet<_>>();
    session.weather.runtime_mut().important_metar_station_ids = Some(station_ids);
    session
        .weather
        .runtime_mut()
        .metar_station_importance_status = None;
    rebuild_metar_tile_cache(session);
    Ok(())
}

fn ensure_weather_station_airport_aliases_loaded(
    session: &mut UiSession,
) -> Result<(), HadReadError> {
    if session
        .weather
        .runtime()
        .weather_station_airport_aliases
        .is_some()
    {
        return Ok(());
    }
    let Some(store) = session.nav_data.store() else {
        session
            .weather
            .runtime_mut()
            .weather_station_airport_aliases = Some(WeatherStationAirportAliases::default());
        return Ok(());
    };
    let Some(payload) = read_attached_json_optional::<WeatherStationAirportAliasesPayload>(
        store,
        NavKvQuery::WeatherStationAirportAliases,
    )?
    else {
        session
            .weather
            .runtime_mut()
            .weather_station_airport_aliases = Some(WeatherStationAirportAliases::default());
        return Ok(());
    };
    if payload.schema_version != 1 {
        return Err(HadReadError::Fatal(format!(
            "unsupported weather station airport alias schema version {}",
            payload.schema_version
        )));
    }
    session
        .weather
        .runtime_mut()
        .weather_station_airport_aliases =
        Some(WeatherStationAirportAliases::from_station_to_airport(
            payload
                .aliases
                .into_iter()
                .map(|(station_id, alias)| (station_id, alias.airport_id, alias.position)),
        ));
    Ok(())
}

fn metar_importance_required_for_surface(session: &UiSession, metrics: &MapSurfaceMetrics) -> bool {
    if !session.map.layer_state().metars.visible
        || session.weather.runtime().metar_payload.is_none()
    {
        return false;
    }
    let Some(layer) = session.map.overlay_config().metar_layer.as_ref() else {
        return false;
    };
    crate::overlay_surface_decision(*metrics, session.map.overlay_config()).metar_tile_zoom
        == Some(layer.min_zoom)
}

fn metar_station_importance_status_record(
    value: impl Into<String>,
    severity: UiStatusSeverity,
    detail: impl Into<String>,
) -> DataStatusRecord {
    DataStatusRecord::new(
        METAR_STATION_IMPORTANCE_STATUS_ID,
        "METAR",
        Some(value.into()),
        severity,
        false,
        detail.into(),
    )
}

fn try_ensure_metar_station_importance_loaded(session: &mut UiSession) -> Option<DataStatusRecord> {
    if session
        .weather
        .runtime()
        .important_metar_station_ids
        .is_some()
    {
        return session
            .weather
            .runtime()
            .metar_station_importance_status
            .clone();
    }
    match ensure_metar_station_importance_loaded(session) {
        Ok(()) => session
            .weather
            .runtime()
            .metar_station_importance_status
            .clone(),
        Err(HadReadError::NeedPages(pages)) => {
            for resource in nav_kv_page_resources(pages) {
                enqueue_session_resource_effect(session, resource, [UiInvalidation::MapOverlay]);
            }
            rebuild_metar_tile_cache(session);
            Some(metar_station_importance_status_record(
                "Station importance loading",
                UiStatusSeverity::Info,
                "METAR low-zoom station filtering is waiting for weather/metar-important-stations. Low-zoom METARs are hidden until that record is available; map vectors and high-zoom METARs remain available.",
            ))
        }
        Err(HadReadError::Fatal(message)) => {
            session.weather.runtime_mut().important_metar_station_ids = Some(HashSet::new());
            session
                .weather
                .runtime_mut()
                .metar_station_importance_status = Some(metar_station_importance_status_record(
                "Station importance failed",
                UiStatusSeverity::Caution,
                format!("METAR low-zoom station filtering failed: {message}"),
            ));
            rebuild_metar_tile_cache(session);
            session
                .weather
                .runtime()
                .metar_station_importance_status
                .clone()
        }
    }
}

fn metar_tile_xy(lat: f64, lon: f64, zoom: u32) -> Option<(u32, u32)> {
    if !lat.is_finite() || !lon.is_finite() {
        return None;
    }
    let scale = 2_u32.checked_pow(zoom)?;
    let scale_f64 = scale as f64;
    let x = (((lon + 180.0) / 360.0) * scale_f64).floor();
    let clamped_lat = lat.clamp(-WORLD_MERCATOR_MAX_LATITUDE, WORLD_MERCATOR_MAX_LATITUDE);
    let y = ((1.0 - clamped_lat.to_radians().tan().asinh() / std::f64::consts::PI) / 2.0
        * scale_f64)
        .floor();
    Some((
        positive_mod_i64(x as i64, scale as i64) as u32,
        (y as i64).clamp(0, scale as i64 - 1) as u32,
    ))
}

fn positive_mod_i64(value: i64, modulus: i64) -> i64 {
    ((value % modulus) + modulus) % modulus
}

fn internal_json_error(err: serde_json::Error) -> AppError {
    AppError {
        kind: AppErrorKind::Internal,
        message: err.to_string(),
    }
}

fn canonical_json_sha256_value(value: &serde_json::Value) -> AppResult<String> {
    let bytes = serde_json::to_vec(value).map_err(internal_json_error)?;
    Ok(format!("{:x}", Sha256::digest(&bytes)))
}

fn live_feed_state_member_address(state_url: &str, member_path: &str) -> String {
    let base = state_url
        .rsplit_once('/')
        .map(|(base, _)| base)
        .unwrap_or("");
    let member = member_path.trim_start_matches('/');
    if base.is_empty() {
        format!("{LIVE_FEEDS_BASE_PATH}/{member}")
    } else {
        format!("{LIVE_FEEDS_BASE_PATH}/{base}/{member}")
    }
}

fn live_nav_kv_resource_id_prefix(source: &LiveNavKvSource) -> String {
    if source.product == "obstacles" {
        format!("{LIVE_OBSTACLE_HAD_RESOURCE_PREFIX}{}", source.version)
    } else {
        format!(
            "{LIVE_NAV_KV_RESOURCE_PREFIX}{}/{}",
            source.product, source.version
        )
    }
}

fn live_nav_kv_root_resource(
    live_feeds: &LiveFeedsState,
    source: &LiveNavKvSource,
) -> CoreResourceRequest {
    live_feeds.public_live_feed_resource(
        format!("{}/root", live_nav_kv_resource_id_prefix(source)),
        &live_feed_state_member_address(&source.state_url, &source.root_member_path),
        false,
    )
}

fn live_nav_kv_page_member_path(source: &LiveNavKvSource, page: u32) -> String {
    source
        .page_path_template
        .replace("{page:04}", &format!("{page:04}"))
        .replace("{page}", &page.to_string())
}

fn live_nav_kv_page_resource(
    live_feeds: &LiveFeedsState,
    source: &LiveNavKvSource,
    page: u32,
) -> CoreResourceRequest {
    let member_path = live_nav_kv_page_member_path(source, page);
    live_feeds.public_live_feed_resource(
        format!("{}/page/{page:04}", live_nav_kv_resource_id_prefix(source)),
        &live_feed_state_member_address(&source.state_url, &member_path),
        false,
    )
}

fn live_nav_kv_page_resources(
    live_feeds: &LiveFeedsState,
    source: &LiveNavKvSource,
    pages: Vec<u32>,
) -> Vec<CoreResourceRequest> {
    let mut pages = pages;
    pages.sort_unstable();
    pages.dedup();
    pages
        .into_iter()
        .map(|page| live_nav_kv_page_resource(live_feeds, source, page))
        .collect()
}

fn live_obstacle_had_root_resource(
    live_feeds: &LiveFeedsState,
    had: &LiveObstacleHadState,
) -> CoreResourceRequest {
    live_nav_kv_root_resource(live_feeds, &had.source)
}

fn live_obstacle_had_page_resources(
    live_feeds: &LiveFeedsState,
    had: &LiveObstacleHadState,
    pages: Vec<u32>,
) -> Vec<CoreResourceRequest> {
    live_nav_kv_page_resources(live_feeds, &had.source, pages)
}

fn live_obstacle_had_resource_parts(resource_id: &str) -> Option<(&str, &str)> {
    let rest = resource_id.strip_prefix(LIVE_OBSTACLE_HAD_RESOURCE_PREFIX)?;
    rest.split_once('/')
}

fn live_nav_kv_resource_parts(resource_id: &str) -> Option<(&str, &str, &str)> {
    let rest = resource_id.strip_prefix(LIVE_NAV_KV_RESOURCE_PREFIX)?;
    let (product, rest) = rest.split_once('/')?;
    let (version, member) = rest.split_once('/')?;
    Some((product, version, member))
}

fn had_read_error_to_overlay_outcome(err: HadReadError) -> AppResult<HadOperationOutcome> {
    match err {
        HadReadError::NeedPages(pages) => Ok(HadOperationOutcome::NeedResources {
            resources: nav_kv_page_resources(pages),
        }),
        HadReadError::Fatal(message) => Err(AppError {
            kind: AppErrorKind::Internal,
            message,
        }),
    }
}

fn read_attached_json_optional<T: for<'de> Deserialize<'de>>(
    store: &NavKvStore,
    query: NavKvQuery,
) -> Result<Option<T>, HadReadError> {
    let Some(key) = nav_kv_key_for_query(&query) else {
        return Ok(None);
    };
    match store.get_bytes(&key).map_err(HadReadError::Fatal)? {
        NavKvLookup::Hit(bytes) => serde_json::from_slice(&bytes)
            .map(Some)
            .map_err(|err| HadReadError::Fatal(format!("HAD JSON decode failed for {key}: {err}"))),
        NavKvLookup::MissingKey => Ok(None),
        NavKvLookup::MissingPages(pages) => {
            crate::core_debug_log(
                "core.had.key_page_fault",
                &serde_json::json!({
                    "key": key,
                    "pages": pages,
                    "page_count": pages.len(),
                }),
            );
            Err(HadReadError::NeedPages(pages))
        }
    }
}

fn read_attached_json_required<T: for<'de> Deserialize<'de>>(
    store: &NavKvStore,
    query: NavKvQuery,
    family: &str,
) -> Result<T, HadReadError> {
    read_attached_json_optional(store, query.clone())?.ok_or_else(|| {
        let key = nav_kv_key_for_query(&query).unwrap_or_else(|| "<no-key>".to_string());
        HadReadError::Fatal(format!("HAD missing required {family} key: {key}"))
    })
}

fn ensure_vector_manifest_loaded(session: &mut UiSession) -> Result<(), HadReadError> {
    if session.map.vector_manifest_loaded() {
        return Ok(());
    }
    let manifest_json = {
        let store = session.nav_data.store().ok_or_else(|| {
            HadReadError::Fatal("session missing nav kv store for vector overlay".to_string())
        })?;
        read_attached_json_required::<serde_json::Value>(
            store,
            NavKvQuery::VectorManifest,
            "vector manifest",
        )?
    };
    let manifest_json = serde_json::to_string(&manifest_json)
        .map_err(|err| HadReadError::Fatal(err.to_string()))?;
    install_vector_manifest_config(session, &manifest_json).map_err(HadReadError::Fatal)?;
    Ok(())
}

fn install_vector_manifest_config(
    session: &mut UiSession,
    manifest_json: &str,
) -> Result<(), String> {
    let config = map_overlay_config_from_vector_manifest_json(&manifest_json)
        .map_err(|err| err.to_string())?;
    session.map.install_vector_manifest_config(config);
    rebuild_metar_tile_cache(session);
    Ok(())
}

#[derive(Default)]
struct VectorInputLoadStats {
    iterations: u32,
    manifest_ms: u64,
    request_ms: u64,
    key_ms: u64,
    missing_pages_ms: u64,
    read_tiles_ms: u64,
    read_features_ms: u64,
    insert_ms: u64,
    probe: NavKvPageProbeStats,
    total_needed_vector_tiles: usize,
    total_needed_airspace_features: usize,
    needed_pages: usize,
    loaded_vector_tiles: usize,
    loaded_airspace_features: usize,
}

fn merge_nav_kv_probe_stats(total: &mut NavKvPageProbeStats, next: NavKvPageProbeStats) {
    total.keys += next.keys;
    total.node_page_hits += next.node_page_hits;
    total.node_page_misses += next.node_page_misses;
    total.leaf_entries_scanned += next.leaf_entries_scanned;
    total.inline_values += next.inline_values;
    total.external_values += next.external_values;
    total.value_page_hits += next.value_page_hits;
    total.value_page_misses += next.value_page_misses;
}

fn ensure_vector_inputs_loaded(
    session: &mut UiSession,
    metrics: &MapSurfaceMetrics,
) -> Result<(), HadReadError> {
    let total_started_at = crate::core_clock_ms();
    let mut stats = VectorInputLoadStats::default();
    let result = ensure_vector_inputs_loaded_impl(session, metrics, &mut stats);
    let status = match &result {
        Ok(()) => "ok",
        Err(HadReadError::NeedPages(_)) => "need_pages",
        Err(HadReadError::Fatal(_)) => "fatal",
    };
    let error = match &result {
        Ok(()) => None,
        Err(HadReadError::NeedPages(_)) => None,
        Err(HadReadError::Fatal(message)) => Some(message.as_str()),
    };
    crate::core_perf_debug_log("map.overlay.vector_inputs", || {
        serde_json::json!({
            "status": status,
            "error": error,
            "total_ms": elapsed_ms(total_started_at),
            "manifest_ms": stats.manifest_ms,
            "request_ms": stats.request_ms,
            "key_ms": stats.key_ms,
            "missing_pages_ms": stats.missing_pages_ms,
            "read_tiles_ms": stats.read_tiles_ms,
            "read_features_ms": stats.read_features_ms,
            "insert_ms": stats.insert_ms,
            "probe_keys": stats.probe.keys,
            "probe_node_page_hits": stats.probe.node_page_hits,
            "probe_node_page_misses": stats.probe.node_page_misses,
            "probe_leaf_entries_scanned": stats.probe.leaf_entries_scanned,
            "probe_inline_values": stats.probe.inline_values,
            "probe_external_values": stats.probe.external_values,
            "probe_value_page_hits": stats.probe.value_page_hits,
            "probe_value_page_misses": stats.probe.value_page_misses,
            "iterations": stats.iterations,
            "total_needed_vector_tiles": stats.total_needed_vector_tiles,
            "total_needed_airspace_features": stats.total_needed_airspace_features,
            "needed_pages": stats.needed_pages,
            "loaded_vector_tiles": stats.loaded_vector_tiles,
            "loaded_airspace_features": stats.loaded_airspace_features,
            "cached_vector_tiles": session.map.runtime().vector_tile_cache.len(),
            "cached_airspace_features": session.map.runtime().airspace_feature_cache.len(),
        })
    });
    result
}

fn ensure_vector_inputs_loaded_impl(
    session: &mut UiSession,
    metrics: &MapSurfaceMetrics,
    stats: &mut VectorInputLoadStats,
) -> Result<(), HadReadError> {
    let manifest_started_at = crate::core_clock_ms();
    ensure_vector_manifest_loaded(session)?;
    stats.manifest_ms += elapsed_ms(manifest_started_at);
    for _ in 0..8 {
        stats.iterations += 1;
        let request_started_at = crate::core_clock_ms();
        let inputs = vector_overlay_input_requests(
            metrics,
            session.map.overlay_config(),
            &session.map.runtime().vector_tile_cache,
            &session.map.runtime().airspace_feature_cache,
        );
        stats.request_ms += elapsed_ms(request_started_at);
        let needed_vector_inputs =
            inputs.needed_vector_tiles.len() + inputs.needed_airspace_features.len();
        stats.total_needed_vector_tiles += inputs.needed_vector_tiles.len();
        stats.total_needed_airspace_features += inputs.needed_airspace_features.len();
        if needed_vector_inputs == 0 {
            return Ok(());
        }

        let mut loaded_any = false;
        let store = session.nav_data.store().ok_or_else(|| {
            HadReadError::Fatal("session missing nav kv store for vector overlay".to_string())
        })?;
        let keys_started_at = crate::core_clock_ms();
        let input_keys = vector_input_keys(&inputs);
        stats.key_ms += elapsed_ms(keys_started_at);
        let missing_pages_started_at = crate::core_clock_ms();
        let (needed_pages, probe_stats) = store
            .missing_pages_for_keys_with_stats(&input_keys)
            .map_err(HadReadError::Fatal)?;
        merge_nav_kv_probe_stats(&mut stats.probe, probe_stats);
        stats.missing_pages_ms += elapsed_ms(missing_pages_started_at);
        stats.needed_pages += needed_pages.len();
        if !needed_pages.is_empty() {
            return Err(HadReadError::NeedPages(needed_pages));
        }

        let mut vector_tiles = Vec::new();
        let read_tiles_started_at = crate::core_clock_ms();
        for tile in inputs.needed_vector_tiles {
            let payload = read_attached_json_optional::<VectorAggregateTilePayload>(
                store,
                NavKvQuery::VectorTile {
                    z: tile.z,
                    x: tile.x,
                    y: tile.y,
                },
            )?
            .unwrap_or(VectorAggregateTilePayload {
                schema_version: 1,
                z: tile.z,
                x: tile.x,
                y: tile.y,
                airports: Vec::new(),
                fixes: Vec::new(),
                navaids: Vec::new(),
                airspace_refs: Vec::new(),
                airspace_labels: Vec::new(),
            });
            vector_tiles.push(payload);
        }
        stats.read_tiles_ms += elapsed_ms(read_tiles_started_at);

        let mut features = Vec::new();
        let read_features_started_at = crate::core_clock_ms();
        for feature in inputs.needed_airspace_features {
            let payload = read_attached_json_required::<AirspaceFeaturePayload>(
                store,
                NavKvQuery::VectorAirspaceFeature { id: feature.id },
                "vector airspace feature",
            )?;
            features.push(payload);
        }
        stats.read_features_ms += elapsed_ms(read_features_started_at);

        let insert_started_at = crate::core_clock_ms();
        let runtime = session.map.runtime_mut();
        for tile in vector_tiles {
            runtime.vector_tile_cache.insert(
                crate::aggregate_vector_tile_cache_key(tile.z, tile.x, tile.y),
                tile,
            );
            stats.loaded_vector_tiles += 1;
            loaded_any = true;
        }
        for feature in features {
            runtime
                .airspace_feature_cache
                .insert(feature.id.clone(), feature);
            stats.loaded_airspace_features += 1;
            loaded_any = true;
        }
        stats.insert_ms += elapsed_ms(insert_started_at);
        if !loaded_any {
            return Ok(());
        }
    }
    Err(HadReadError::Fatal(
        "vector overlay did not converge after loading HAD inputs".to_string(),
    ))
}

fn vector_inputs_status_record(
    value: impl Into<String>,
    severity: UiStatusSeverity,
    detail: impl Into<String>,
) -> DataStatusRecord {
    DataStatusRecord::new(
        VECTOR_INPUTS_STATUS_ID,
        "Map overlay",
        Some(value.into()),
        severity,
        false,
        detail.into(),
    )
}

fn ensure_vector_inputs_loaded_for_map_overlay(
    session: &mut UiSession,
    metrics: &MapSurfaceMetrics,
) -> Result<Vec<DataStatusRecord>, HadReadError> {
    match ensure_vector_inputs_loaded(session, metrics) {
        Ok(()) => Ok(Vec::new()),
        Err(HadReadError::NeedPages(pages)) => Err(HadReadError::NeedPages(pages)),
        Err(HadReadError::Fatal(message)) => Ok(vec![vector_inputs_status_record(
            "Vector overlay failed",
            UiStatusSeverity::Caution,
            format!("Vector overlay data could not be loaded: {message}"),
        )]),
    }
}

fn vector_input_keys(inputs: &VectorOverlayInputRequests) -> Vec<String> {
    inputs
        .needed_vector_tiles
        .iter()
        .filter_map(|tile| {
            nav_kv_key_for_query(&NavKvQuery::VectorTile {
                z: tile.z,
                x: tile.x,
                y: tile.y,
            })
        })
        .chain(
            inputs
                .needed_airspace_features
                .iter()
                .filter_map(|feature| {
                    nav_kv_key_for_query(&NavKvQuery::VectorAirspaceFeature {
                        id: feature.id.clone(),
                    })
                }),
        )
        .collect()
}

fn ensure_live_obstacle_inputs_loaded(
    session: &mut UiSession,
    metrics: &MapSurfaceMetrics,
) -> Vec<DataStatusRecord> {
    if session.weather.runtime().obstacle_had.is_none() {
        if let HadOperationOutcome::NeedResources { resources } = session
            .weather
            .live_feeds()
            .sync_product_outcome_at_epoch_ms("obstacles", session.coordinator.wall_clock_epoch_ms)
        {
            for resource in resources {
                enqueue_session_resource_effect(session, resource, [UiInvalidation::MapOverlay]);
            }
            return Vec::new();
        }
    }
    let Some(layer) = session.map.overlay_config().obstacle_layer.clone() else {
        return Vec::new();
    };
    let Some(had) = session.weather.runtime().obstacle_had.clone() else {
        return Vec::new();
    };
    if had.store.is_none() {
        enqueue_session_resource_effect(
            session,
            live_obstacle_had_root_resource(session.weather.live_feeds(), &had),
            [UiInvalidation::MapOverlay],
        );
        return vec![live_feed_unavailable_status_record(
            "obstacles",
            "Obstacle live feed is waiting for the current HAD root".to_string(),
        )];
    }
    let obstacle_context = ownship_overlay_context(session);
    let tiles = visible_obstacle_tile_window(
        &layer,
        &metrics.viewport,
        metrics.width_px,
        metrics.height_px,
        obstacle_context.as_ref(),
        metrics.display_scale,
    );
    if tiles.is_empty() {
        return Vec::new();
    }
    let keys = tiles
        .iter()
        .filter_map(|tile| {
            nav_kv_key_for_query(&NavKvQuery::ObstacleTile {
                z: tile.z,
                x: tile.x,
                y: tile.y,
            })
        })
        .collect::<Vec<_>>();
    let Some(store) = had.store.as_ref() else {
        return Vec::new();
    };
    let missing_pages = match store.missing_pages_for_keys(&keys) {
        Ok(pages) => pages,
        Err(message) => {
            return vec![live_feed_unavailable_status_record(
                "obstacles",
                format!("Obstacle live feed unavailable: failed to query HAD pages: {message}"),
            )];
        }
    };
    if !missing_pages.is_empty() {
        for resource in
            live_obstacle_had_page_resources(session.weather.live_feeds(), &had, missing_pages)
        {
            enqueue_session_resource_effect(session, resource, [UiInvalidation::MapOverlay]);
        }
        return vec![live_feed_unavailable_status_record(
            "obstacles",
            "Obstacle live feed is waiting for visible HAD pages".to_string(),
        )];
    }

    let mut loaded_any = false;
    for tile in tiles {
        let cache_key = crate::tile_key("obstacle", tile.z, tile.x, tile.y);
        if session
            .weather
            .runtime()
            .obstacle_tile_cache
            .contains_key(&cache_key)
        {
            continue;
        }
        let Some(key) = nav_kv_key_for_query(&NavKvQuery::ObstacleTile {
            z: tile.z,
            x: tile.x,
            y: tile.y,
        }) else {
            continue;
        };
        match store.get_bytes(&key) {
            Ok(NavKvLookup::Hit(bytes)) => match serde_json::from_slice::<PointTilePayload>(&bytes)
            {
                Ok(payload) => {
                    session
                        .weather
                        .runtime_mut()
                        .obstacle_tile_cache
                        .insert(cache_key, payload);
                    loaded_any = true;
                }
                Err(err) => {
                    return vec![live_feed_unavailable_status_record(
                        "obstacles",
                        format!("Obstacle live feed unavailable: failed to parse tile: {err}"),
                    )];
                }
            },
            Ok(NavKvLookup::MissingKey) => {}
            Ok(NavKvLookup::MissingPages(pages)) => {
                for resource in
                    live_obstacle_had_page_resources(session.weather.live_feeds(), &had, pages)
                {
                    enqueue_session_resource_effect(
                        session,
                        resource,
                        [UiInvalidation::MapOverlay],
                    );
                }
            }
            Err(message) => {
                return vec![live_feed_unavailable_status_record(
                    "obstacles",
                    format!("Obstacle live feed unavailable: failed to read tile: {message}"),
                )];
            }
        }
    }
    if loaded_any {
        clear_data_status_record(session, LIVE_FEED_OBSTACLES_STATUS_ID);
    }
    Vec::new()
}

fn forecast_atmosphere_bootstrap_resources(session: &mut UiSession) -> Vec<CoreResourceRequest> {
    if session
        .weather
        .runtime()
        .forecast_atmosphere_state
        .is_none()
    {
        if !session.weather.live_feeds().current_loaded()
            || !session
                .weather
                .live_feeds()
                .has_product_current_version("winds-aloft")
        {
            return Vec::new();
        }
        if let HadOperationOutcome::NeedResources { resources } = session
            .weather
            .live_feeds()
            .sync_product_outcome_at_epoch_ms(
                "winds-aloft",
                session.coordinator.wall_clock_epoch_ms,
            )
        {
            return resources;
        }
        return Vec::new();
    }

    let Some(source) = session
        .weather
        .runtime()
        .forecast_atmosphere_state
        .as_ref()
        .map(|state| state.source.clone())
    else {
        return Vec::new();
    };
    if session.weather.runtime().forecast_atmosphere.is_none() {
        return vec![live_nav_kv_root_resource(
            session.weather.live_feeds(),
            &source,
        )];
    }
    Vec::new()
}

fn forecast_atmosphere_snapshot_resources(session: &mut UiSession) -> Vec<CoreResourceRequest> {
    let bootstrap_resources = forecast_atmosphere_bootstrap_resources(session);
    if session.coordinator.altitude_planner_wind_selection != AltitudePlannerWindSelection::Gfs {
        for resource in bootstrap_resources {
            enqueue_session_resource_effect(session, resource, [UiInvalidation::SessionSnapshot]);
        }
        return Vec::new();
    }
    if !bootstrap_resources.is_empty() {
        return bootstrap_resources;
    }

    let paths = session
        .flight_plan
        .guidance_leg_geometry()
        .values()
        .map(crate::flight_plan_materialization::geometry_points)
        .filter(|path| path.len() >= 2)
        .collect::<Vec<_>>();
    let Some(state) = session.weather.runtime().forecast_atmosphere_state.as_ref() else {
        return Vec::new();
    };
    let Some(atmosphere) = session.weather.runtime().forecast_atmosphere.as_ref() else {
        return Vec::new();
    };
    let missing_pages = match atmosphere.missing_pages_for_paths(&paths) {
        Ok(pages) => pages,
        Err(message) => {
            upsert_data_status_record(
                session,
                live_feed_unavailable_status_record(
                    "winds-aloft",
                    format!("Winds-aloft forecast unavailable for this route: {message}"),
                ),
            );
            return Vec::new();
        }
    };
    if missing_pages.is_empty() {
        let status_id = live_feed_unavailable_status_record("winds-aloft", String::new()).id;
        clear_data_status_record(session, &status_id);
        return Vec::new();
    }
    live_nav_kv_page_resources(session.weather.live_feeds(), &state.source, missing_pages)
}

