pub fn get_map_selection_for_nav_ref_in_session_with_point_display_scale_at_epoch_ms(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
    nav_ref: NavRef,
    point_display_scale: f64,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    advance_session_wall_clock(session, epoch_ms);
    let store = session_nav_kv_store(session)?;
    let position = match nav_ref_position(store, &nav_ref, None) {
        Ok(position) => position,
        Err(err) => return had_read_error_to_overlay_outcome(err),
    };
    let requested_nav_ref_point = if matches!(nav_ref, NavRef::LatLon(_) | NavRef::Spot(_)) {
        None
    } else {
        let symbol = match nav_symbol_feature(store, &nav_ref) {
            Ok(Some(symbol)) => symbol,
            Ok(None) => {
                return Err(AppError {
                    kind: AppErrorKind::InvalidCatalog,
                    message: format!("NAVDB is missing the symbol for {nav_ref:?}"),
                });
            }
            Err(err) => return had_read_error_to_overlay_outcome(err),
        };
        Some(NavRefSelectionPoint {
            feature_id: format!("nav-ref:{}", nav_ref_overlay_key(&nav_ref)),
            nav_ref: nav_ref.clone(),
            position,
            symbol,
        })
    };
    let surface_metrics =
        MapSurfaceMetrics::new(viewport, width_px, height_px, point_display_scale);
    let target_zoom =
        surface_metrics.raw_zoom_at_least_display_zoom(MAP_SELECTION_NAV_REF_MIN_FOCUS_ZOOM);
    let selection_viewport = MapViewport {
        center: position,
        zoom: target_zoom,
        ..viewport
    };
    let metrics =
        MapSurfaceMetrics::new(selection_viewport, width_px, height_px, point_display_scale);
    let selection = match materialize_map_selection_in_session(
        session,
        &metrics,
        position,
        requested_nav_ref_point.as_ref(),
    )? {
        MapSelectionMaterialization::Complete(selection) => selection,
        MapSelectionMaterialization::NeedResources(resources) => {
            return Ok(HadOperationOutcome::NeedResources { resources });
        }
    };
    let selected_item_id = crate::selected_map_selection_item_id_for_nav_ref(&selection, &nav_ref);
    Ok(HadOperationOutcome::complete(
        serde_json::to_value(MapSelectionForNavRefResult {
            position,
            target_zoom,
            selection,
            selected_item_id,
        })
        .map_err(|err| AppError {
            kind: AppErrorKind::Internal,
            message: err.to_string(),
        })?,
    ))
}

enum MapSelectionMaterialization {
    Complete(MapSelectionQueryResult),
    NeedResources(Vec<CoreResourceRequest>),
}

fn had_read_error_to_map_selection_materialization(
    err: HadReadError,
) -> AppResult<MapSelectionMaterialization> {
    match err {
        HadReadError::NeedPages(pages) => Ok(MapSelectionMaterialization::NeedResources(
            nav_kv_page_resources(pages),
        )),
        HadReadError::Fatal(message) => Err(AppError {
            kind: AppErrorKind::Internal,
            message,
        }),
    }
}

fn materialize_map_selection_in_session(
    session: &mut UiSession,
    metrics: &MapSurfaceMetrics,
    click: LatLon,
    requested_nav_ref_point: Option<&NavRefSelectionPoint>,
) -> AppResult<MapSelectionMaterialization> {
    if let Err(err) = ensure_vector_inputs_loaded(session, &metrics) {
        return had_read_error_to_map_selection_materialization(err);
    }
    if let Err(err) = ensure_weather_station_airport_aliases_loaded(session) {
        return had_read_error_to_map_selection_materialization(err);
    }
    let weather_station_airport_aliases = session
        .weather
        .runtime()
        .weather_station_airport_aliases
        .as_ref()
        .ok_or_else(|| AppError {
            kind: AppErrorKind::Internal,
            message: "weather station airport aliases did not load".to_string(),
        })?;
    let plan = session.flight_plan.active_plan();
    let store = session_nav_kv_store(session)?;
    let mut missing_pages = Vec::new();
    let mut availability = |airport_id: &str| match airport_plate_availability(store, airport_id) {
        Ok(availability) => availability,
        Err(HadReadError::NeedPages(pages)) => {
            missing_pages.extend(pages);
            AirportPlateAvailability::default()
        }
        Err(HadReadError::Fatal(_)) => AirportPlateAvailability::default(),
    };
    let offline_region_records = if session.map.layer_state().offline_regions.visible {
        match read_attached_json_optional::<crate::OfflineRegionCatalog>(
            store,
            NavKvQuery::OfflineRegionCatalog,
        ) {
            Ok(Some(catalog)) => catalog.regions,
            Ok(None) => Vec::new(),
            Err(err) => {
                return had_read_error_to_map_selection_materialization(err);
            }
        }
    } else {
        Vec::new()
    };
    let mut supplemental_nav_ref_points = match flight_plan_selection_points(session) {
        Ok(points) => points,
        Err(err) => {
            return had_read_error_to_map_selection_materialization(err);
        }
    };
    if let Some(point) = requested_nav_ref_point {
        if !supplemental_nav_ref_points
            .iter()
            .any(|existing| existing.nav_ref == point.nav_ref)
        {
            supplemental_nav_ref_points.push(point.clone());
        }
    }
    let local_time_zone = session
        .coordinator
        .platform_capabilities
        .local_time_zone
        .as_deref()
        .unwrap_or("UTC")
        .parse::<Tz>()
        .map_err(|_| AppError {
            kind: AppErrorKind::InvalidCatalog,
            message: "configured platform local time zone is invalid".to_string(),
        })?;
    let mut selection = query_map_selection_for_surface_in_time_zone(
        metrics,
        session.map.overlay_config(),
        plan,
        click,
        &session.map.runtime().vector_tile_cache,
        &session.weather.runtime().metar_tile_cache,
        session.weather.runtime().metar_payload.as_ref(),
        session.weather.runtime().pirep_payload.as_ref(),
        session.weather.runtime().taf_payload.as_ref(),
        session.weather.runtime().airport_notam_index.as_ref(),
        weather_station_airport_aliases,
        &offline_region_records,
        &session.map.runtime().airspace_feature_cache,
        session.weather.runtime().tfr_payload.as_ref(),
        &supplemental_nav_ref_points,
        &mut availability,
        Some(session_wall_clock_utc(session)),
        local_time_zone,
        session.coordinator.time_display_mode,
    );
    if !missing_pages.is_empty() {
        return Ok(MapSelectionMaterialization::NeedResources(
            nav_kv_page_resources(missing_pages),
        ));
    }
    let mut terrain_requests = terrain_elevation_requests_for_selection(session, &selection);
    match resolve_terrain_source_resources(
        session,
        terrain_requests
            .iter_mut()
            .flat_map(|request| request.source_tiles.iter_mut()),
        TerrainSourceFetchPolicy::OptionalPayload,
    ) {
        TerrainSourceResolution::NeedResources(resources) => {
            return Ok(MapSelectionMaterialization::NeedResources(resources));
        }
        TerrainSourceResolution::Unavailable { .. } | TerrainSourceResolution::Resolved => {}
    }
    selection = map_selection_with_point_details(selection, |position| {
        terrain_elevation_from_cache(session, position)
    });
    let ownship_position = session.situation.ownship().render.position;
    let selection = map_selection_with_ownship_distances(selection, ownship_position);
    let mut selection =
        map_selection_with_session_action_availability(selection, ownship_position.is_some());
    if session.coordinator.debug_state.internet_adsb && session.map.layer_state().traffic.visible {
        let traffic = session.runtime.adsb.traffic_selection_category(
            *metrics,
            crate::adsb::TrafficOwnshipAltitude {
                altitude_msl_ft: session.situation.ownship().render.altitude_msl_ft,
                pressure_altitude_ft: session.situation.ownship().render.pressure_altitude_ft,
            },
            click,
            session.coordinator.wall_clock_epoch_ms,
        );
        if let Some(item) = traffic.items.first() {
            selection.initial_selected_item_id = Some(item.id.clone());
        }
        selection.categories.push(traffic);
    }
    Ok(MapSelectionMaterialization::Complete(selection))
}

fn terrain_elevation_request_for_session(
    session: &UiSession,
    position: LatLon,
) -> Option<crate::terrain::TerrainElevationRequest> {
    match session.packages.resource_policy() {
        CoreResourcePolicy::InstalledPackage => {
            crate::terrain::terrain_elevation_request_with_available_packages(
                position,
                session.packages.installed_package_ids(),
            )
        }
        CoreResourcePolicy::PublicUnpacked => crate::terrain::terrain_elevation_request(position),
    }
}

fn terrain_elevation_requests_for_selection(
    session: &UiSession,
    selection: &MapSelectionQueryResult,
) -> Vec<crate::terrain::TerrainElevationRequest> {
    let mut requests = BTreeMap::new();
    for item in selection
        .categories
        .iter()
        .flat_map(|category| category.items.iter())
    {
        if item.elevation_msl_ft.is_some_and(f64::is_finite) {
            continue;
        }
        let Some(position) = item.position else {
            continue;
        };
        let Some(request) = terrain_elevation_request_for_session(session, position) else {
            continue;
        };
        requests.entry(request.key()).or_insert(request);
    }
    requests.into_values().collect()
}

fn terrain_elevation_from_cache(session: &UiSession, position: LatLon) -> Option<f64> {
    let request = terrain_elevation_request_for_session(session, position)?;
    let tile_bytes = request
        .source_tiles
        .iter()
        .filter_map(|source_tile| {
            session
                .map
                .runtime()
                .terrain_source_tile_cache
                .get(&terrain_source_tile_cache_key(
                    &source_tile.product_id,
                    &source_tile.path,
                ))
        })
        .map(Vec::as_slice)
        .collect::<Vec<_>>();
    crate::terrain::sample_terrain_elevation_ft(&request, position, &tile_bytes)
        .ok()
        .flatten()
}

fn enqueue_ownship_agl_terrain_effect(session: &mut UiSession) {
    if !session
        .settings
        .flight_data_cell_enabled(crate::flight_data::FLIGHT_DATA_AGL_CELL_ID)
    {
        return;
    }
    let ownship = &session.situation.ownship().render;
    if !ownship.altitude_msl_ft.is_some_and(f64::is_finite) {
        return;
    }
    let Some(position) = ownship.position else {
        return;
    };
    let Some(mut request) = terrain_elevation_request_for_session(session, position) else {
        return;
    };
    if let TerrainSourceResolution::NeedResources(resources) = resolve_terrain_source_resources(
        session,
        request.source_tiles.iter_mut(),
        TerrainSourceFetchPolicy::OptionalPayload,
    ) {
        for resource in resources {
            if resource.id.starts_with("terrain/source/")
                && !session
                    .map
                    .runtime_mut()
                    .agl_terrain_resource_ids_in_flight
                    .insert(resource.id.clone())
            {
                continue;
            }
            enqueue_session_resource_effect(session, resource, [UiInvalidation::SessionSnapshot]);
        }
    }
}

fn map_selection_with_point_details(
    mut selection: MapSelectionQueryResult,
    mut terrain_elevation: impl FnMut(LatLon) -> Option<f64>,
) -> MapSelectionQueryResult {
    for item in selection
        .categories
        .iter_mut()
        .flat_map(|category| category.items.iter_mut())
    {
        let Some(position) = item.position else {
            continue;
        };
        append_map_selection_description(
            &mut item.secondary_description,
            format!("{:.4}, {:.4}", position.lat, position.lon),
        );
        let elevation_msl_ft = item
            .elevation_msl_ft
            .filter(|value| value.is_finite())
            .or_else(|| terrain_elevation(position).filter(|value| value.is_finite()));
        let elevation = elevation_msl_ft
            .map(|value| format!("Elev {}", value.round() as i64))
            .unwrap_or_else(|| "Elev --".to_string());
        append_map_selection_description(&mut item.description, elevation);
    }
    selection
}

fn append_map_selection_description(description: &mut Option<String>, detail: String) {
    *description = Some(
        description
            .take()
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
            .map(|value| format!("{value} · {detail}"))
            .unwrap_or(detail),
    );
}

fn map_selection_with_ownship_distances(
    mut selection: MapSelectionQueryResult,
    ownship_position: Option<LatLon>,
) -> MapSelectionQueryResult {
    for item in selection
        .categories
        .iter_mut()
        .flat_map(|category| category.items.iter_mut())
    {
        let Some(point_position) = item.position else {
            continue;
        };
        item.distance = map_selection_distance(ownship_position, point_position);
    }

    selection
}

fn map_selection_distance(
    ownship_position: Option<LatLon>,
    point_position: LatLon,
) -> Option<String> {
    let distance_nm = crate::great_circle_distance_nm(ownship_position?, point_position);
    distance_nm
        .is_finite()
        .then(|| format!("{}nm", crate::flight_data::format_nm(distance_nm)))
}

fn map_selection_with_session_action_availability(
    mut selection: MapSelectionQueryResult,
    has_ownship_position: bool,
) -> MapSelectionQueryResult {
    let Some(direct_to_disabled_reason) =
        crate::planning::direct_to_ownship_disabled_reason(has_ownship_position)
    else {
        return selection;
    };

    for action in selection
        .categories
        .iter_mut()
        .flat_map(|category| category.items.iter_mut())
        .flat_map(|item| item.actions.iter_mut())
        .filter(|action| action.id == "direct_to")
    {
        action.enabled = false;
        action.disabled_reason = Some(direct_to_disabled_reason.to_string());
        action.session_action = None;
        action.flight_plan_row_action = None;
    }

    selection
}

pub fn get_terrain_overlay_in_session(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
) -> AppResult<HadOperationOutcome> {
    get_terrain_overlay_in_session_at_epoch_ms(handle, viewport, width_px, height_px, 0)
}

pub fn get_terrain_overlay_in_session_at_epoch_ms(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    get_scheduled_terrain_overlay_in_session_at_epoch_ms(
        handle,
        viewport,
        width_px,
        height_px,
        &BTreeSet::new(),
        &BTreeSet::new(),
        epoch_ms,
    )
}

pub fn get_scheduled_terrain_overlay_in_session_at_epoch_ms(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
    decoded_cache_keys: &BTreeSet<String>,
    in_flight_cache_keys: &BTreeSet<String>,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    advance_session_wall_clock(session, epoch_ms);
    let freshness_invalidations = Vec::new();
    if !session.map.layer_state().terrain_warning.visible {
        let result = TerrainOverlayQueryResult {
            status: crate::TerrainOverlayStatus::Hidden,
            tile_requests: Vec::new(),
            altitude_bucket_ft: None,
            frame_key: None,
            schedule: crate::TerrainOverlayScheduleDecision {
                cached_count: 0,
                in_flight_count: 0,
                missing_count: 0,
                frame_complete: false,
                work_batch: Vec::new(),
            },
        };
        return complete_terrain_overlay_outcome_with_invalidations(
            session,
            result,
            freshness_invalidations,
        );
    }
    let kinematics = session.situation.ownship().resolved.kinematics.as_ref();
    let has_position = kinematics.is_some_and(|kinematics| {
        kinematics.position.lat.is_finite() && kinematics.position.lon.is_finite()
    });
    let has_altitude = ownship_terrain_altitude_ft(session).is_some();
    let ownship_position = kinematics.map(|kinematics| kinematics.position);
    let terrain_altitude_ft = ownship_terrain_altitude_ft(session);
    let mut query = match session.packages.resource_policy() {
        CoreResourcePolicy::InstalledPackage => {
            crate::query_terrain_overlay_with_available_packages(
                &viewport,
                width_px,
                height_px,
                has_position,
                has_altitude,
                session.packages.installed_package_ids(),
            )
        }
        CoreResourcePolicy::PublicUnpacked => {
            crate::query_terrain_overlay(&viewport, width_px, height_px, has_position, has_altitude)
        }
    };
    crate::prepare_terrain_overlay_frame(
        &mut query,
        terrain_altitude_ft,
        ownship_position,
        &viewport,
        width_px,
        height_px,
    );
    match resolve_terrain_overlay_source_resources(session, &mut query) {
        TerrainSourceResolution::NeedResources(resources) => {
            return Ok(HadOperationOutcome::NeedResources { resources });
        }
        TerrainSourceResolution::Unavailable { reason } => {
            return complete_terrain_overlay_outcome_with_invalidations(
                session,
                TerrainOverlayQueryResult {
                    status: crate::TerrainOverlayStatus::Unavailable { reason },
                    tile_requests: Vec::new(),
                    altitude_bucket_ft: None,
                    frame_key: None,
                    schedule: crate::TerrainOverlayScheduleDecision {
                        cached_count: 0,
                        in_flight_count: 0,
                        missing_count: 0,
                        frame_complete: false,
                        work_batch: Vec::new(),
                    },
                },
                freshness_invalidations,
            );
        }
        TerrainSourceResolution::Resolved => {}
    }
    crate::schedule_terrain_overlay_frame(&mut query, decoded_cache_keys, in_flight_cache_keys);
    complete_terrain_overlay_outcome_with_invalidations(session, query, freshness_invalidations)
}

enum TerrainSourceResolution {
    Resolved,
    NeedResources(Vec<CoreResourceRequest>),
    Unavailable { reason: String },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TerrainSourceFetchPolicy {
    PlanOnly,
    OptionalPayload,
}

fn resolve_terrain_overlay_source_resources(
    session: &UiSession,
    query: &mut TerrainOverlayQueryResult,
) -> TerrainSourceResolution {
    for request in &mut query.tile_requests {
        if request.source_tiles.is_empty() {
            request.source_tiles = terrain_source_tiles(request);
        }
    }
    resolve_terrain_source_resources(
        session,
        query
            .tile_requests
            .iter_mut()
            .flat_map(|request| request.source_tiles.iter_mut()),
        TerrainSourceFetchPolicy::PlanOnly,
    )
}

fn resolve_terrain_source_resources<'a>(
    session: &UiSession,
    source_tiles: impl IntoIterator<Item = &'a mut crate::TerrainOverlaySourceTile>,
    fetch_policy: TerrainSourceFetchPolicy,
) -> TerrainSourceResolution {
    let mut pending_resources = Vec::new();
    for source_tile in source_tiles {
        let key = terrain_source_tile_cache_key(&source_tile.product_id, &source_tile.path);
        let target_resource_id = format!("terrain/source/{key}");
        let requested = match session.packages.package_resource_requests(
            &target_resource_id,
            &source_tile.product_id,
            &source_tile.path,
            fetch_policy == TerrainSourceFetchPolicy::OptionalPayload,
        ) {
            Ok(requested) => requested,
            Err(message) => {
                return TerrainSourceResolution::Unavailable {
                    reason: format!("{target_resource_id}: {message}"),
                };
            }
        };
        let mut resolved_source = false;
        let mut requested_metadata = false;
        for resource in requested {
            if resource.id == target_resource_id {
                if let CoreResourceSource::Unavailable { message } = &resource.source {
                    return TerrainSourceResolution::Unavailable {
                        reason: format!("{}: {message}", resource.id),
                    };
                }
                if fetch_policy == TerrainSourceFetchPolicy::OptionalPayload
                    && !session
                        .map
                        .runtime()
                        .terrain_source_tile_cache
                        .contains_key(&key)
                {
                    pending_resources.push(resource.clone());
                }
                source_tile.resource = Some(resource);
                resolved_source = true;
            } else {
                requested_metadata = true;
                pending_resources.push(resource);
            }
        }
        if !resolved_source && !requested_metadata {
            return TerrainSourceResolution::Unavailable {
                reason: format!("{target_resource_id}: package resolver returned no source"),
            };
        }
    }
    if !pending_resources.is_empty() {
        TerrainSourceResolution::NeedResources(dedupe_resource_requests(pending_resources))
    } else {
        TerrainSourceResolution::Resolved
    }
}

pub fn get_nexrad_overlay_in_session(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
) -> AppResult<HadOperationOutcome> {
    get_nexrad_overlay_in_session_at_epoch_ms(handle, viewport, width_px, height_px, 0)
}

pub fn get_nexrad_overlay_in_session_at_epoch_ms(
    handle: u32,
    viewport: MapViewport,
    width_px: f64,
    height_px: f64,
    epoch_ms: i64,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let previous_nexrad_banner_value = project_weather_for_session(session).nexrad_age_banner_value;
    advance_session_wall_clock(session, epoch_ms);
    let mut freshness_invalidations = Vec::new();
    if previous_nexrad_banner_value != project_weather_for_session(session).nexrad_age_banner_value
    {
        freshness_invalidations.push(UiInvalidation::SessionSnapshot);
    }
    if !session.map.layer_state().nexrad.visible {
        return complete_nexrad_overlay_outcome_with_invalidations(
            session,
            NexradOverlayQueryResult {
                status: NexradOverlayStatus::Hidden,
                tiles: Vec::new(),
                stats: NexradOverlayStats::default(),
                animation: NexradOverlayAnimation::idle(),
            },
            freshness_invalidations,
        );
    }
    match session
        .coordinator
        .platform_capabilities
        .live_feeds
        .as_ref()
        .map(|capability| capability.acquisition_policy)
    {
        Some(LiveFeedAcquisitionPolicy::JitPublicResources) => {
            if let HadOperationOutcome::NeedResources { resources } = session
                .weather
                .live_feeds()
                .sync_product_outcome_at_epoch_ms("nexrad", session.coordinator.wall_clock_epoch_ms)
            {
                return Ok(HadOperationOutcome::NeedResources { resources });
            }
            let history_resources = session
                .weather
                .live_feeds()
                .missing_history_resources_for_product_at_epoch_ms(
                    "nexrad",
                    session.coordinator.wall_clock_epoch_ms,
                );
            for resource in history_resources {
                enqueue_session_resource_effect(
                    session,
                    resource,
                    [
                        UiInvalidation::NexradOverlay,
                        UiInvalidation::SessionSnapshot,
                        UiInvalidation::DebugPanel,
                    ],
                );
            }
        }
        Some(LiveFeedAcquisitionPolicy::DurableCompleteStates) => {}
        None => {
            return Err(AppError {
                kind: AppErrorKind::Internal,
                message: "platform did not declare a live-feed acquisition policy".to_string(),
            });
        }
    }
    let frames = nexrad_frame_candidates(&session.weather);
    if frames.is_empty() {
        return complete_nexrad_overlay_outcome_with_invalidations(
            session,
            NexradOverlayQueryResult {
                status: NexradOverlayStatus::Unavailable {
                    reason: "NEXRAD product is missing from the live feed index".to_string(),
                },
                tiles: Vec::new(),
                stats: NexradOverlayStats::default(),
                animation: NexradOverlayAnimation::idle(),
            },
            freshness_invalidations,
        );
    }
    let animation = nexrad_animation_for_frames(&frames, session.coordinator.wall_clock_epoch_ms);
    let selected_frame_index = animation.selected_frame_index;
    let query = match selected_frame_index {
        Some(index) => {
            match nexrad_overlay_query(&frames[index].manifest, &viewport, width_px, height_px) {
                Ok(mut query) => {
                    query.animation = animation;
                    query
                }
                Err(err) => NexradOverlayQueryResult {
                    status: NexradOverlayStatus::Unavailable {
                        reason: err.to_string(),
                    },
                    tiles: Vec::new(),
                    stats: NexradOverlayStats::default(),
                    animation,
                },
            }
        }
        None => {
            let mut stats = NexradOverlayStats::default();
            stats.observed_at_utc = frames.last().and_then(|frame| frame.observed_at_utc);
            NexradOverlayQueryResult {
                status: NexradOverlayStatus::Ready { count: 0 },
                tiles: Vec::new(),
                stats,
                animation,
            }
        }
    };
    complete_nexrad_overlay_outcome_with_invalidations(session, query, freshness_invalidations)
}

pub fn nexrad_tile_bytes_in_session(handle: u32, src: &str) -> AppResult<Vec<u8>> {
    let slot = session_slot(handle)?;
    let session_guard = slot.lock_running()?;
    let session = &*session_guard;
    session
        .weather
        .runtime()
        .nexrad_tile_cache
        .get(src)
        .cloned()
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("NEXRAD tile bytes are not loaded for {src}"),
        })
}

fn nexrad_installed_member(src: &str) -> Option<(String, String)> {
    let src = src.trim_start_matches('/');
    let prefix = format!(
        "{}/states/nexrad/",
        LIVE_FEEDS_BASE_PATH.trim_start_matches('/')
    );
    let rest = src.strip_prefix(&prefix)?;
    let (version, tile_path) = rest.split_once("/tiles/")?;
    if version.is_empty() || tile_path.is_empty() {
        return None;
    }
    Some((version.to_string(), format!("tiles/{tile_path}")))
}

const NEXRAD_TILE_RESOURCE_PREFIX: &str = "live_feeds/nexrad_tile/";

pub fn prepare_nexrad_tile_in_session(handle: u32, src: &str) -> AppResult<HadOperationOutcome> {
    let resource = {
        let slot = session_slot(handle)?;
        let session_guard = slot.lock_running()?;
        let session = &*session_guard;
        if nexrad_tile_bytes_loaded(session, src)? {
            return Ok(HadOperationOutcome::complete(serde_json::Value::Null));
        }
        nexrad_tile_resource_request(session, src)?
    };
    Ok(HadOperationOutcome::NeedResources {
        resources: vec![resource],
    })
}

fn nexrad_tile_bytes_loaded(session: &UiSession, src: &str) -> AppResult<bool> {
    Ok(session
        .weather
        .runtime()
        .nexrad_tile_cache
        .contains_key(src))
}

fn nexrad_tile_resource_request(session: &UiSession, src: &str) -> AppResult<CoreResourceRequest> {
    let resource_id = nexrad_tile_resource_id(src)?;
    match session
        .coordinator
        .platform_capabilities
        .live_feeds
        .as_ref()
        .map(|capability| capability.acquisition_policy)
    {
        Some(LiveFeedAcquisitionPolicy::JitPublicResources) => {
            Ok(CoreResourceRequest::public_url(resource_id, src, false))
        }
        Some(LiveFeedAcquisitionPolicy::DurableCompleteStates) => {
            let (version, member_path) = nexrad_installed_member(src).ok_or_else(|| AppError {
                kind: AppErrorKind::InvalidManifest,
                message: format!("NEXRAD tile URL {src} does not identify a package member"),
            })?;
            let installed = session
                .weather
                .runtime()
                .nexrad_installed
                .get(&version)
                .ok_or_else(|| AppError {
                    kind: AppErrorKind::InvalidManifest,
                    message: format!("NEXRAD frame {version} is not installed"),
                })?;
            Ok(CoreResourceRequest::live_feed_package_member(
                resource_id,
                "nexrad",
                version,
                installed.package_blob_sha256.clone(),
                member_path,
                false,
            ))
        }
        None => Err(AppError {
            kind: AppErrorKind::Internal,
            message: "platform did not declare a live-feed acquisition policy".to_string(),
        }),
    }
}

fn nexrad_tile_resource_id(src: &str) -> AppResult<String> {
    let src = normalize_nexrad_tile_src(src)?;
    let prefix = format!(
        "{}/states/nexrad/",
        LIVE_FEEDS_BASE_PATH.trim_start_matches('/')
    );
    let suffix = src
        .trim_start_matches('/')
        .strip_prefix(&prefix)
        .ok_or_else(|| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("NEXRAD tile URL {src} is not a live-feed NEXRAD state tile"),
        })?;
    Ok(format!("{NEXRAD_TILE_RESOURCE_PREFIX}{suffix}"))
}

fn nexrad_tile_src_from_resource_id(resource_id: &str) -> Option<String> {
    let suffix = resource_id.strip_prefix(NEXRAD_TILE_RESOURCE_PREFIX)?;
    let src = format!("{LIVE_FEEDS_BASE_PATH}/states/nexrad/{suffix}");
    normalize_nexrad_tile_src(&src).ok()
}

fn normalize_nexrad_tile_src(src: &str) -> AppResult<String> {
    let trimmed = src.trim_start_matches('/');
    let prefix = format!(
        "{}/states/nexrad/",
        LIVE_FEEDS_BASE_PATH.trim_start_matches('/')
    );
    let Some(rest) = trimmed.strip_prefix(&prefix) else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("NEXRAD tile URL {src} is not a live-feed NEXRAD state tile"),
        });
    };
    if !rest.contains("/tiles/") {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("NEXRAD tile URL {src} is missing a tiles/ member path"),
        });
    }
    Ok(format!("/{trimmed}"))
}

#[derive(Debug, Deserialize)]
struct NexradSourceGridManifest {
    state_id: String,
    observed_at_utc: Option<DateTime<Utc>>,
    source_grid: NexradSourceGrid,
    levels: Vec<NexradSourceGridLevel>,
    tile_size: u32,
    tile_path_template: String,
}

#[derive(Debug, Deserialize)]
struct NexradSourceGrid {
    geo_transform: [f64; 6],
}

#[derive(Debug, Clone, Deserialize)]
struct NexradSourceGridLevel {
    res: u32,
    width: u32,
    height: u32,
    tile_cols: u32,
    tile_rows: u32,
}

fn nexrad_overlay_query(
    manifest: &serde_json::Value,
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
) -> AppResult<NexradOverlayQueryResult> {
    if width_px <= 0.0 || height_px <= 0.0 {
        return Ok(NexradOverlayQueryResult {
            status: NexradOverlayStatus::Ready { count: 0 },
            tiles: Vec::new(),
            stats: NexradOverlayStats::default(),
            animation: NexradOverlayAnimation::idle(),
        });
    }
    let manifest: NexradSourceGridManifest =
        serde_json::from_value(manifest.clone()).map_err(|err| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("failed to parse NEXRAD source-grid manifest: {err}"),
        })?;
    if manifest.tile_path_template != "tiles/res{res}/{x}/{y}.png" {
        return Ok(NexradOverlayQueryResult {
            status: NexradOverlayStatus::Unavailable {
                reason: format!(
                    "unsupported NEXRAD tile path template: {}",
                    manifest.tile_path_template
                ),
            },
            tiles: Vec::new(),
            stats: NexradOverlayStats::default(),
            animation: NexradOverlayAnimation::idle(),
        });
    }
    let viewport_bounds = viewport_lat_lon_bounds(viewport, width_px, height_px);
    let [origin_lon, pixel_lon, _rot_x, origin_lat, _rot_y, pixel_lat] =
        manifest.source_grid.geo_transform;
    let observed_at_utc = manifest.observed_at_utc.clone();
    if pixel_lon == 0.0 || pixel_lat == 0.0 {
        return Ok(NexradOverlayQueryResult {
            status: NexradOverlayStatus::Unavailable {
                reason: "NEXRAD source grid has invalid geo transform".to_string(),
            },
            tiles: Vec::new(),
            stats: NexradOverlayStats::default(),
            animation: NexradOverlayAnimation::idle(),
        });
    }
    let Some(level) = nexrad_level_for_viewport(
        &manifest.levels,
        viewport,
        width_px,
        height_px,
        pixel_lon,
        pixel_lat,
    ) else {
        return Ok(NexradOverlayQueryResult {
            status: NexradOverlayStatus::Unavailable {
                reason: "NEXRAD manifest has no resolution levels".to_string(),
            },
            tiles: Vec::new(),
            stats: NexradOverlayStats::default(),
            animation: NexradOverlayAnimation::idle(),
        });
    };
    let level_scale = 2_f64.powi(level.res as i32);
    let level_pixel_lon = pixel_lon * level_scale;
    let level_pixel_lat = pixel_lat * level_scale;
    let tile_span_lon = level_pixel_lon.abs() * manifest.tile_size as f64;
    let tile_span_lat = level_pixel_lat.abs() * manifest.tile_size as f64;
    let grid_west = origin_lon.min(origin_lon + level_pixel_lon * level.width as f64);
    let grid_east = origin_lon.max(origin_lon + level_pixel_lon * level.width as f64);
    let grid_south = origin_lat.min(origin_lat + level_pixel_lat * level.height as f64);
    let grid_north = origin_lat.max(origin_lat + level_pixel_lat * level.height as f64);
    let west = viewport_bounds.west.max(grid_west);
    let east = viewport_bounds.east.min(grid_east);
    let south = viewport_bounds.south.max(grid_south);
    let north = viewport_bounds.north.min(grid_north);
    if west >= east || south >= north {
        return Ok(NexradOverlayQueryResult {
            status: NexradOverlayStatus::Ready { count: 0 },
            tiles: Vec::new(),
            stats: NexradOverlayStats::default(),
            animation: NexradOverlayAnimation::idle(),
        });
    }

    let x_start = (((west - grid_west) / tile_span_lon).floor() as i64)
        .clamp(0, level.tile_cols as i64 - 1) as u32;
    let x_end = (((east - grid_west) / tile_span_lon).floor() as i64)
        .clamp(0, level.tile_cols as i64 - 1) as u32;
    let y_start = (((grid_north - north) / tile_span_lat).floor() as i64)
        .clamp(0, level.tile_rows as i64 - 1) as u32;
    let y_end = (((grid_north - south) / tile_span_lat).floor() as i64)
        .clamp(0, level.tile_rows as i64 - 1) as u32;

    const NEXRAD_RENDER_MAX_SOURCE_SLICE_PX: u32 = 256;
    const NEXRAD_RENDER_MAX_AFFINE_ERROR_PX: f64 = 1.0;
    const NEXRAD_MAX_LEVEL_PIXEL_STRETCH_PX: f64 = 1.5;
    let mut tiles = Vec::new();
    let mut stats = NexradOverlayStats {
        source_tile_count: ((x_end - x_start + 1) as usize) * ((y_end - y_start + 1) as usize),
        level_pixel_span_px: nexrad_level_screen_pixel_span(
            viewport, width_px, height_px, pixel_lon, pixel_lat, level.res,
        ),
        max_level_pixel_stretch_px: NEXRAD_MAX_LEVEL_PIXEL_STRETCH_PX,
        res: Some(level.res),
        observed_at_utc,
        ..NexradOverlayStats::default()
    };
    for y in y_start..=y_end {
        for x in x_start..=x_end {
            let tile_level_x0 = x * manifest.tile_size;
            let tile_level_y0 = y * manifest.tile_size;
            let image_width = manifest.tile_size.min(level.width - tile_level_x0);
            let image_height = manifest.tile_size.min(level.height - tile_level_y0);
            let src = format!(
                "{LIVE_FEEDS_BASE_PATH}/states/nexrad/{}/tiles/res{}/{}/{}.png",
                manifest.state_id, level.res, x, y
            );
            let mut stack = vec![(0, 0, image_width, image_height)];
            while let Some((source_x, source_y, source_width, source_height)) = stack.pop() {
                stats.max_stack_depth = stats.max_stack_depth.max(stack.len() + 1);
                let affine_error_px = nexrad_render_piece_affine_error_px(
                    viewport,
                    width_px,
                    height_px,
                    origin_lon,
                    level_pixel_lon,
                    origin_lat,
                    level_pixel_lat,
                    tile_level_x0 + source_x,
                    tile_level_y0 + source_y,
                    source_width,
                    source_height,
                );
                if source_width > 1
                    && (source_width > NEXRAD_RENDER_MAX_SOURCE_SLICE_PX
                        || affine_error_px > NEXRAD_RENDER_MAX_AFFINE_ERROR_PX)
                    && source_width >= source_height
                {
                    stats.split_count += 1;
                    let left_width = source_width / 2;
                    let right_width = source_width - left_width;
                    stack.push((source_x + left_width, source_y, right_width, source_height));
                    stack.push((source_x, source_y, left_width, source_height));
                    continue;
                }
                if source_height > 1
                    && (source_height > NEXRAD_RENDER_MAX_SOURCE_SLICE_PX
                        || affine_error_px > NEXRAD_RENDER_MAX_AFFINE_ERROR_PX)
                {
                    stats.split_count += 1;
                    let top_height = source_height / 2;
                    let bottom_height = source_height - top_height;
                    stack.push((source_x, source_y + top_height, source_width, bottom_height));
                    stack.push((source_x, source_y, source_width, top_height));
                    continue;
                }

                stats.render_piece_count += 1;
                stats.max_affine_error_px = stats.max_affine_error_px.max(affine_error_px);
                let level_x0 = tile_level_x0 + source_x;
                let level_x1 = level_x0 + source_width;
                let level_y0 = tile_level_y0 + source_y;
                let level_y1 = level_y0 + source_height;
                let lon0 = origin_lon + level_pixel_lon * level_x0 as f64;
                let lon1 = origin_lon + level_pixel_lon * level_x1 as f64;
                let lat0 = origin_lat + level_pixel_lat * level_y0 as f64;
                let lat1 = origin_lat + level_pixel_lat * level_y1 as f64;
                let west = lon0.min(lon1).max(grid_west);
                let east = lon0.max(lon1).min(grid_east);
                let south = lat0.min(lat1).max(grid_south);
                let north = lat0.max(lat1).min(grid_north);
                let corners = NexradOverlayTileCorners {
                    nw: screen_point_for_lat_lon(viewport, width_px, height_px, north, west),
                    ne: screen_point_for_lat_lon(viewport, width_px, height_px, north, east),
                    se: screen_point_for_lat_lon(viewport, width_px, height_px, south, east),
                    sw: screen_point_for_lat_lon(viewport, width_px, height_px, south, west),
                };
                tiles.push(NexradOverlayTile {
                    key: format!(
                        "nexrad/{}/res{}/{}/{}/{}/{}",
                        manifest.state_id, level.res, x, y, source_x, source_y
                    ),
                    src: src.clone(),
                    res: level.res,
                    x,
                    y,
                    source_x,
                    source_y,
                    source_width,
                    source_height,
                    image_width,
                    image_height,
                    corners,
                });
            }
        }
    }

    Ok(NexradOverlayQueryResult {
        status: NexradOverlayStatus::Ready { count: tiles.len() },
        stats,
        tiles,
        animation: NexradOverlayAnimation::idle(),
    })
}

fn nexrad_render_piece_affine_error_px(
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
    origin_lon: f64,
    level_pixel_lon: f64,
    origin_lat: f64,
    level_pixel_lat: f64,
    level_x0: u32,
    level_y0: u32,
    source_width: u32,
    source_height: u32,
) -> f64 {
    let lon0 = origin_lon + level_pixel_lon * level_x0 as f64;
    let lon1 = origin_lon + level_pixel_lon * (level_x0 + source_width) as f64;
    let lat0 = origin_lat + level_pixel_lat * level_y0 as f64;
    let lat1 = origin_lat + level_pixel_lat * (level_y0 + source_height) as f64;
    let west = lon0.min(lon1);
    let east = lon0.max(lon1);
    let south = lat0.min(lat1);
    let north = lat0.max(lat1);
    let true_center = screen_point_for_lat_lon(
        viewport,
        width_px,
        height_px,
        (north + south) * 0.5,
        (west + east) * 0.5,
    );
    let nw = screen_point_for_lat_lon(viewport, width_px, height_px, north, west);
    let ne = screen_point_for_lat_lon(viewport, width_px, height_px, north, east);
    let se = screen_point_for_lat_lon(viewport, width_px, height_px, south, east);
    let sw = screen_point_for_lat_lon(viewport, width_px, height_px, south, west);
    let affine_center = ScreenPoint {
        x: (nw.x + ne.x + se.x + sw.x) * 0.25,
        y: (nw.y + ne.y + se.y + sw.y) * 0.25,
    };
    ((true_center.x - affine_center.x).powi(2) + (true_center.y - affine_center.y).powi(2)).sqrt()
}

fn nexrad_level_for_viewport(
    levels: &[NexradSourceGridLevel],
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
    source_pixel_lon: f64,
    source_pixel_lat: f64,
) -> Option<NexradSourceGridLevel> {
    const NEXRAD_MAX_PIXEL_STRETCH: f64 = 1.5;
    levels
        .iter()
        .filter(|level| {
            nexrad_level_screen_pixel_span(
                viewport,
                width_px,
                height_px,
                source_pixel_lon,
                source_pixel_lat,
                level.res,
            ) <= NEXRAD_MAX_PIXEL_STRETCH
        })
        .max_by_key(|level| level.res)
        .or_else(|| levels.iter().min_by_key(|level| level.res))
        .cloned()
}

fn nexrad_level_screen_pixel_span(
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
    source_pixel_lon: f64,
    source_pixel_lat: f64,
    res: u32,
) -> f64 {
    let scale = 2_f64.powi(res as i32);
    let center = screen_point_for_lat_lon(
        viewport,
        width_px,
        height_px,
        viewport.center.lat,
        viewport.center.lon,
    );
    let horizontal = screen_point_for_lat_lon(
        viewport,
        width_px,
        height_px,
        viewport.center.lat,
        viewport.center.lon + source_pixel_lon * scale,
    );
    let vertical = screen_point_for_lat_lon(
        viewport,
        width_px,
        height_px,
        viewport.center.lat + source_pixel_lat * scale,
        viewport.center.lon,
    );
    (horizontal.x - center.x)
        .abs()
        .max((vertical.y - center.y).abs())
}

fn viewport_lat_lon_bounds(
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
) -> crate::GeoBounds {
    let center_world = lat_lon_to_world_xy(viewport.center.lat, viewport.center.lon);
    let scale = scale_for_map_zoom(viewport.zoom);
    let corners = [
        world_to_lat_lon(
            center_world.0 - width_px / 2.0 / scale,
            center_world.1 - height_px / 2.0 / scale,
        ),
        world_to_lat_lon(
            center_world.0 + width_px / 2.0 / scale,
            center_world.1 - height_px / 2.0 / scale,
        ),
        world_to_lat_lon(
            center_world.0 + width_px / 2.0 / scale,
            center_world.1 + height_px / 2.0 / scale,
        ),
        world_to_lat_lon(
            center_world.0 - width_px / 2.0 / scale,
            center_world.1 + height_px / 2.0 / scale,
        ),
    ];
    crate::GeoBounds {
        south: corners
            .iter()
            .map(|point| point.lat)
            .fold(f64::INFINITY, f64::min),
        west: corners
            .iter()
            .map(|point| point.lon)
            .fold(f64::INFINITY, f64::min),
        north: corners
            .iter()
            .map(|point| point.lat)
            .fold(f64::NEG_INFINITY, f64::max),
        east: corners
            .iter()
            .map(|point| point.lon)
            .fold(f64::NEG_INFINITY, f64::max),
    }
}

fn screen_point_for_lat_lon(
    viewport: &MapViewport,
    width_px: f64,
    height_px: f64,
    lat: f64,
    lon: f64,
) -> ScreenPoint {
    let center_world = lat_lon_to_world_xy(viewport.center.lat, viewport.center.lon);
    let point_world = lat_lon_to_world_xy(lat, lon);
    let scale = scale_for_map_zoom(viewport.zoom);
    ScreenPoint {
        x: (point_world.0 - center_world.0) * scale + width_px / 2.0,
        y: (point_world.1 - center_world.1) * scale + height_px / 2.0,
    }
}

fn scale_for_map_zoom(zoom: f64) -> f64 {
    2.0_f64.powf(zoom)
}

fn lat_lon_to_world_xy(lat: f64, lon: f64) -> (f64, f64) {
    const WORLD_SIZE: f64 = 256.0;
    const MAX_LATITUDE: f64 = 85.051_128_78;
    let clamped_lat = lat.clamp(-MAX_LATITUDE, MAX_LATITUDE);
    let lat_rad = clamped_lat.to_radians();
    (
        ((lon + 180.0) / 360.0) * WORLD_SIZE,
        ((1.0 - lat_rad.tan().asinh() / std::f64::consts::PI) / 2.0) * WORLD_SIZE,
    )
}

fn world_to_lat_lon(world_x: f64, world_y: f64) -> LatLon {
    const WORLD_SIZE: f64 = 256.0;
    let lon = world_x / WORLD_SIZE * 360.0 - 180.0;
    let n = std::f64::consts::PI * (1.0 - 2.0 * world_y / WORLD_SIZE);
    let lat = n.sinh().atan().to_degrees();
    LatLon { lat, lon }
}

fn terrain_source_tiles(
    request: &crate::TerrainOverlayTileRequest,
) -> Vec<crate::TerrainOverlaySourceTile> {
    if request.source_tiles.is_empty() {
        vec![crate::TerrainOverlaySourceTile {
            product_id: request.product_id.clone(),
            path: request.path.clone(),
            resource: None,
        }]
    } else {
        request.source_tiles.clone()
    }
}

fn terrain_source_tile_cache_key(product_id: &str, path: &str) -> String {
    format!("{product_id}/{path}")
}

pub fn render_terrain_overlay_tile_in_session(
    handle: u32,
    tile_bytes: &[u8],
    aircraft_altitude_ft: Option<f64>,
) -> AppResult<Vec<u8>> {
    let slot = session_slot(handle)?;
    let session_guard = slot.lock_running()?;
    let session = &*session_guard;
    let altitude_ft = aircraft_altitude_ft
        .filter(|altitude| altitude.is_finite())
        .or_else(|| ownship_terrain_altitude_ft(session))
        .ok_or_else(|| AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: "ownship altitude unavailable for terrain overlay".to_string(),
        })?;
    crate::render_terrain_warning_raw_rgba_from_tiles(&[tile_bytes], altitude_ft).map_err(|err| {
        AppError {
            kind: AppErrorKind::InvalidManifest,
            message: err,
        }
    })
}

pub fn render_terrain_overlay_tile_by_key_in_session(
    handle: u32,
    tile_key: &str,
    aircraft_altitude_ft: Option<f64>,
) -> AppResult<Vec<u8>> {
    let slot = session_slot(handle)?;
    let session_guard = slot.lock_running()?;
    let session = &*session_guard;
    let altitude_ft = aircraft_altitude_ft
        .filter(|altitude| altitude.is_finite())
        .or_else(|| ownship_terrain_altitude_ft(session))
        .ok_or_else(|| AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: "ownship altitude unavailable for terrain overlay".to_string(),
        })?;
    let Some(path) = tile_key.strip_prefix("terrain/") else {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("invalid terrain tile key {tile_key}"),
        });
    };
    let tile_bytes = session
        .map
        .runtime()
        .terrain_source_tile_cache
        .iter()
        .filter_map(|(source_key, bytes)| source_key.strip_suffix(path).map(|_| bytes.as_slice()))
        .collect::<Vec<_>>();
    if tile_bytes.is_empty() {
        return Err(AppError {
            kind: AppErrorKind::InvalidManifest,
            message: format!("terrain tile bytes missing for {tile_key}"),
        });
    }
    crate::render_terrain_warning_raw_rgba_from_tiles(&tile_bytes, altitude_ft).map_err(|err| {
        AppError {
            kind: AppErrorKind::InvalidManifest,
            message: err,
        }
    })
}

pub fn render_terrain_overlay_tiles_in_session(
    handle: u32,
    packed_tile_bytes: &[u8],
    aircraft_altitude_ft: Option<f64>,
) -> AppResult<Vec<u8>> {
    let slot = session_slot(handle)?;
    let session_guard = slot.lock_running()?;
    let session = &*session_guard;
    let altitude_ft = aircraft_altitude_ft
        .filter(|altitude| altitude.is_finite())
        .or_else(|| ownship_terrain_altitude_ft(session))
        .ok_or_else(|| AppError {
            kind: AppErrorKind::UnsupportedOperation,
            message: "ownship altitude unavailable for terrain overlay".to_string(),
        })?;
    let unpacked_tiles =
        unpack_packed_terrain_tiles(packed_tile_bytes).map_err(|err| AppError {
            kind: AppErrorKind::InvalidManifest,
            message: err,
        })?;
    let tile_refs = unpacked_tiles.iter().map(Vec::as_slice).collect::<Vec<_>>();
    crate::render_terrain_warning_raw_rgba_from_tiles(&tile_refs, altitude_ft).map_err(|err| {
        AppError {
            kind: AppErrorKind::InvalidManifest,
            message: err,
        }
    })
}

fn unpack_packed_terrain_tiles(packed_tile_bytes: &[u8]) -> Result<Vec<Vec<u8>>, String> {
    fn read_u32(bytes: &[u8], cursor: &mut usize) -> Result<u32, String> {
        let end = *cursor + 4;
        let chunk = bytes
            .get(*cursor..end)
            .ok_or_else(|| "truncated packed terrain tile header".to_string())?;
        *cursor = end;
        Ok(u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
    }

    let mut cursor = 0;
    let tile_count = read_u32(packed_tile_bytes, &mut cursor)? as usize;
    let mut tiles = Vec::with_capacity(tile_count);
    for _ in 0..tile_count {
        let byte_count = read_u32(packed_tile_bytes, &mut cursor)? as usize;
        let end = cursor + byte_count;
        let tile_bytes = packed_tile_bytes
            .get(cursor..end)
            .ok_or_else(|| "truncated packed terrain tile body".to_string())?;
        tiles.push(tile_bytes.to_vec());
        cursor = end;
    }
    if cursor != packed_tile_bytes.len() {
        return Err("packed terrain tile payload has trailing bytes".to_string());
    }
    Ok(tiles)
}

pub fn destroy_session(handle: u32) {
    let slot = lock_session_registry().remove(&handle);
    if let Some(slot) = slot {
        slot.close();
    }
}

fn ownship_terrain_altitude_ft(session: &UiSession) -> Option<f64> {
    session
        .situation
        .ownship()
        .resolved
        .kinematics
        .as_ref()
        .and_then(|kinematics| {
            kinematics
                .altitude_msl_ft
                .or(kinematics.pressure_altitude_ft)
        })
}

fn ownship_overlay_context(session: &UiSession) -> Option<crate::ObstacleOverlayContext> {
    let kinematics = session.situation.ownship().resolved.kinematics.as_ref()?;
    Some(crate::ObstacleOverlayContext {
        position: kinematics.position,
        track_deg_true: kinematics.track_deg_true,
        ground_speed_kt: kinematics.ground_speed_kt,
        altitude_ft: kinematics
            .altitude_msl_ft
            .or(kinematics.pressure_altitude_ft),
    })
}

fn session_plan(session: &UiSession) -> AppResult<FlightPlan> {
    session
        .flight_plan
        .active_plan()
        .cloned()
        .ok_or_else(|| AppError {
            kind: AppErrorKind::Internal,
            message: "session missing active plan".to_string(),
        })
}

fn session_nav_kv_store(session: &UiSession) -> AppResult<&NavKvStore> {
    session.nav_data.store().ok_or_else(|| AppError {
        kind: AppErrorKind::Internal,
        message: "session missing nav kv store".to_string(),
    })
}

fn read_chart_asset_by_id(
    store: &NavKvStore,
    chart_id: &str,
) -> Result<ChartAssetRecord, HadReadError> {
    let key = nav_kv_key_for_query(&NavKvQuery::PlateById {
        plate_id: chart_id.to_string(),
    })
    .ok_or_else(|| HadReadError::Fatal("invalid chart asset id query".to_string()))?;
    match store.get_bytes(&key).map_err(HadReadError::Fatal)? {
        NavKvLookup::Hit(bytes) => serde_json::from_slice(&bytes)
            .map_err(|err| HadReadError::Fatal(format!("HAD JSON decode failed for {key}: {err}"))),
        NavKvLookup::MissingKey => Err(HadReadError::Fatal(format!(
            "HAD missing required chart asset key: {key}"
        ))),
        NavKvLookup::MissingPages(pages) => Err(HadReadError::NeedPages(pages)),
    }
}

fn airport_plate_availability(
    store: &NavKvStore,
    airport_id: &str,
) -> Result<AirportPlateAvailability, HadReadError> {
    let key = nav_kv_key_for_query(&NavKvQuery::PlateAirport {
        airport_id: airport_id.to_ascii_uppercase(),
    })
    .ok_or_else(|| HadReadError::Fatal("invalid plate airport query".to_string()))?;
    match store.get_bytes(&key).map_err(HadReadError::Fatal)? {
        NavKvLookup::Hit(bytes) => {
            let airport: crate::chart_page::PlateAirportRecord = serde_json::from_slice(&bytes)
                .map_err(|err| {
                    HadReadError::Fatal(format!("HAD JSON decode failed for {key}: {err}"))
                })?;
            Ok(AirportPlateAvailability {
                plates: !airport.chart_ids.is_empty(),
                csup: airport.chart_ids.iter().any(|chart_id| {
                    chart_id
                        .get(..5)
                        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("csup:"))
                }),
            })
        }
        NavKvLookup::MissingKey => Ok(AirportPlateAvailability::default()),
        NavKvLookup::MissingPages(pages) => Err(HadReadError::NeedPages(pages)),
    }
}

fn replace_session_flight_plan(session: &mut UiSession, plan: FlightPlan) -> AppResult<()> {
    let normalized_plan = session.flight_plan.replace_plan(plan)?.clone();
    refresh_session_flight_plan_derivatives(session, &normalized_plan);
    Ok(())
}

fn refresh_session_flight_plan_derivatives(session: &mut UiSession, normalized_plan: &FlightPlan) {
    session.coordinator.last_content_report = None;
    session.coordinator.chart_page_state = derive_compact_chart_page_state_with_reference(
        normalized_plan,
        &session.coordinator.chart_page_state.recent_airport_ids,
        session
            .coordinator
            .chart_page_state
            .plate_target_airport_id
            .as_deref(),
        Some(&session.coordinator.chart_page_state.selected_airport_id),
        session
            .coordinator
            .chart_page_state
            .selected_reference_family_id
            .as_deref(),
        Some(&session.coordinator.chart_page_state.selected_chart_id),
        &session.coordinator.chart_page_state.suggested_chart_ids,
    );
    sync_procedure_geometry_status_records(session, normalized_plan);
}

fn commit_session_flight_plan_edit_with_invalidations_outcome(
    session: &mut UiSession,
    plan: FlightPlan,
) -> AppResult<HadOperationOutcome> {
    let started = crate::CoreDebugTimer::start();
    let prior_plan = session
        .flight_plan
        .active_plan()
        .cloned()
        .ok_or_else(|| missing_active_plan_error("flight-plan mutation"))?;
    run_session_model_transaction(session, |session| {
        let accepted_plan = session.flight_plan.apply_definition_edit(plan)?.clone();
        refresh_session_flight_plan_derivatives(session, &accepted_plan);
        let wall_clock_epoch_ms = session.coordinator.wall_clock_epoch_ms;
        let definition_changed = session.cloud.record_local_flight_plan_mutation(
            &prior_plan,
            &accepted_plan,
            wall_clock_epoch_ms,
        )?;
        if !definition_changed && accepted_plan.guidance.is_none() {
            if let Some(remote_plan) = session.cloud.take_pending_remote_flight_plan() {
                replace_session_flight_plan(session, remote_plan)?;
            }
        }
        sync_guidance_geometry_for_session(session, &started)?;
        Ok(vec![
            UiInvalidation::SessionSnapshot,
            UiInvalidation::FlightPlanRoute,
            UiInvalidation::MapOverlay,
        ])
    })
}

fn commit_session_navigation_update_with_invalidations_outcome(
    session: &mut UiSession,
    plan: FlightPlan,
) -> AppResult<HadOperationOutcome> {
    let started = crate::CoreDebugTimer::start();
    run_session_model_transaction(session, |session| {
        session.flight_plan.apply_navigation_update(plan)?;
        if session
            .flight_plan
            .active_plan()
            .is_some_and(|plan| plan.guidance.is_none())
        {
            if let Some(remote_plan) = session.cloud.take_pending_remote_flight_plan() {
                replace_session_flight_plan(session, remote_plan)?;
            }
        }
        sync_guidance_geometry_for_session(session, &started)?;
        Ok(vec![
            UiInvalidation::SessionSnapshot,
            UiInvalidation::FlightPlanRoute,
            UiInvalidation::MapOverlay,
        ])
    })
}

#[derive(Debug, Clone, Copy)]
enum FlightPlanHistoryDirection {
    Undo,
    Redo,
}

fn move_flight_plan_history_in_session(
    handle: u32,
    direction: FlightPlanHistoryDirection,
) -> AppResult<HadOperationOutcome> {
    let slot = session_slot(handle)?;
    let mut session_guard = slot.lock_running()?;
    let session = &mut *session_guard;
    let started = crate::CoreDebugTimer::start();
    let prior_plan = session
        .flight_plan
        .active_plan()
        .cloned()
        .ok_or_else(|| missing_active_plan_error("flight-plan history mutation"))?;
    run_session_model_transaction(session, |session| {
        let accepted_plan = match direction {
            FlightPlanHistoryDirection::Undo => session.flight_plan.undo_definition_edit()?.clone(),
            FlightPlanHistoryDirection::Redo => session.flight_plan.redo_definition_edit()?.clone(),
        };
        refresh_session_flight_plan_derivatives(session, &accepted_plan);
        session.cloud.record_local_flight_plan_mutation(
            &prior_plan,
            &accepted_plan,
            session.coordinator.wall_clock_epoch_ms,
        )?;
        sync_guidance_geometry_for_session(session, &started)?;
        Ok(vec![
            UiInvalidation::SessionSnapshot,
            UiInvalidation::FlightPlanRoute,
            UiInvalidation::MapOverlay,
        ])
    })
}

fn advance_session_revision(session: &mut UiSession) {
    session.coordinator.session_revision = session.coordinator.session_revision.saturating_add(1);
}

#[derive(Debug)]
enum SessionSnapshotProjectionError {
    NeedResources(Vec<CoreResourceRequest>),
    Had(HadReadError),
}

impl From<HadReadError> for SessionSnapshotProjectionError {
    fn from(error: HadReadError) -> Self {
        Self::Had(error)
    }
}

fn session_snapshot_outcome(session: &mut UiSession) -> AppResult<HadOperationOutcome> {
    session_snapshot_outcome_with_invalidations(session, Vec::new())
}

// Layer commands do not change the snapshot's HAD read set. Fault every required page
// before mutating so NeedResources remains side-effect free across platform retries.
fn preflight_session_snapshot_resources(
    session: &mut UiSession,
) -> AppResult<Option<HadOperationOutcome>> {
    match try_snapshot_for_session(session) {
        Ok(_) => Ok(None),
        Err(SessionSnapshotProjectionError::NeedResources(resources)) => {
            Ok(Some(HadOperationOutcome::NeedResources { resources }))
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::NeedPages(pages))) => {
            Ok(Some(HadOperationOutcome::NeedResources {
                resources: nav_kv_page_resources(pages),
            }))
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::Fatal(message))) => Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message,
        }),
    }
}

fn changed_session_update_outcome(session: &mut UiSession) -> AppResult<HadOperationOutcome> {
    changed_session_update_outcome_with_invalidations(session, Vec::new())
}

// Use this only after an infallible model commit. Snapshot paging is a continuation,
// so NeedSnapshotResources retains the committed revision. Fallible mutations and
// durable writes must use run_session_model_transaction instead.
fn changed_session_update_outcome_with_invalidations(
    session: &mut UiSession,
    mut invalidations: Vec<UiInvalidation>,
) -> AppResult<HadOperationOutcome> {
    let previous_versions = session.projection_versions.versions();
    advance_session_revision(session);
    dedupe_invalidations(&mut invalidations);
    match try_project_session_update(session, previous_versions) {
        Ok(update) => serde_json::to_value(update)
            .map(|update| {
                if invalidations.is_empty() {
                    HadOperationOutcome::complete(update)
                } else {
                    HadOperationOutcome::complete_with_invalidations(update, invalidations)
                }
            })
            .map_err(|err| AppError {
                kind: AppErrorKind::Internal,
                message: err.to_string(),
            }),
        Err(SessionSnapshotProjectionError::NeedResources(resources)) => {
            Ok(HadOperationOutcome::NeedSnapshotResources {
                resources,
                invalidations,
            })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::NeedPages(pages))) => {
            Ok(HadOperationOutcome::NeedSnapshotResources {
                resources: nav_kv_page_resources(pages),
                invalidations,
            })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::Fatal(message))) => Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message,
        }),
    }
}

fn session_snapshot_outcome_with_invalidations(
    session: &mut UiSession,
    mut invalidations: Vec<UiInvalidation>,
) -> AppResult<HadOperationOutcome> {
    dedupe_invalidations(&mut invalidations);
    match try_snapshot_for_session(session) {
        Ok(snapshot) => serde_json::to_value(snapshot)
            .map(|snapshot| {
                if invalidations.is_empty() {
                    HadOperationOutcome::complete(snapshot)
                } else {
                    HadOperationOutcome::complete_with_invalidations(snapshot, invalidations)
                }
            })
            .map_err(|err| AppError {
                kind: AppErrorKind::Internal,
                message: err.to_string(),
            }),
        Err(SessionSnapshotProjectionError::NeedResources(resources)) => {
            Ok(HadOperationOutcome::NeedResources { resources })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::NeedPages(pages))) => {
            Ok(HadOperationOutcome::NeedResources {
                resources: nav_kv_page_resources(pages),
            })
        }
        Err(SessionSnapshotProjectionError::Had(HadReadError::Fatal(message))) => Err(AppError {
            kind: AppErrorKind::InvalidFlightPlan,
            message,
        }),
    }
}

fn session_projection_dependencies(
    session: &UiSession,
    snapshot: &UiSessionSnapshot,
    next_nav_db_maintenance_epoch_ms: Option<i64>,
) -> SessionProjectionDependencies {
    let capabilities = &session.coordinator.platform_capabilities;
    let cloud_available = capabilities.cloud.is_some();
    let application_shell = ApplicationShellProjectionDependencies {
        content_policy: session.coordinator.content_policy,
        last_content_report: session.coordinator.last_content_report.clone(),
    };
    SessionProjectionDependencies {
        envelope: session.coordinator.session_revision,
        nav_data: NavDataProjectionDependencies {
            nav_data_revision: session.nav_data.revision(),
            package_revision: session.packages.revision(),
            next_maintenance_epoch_ms: next_nav_db_maintenance_epoch_ms,
        },
        application_shell,
        flight_plan: FlightPlanProjectionDependencies {
            route_revision: session.flight_plan.route_revision(),
            active_plan: snapshot.app_ui_state.active_plan.clone(),
            aircraft_plan_view_path: snapshot.app_ui_state.aircraft_plan_view_path.clone(),
        },
        ownship: snapshot.app_ui_state.ownship.clone(),
        flight_data: FlightDataProjectionDependencies {
            banner: snapshot.app_ui_state.flight_data_banner.clone(),
            settings_items: snapshot
                .settings_page_state
                .rows
                .first()
                .map(|row| row.items.clone())
                .unwrap_or_default(),
            next_refresh_epoch_ms: snapshot.next_session_snapshot_refresh_epoch_ms,
        },
        situation: session.situation.revision(),
        charts: session.coordinator.chart_page_state.clone(),
        map: MapProjectionDependencies {
            map_revision: session.map.revision(),
            internet_adsb_enabled: session.coordinator.debug_state.internet_adsb,
        },
        status: StatusProjectionDependencies {
            data_status_revision: session.data_status.revision(),
            page_projection_revision: session.data_status.page_projection_revision(),
            next_freshness_check_epoch_ms: session
                .coordinator
                .cycle_product_freshness
                .next_check_epoch_ms,
        },
        settings: SettingsProjectionDependencies {
            static_revision: session.settings.static_revision(),
            display_policy_available: capabilities.display_policy.is_some(),
            debug_state: session.coordinator.debug_state.clone(),
        },
        cloud: CloudProjectionDependencies {
            projection_revision: session.cloud.projection_revision(),
        },
        packages: session.packages.revision(),
        home: HomeProjectionDependencies {
            offline_packages_available: capabilities.offline_packages.is_some(),
            cloud_available,
        },
        debug: session.coordinator.debug_state.clone(),
    }
}

fn refresh_session_projection_versions(
    session: &mut UiSession,
    snapshot: &UiSessionSnapshot,
    next_nav_db_maintenance_epoch_ms: Option<i64>,
) {
    let dependencies =
        session_projection_dependencies(session, snapshot, next_nav_db_maintenance_epoch_ms);
    session.projection_versions.observe(dependencies);
}

fn try_project_session_update(
    session: &mut UiSession,
    previous_versions: SessionProjectionVersions,
) -> Result<UiSessionUpdate, SessionSnapshotProjectionError> {
    let started_at = crate::core_clock_ms();
    let snapshot = try_snapshot_for_session(session)?;
    let current_versions = session.projection_versions.versions();
    let update = assemble_session_update(&snapshot, previous_versions, current_versions);
    session
        .diagnostics
        .record_session_update(&update, debug_elapsed_us(started_at));
    Ok(update)
}

fn changed_projection_patch(
    previous_version: u64,
    current_version: u64,
    assignments: impl FnOnce() -> Vec<UiSessionProjectionAssignment>,
) -> Option<UiSessionProjectionPatch> {
    (previous_version != current_version).then(|| UiSessionProjectionPatch {
        version: current_version,
        assignments: assignments(),
    })
}

macro_rules! projection_assignments {
    ($([$($segment:literal),+] => $value:expr),* $(,)?) => {{
        vec![$(UiSessionProjectionAssignment {
            path: vec![$($segment.to_string()),+],
            value: serde_json::json!($value),
        }),*]
    }};
}

fn assemble_session_update(
    snapshot: &UiSessionSnapshot,
    previous: SessionProjectionVersions,
    current: SessionProjectionVersions,
) -> UiSessionUpdate {
    let settings_changed = previous.settings != current.settings;
    UiSessionUpdate {
        ui_contract_version: snapshot.ui_contract_version,
        session_revision: snapshot.session_revision,
        nav_data: changed_projection_patch(previous.nav_data, current.nav_data, || {
            projection_assignments! {
                ["nav_data_epoch"] => snapshot.nav_data_epoch,
                ["active_nav_db"] => snapshot.active_nav_db,
                ["next_nav_db_maintenance_epoch_ms"] => snapshot.next_nav_db_maintenance_epoch_ms,
            }
        }),
        application_shell: changed_projection_patch(
            previous.application_shell,
            current.application_shell,
            || {
                projection_assignments! {
                    ["app_ui_state", "content_policy"] => snapshot.app_ui_state.content_policy,
                    ["app_ui_state", "last_content_report"] => snapshot.app_ui_state.last_content_report,
                }
            },
        ),
        flight_plan: changed_projection_patch(previous.flight_plan, current.flight_plan, || {
            projection_assignments! {
                ["flight_plan_route_revision"] => snapshot.flight_plan_route_revision,
                ["app_ui_state", "active_plan"] => snapshot.app_ui_state.active_plan,
                ["app_ui_state", "aircraft_plan_view_path"] => snapshot.app_ui_state.aircraft_plan_view_path,
            }
        }),
        ownship: changed_projection_patch(previous.ownship, current.ownship, || {
            projection_assignments! {
                ["app_ui_state", "ownship"] => snapshot.app_ui_state.ownship,
            }
        }),
        flight_data: changed_projection_patch(previous.flight_data, current.flight_data, || {
            let mut assignments = projection_assignments! {
                ["app_ui_state", "flight_data_banner"] => snapshot.app_ui_state.flight_data_banner,
                ["next_session_snapshot_refresh_epoch_ms"] => snapshot
                    .next_session_snapshot_refresh_epoch_ms,
            };
            if !settings_changed {
                assignments.push(UiSessionProjectionAssignment {
                    path: vec!["settings_page_state".to_string(), "rows".to_string()],
                    value: serde_json::json!(snapshot.settings_page_state.rows),
                });
            }
            assignments
        }),
        situation: changed_projection_patch(previous.situation, current.situation, || {
            projection_assignments! {
                ["playback_ui_state"] => snapshot.playback_ui_state,
                ["playback_panel_state"] => snapshot.playback_panel_state,
                ["map_follow_ui_state"] => snapshot.map_follow_ui_state,
                ["map_follow_target_viewport"] => snapshot.map_follow_target_viewport,
            }
        }),
        charts: changed_projection_patch(previous.charts, current.charts, || {
            projection_assignments! {
                ["chart_page_state"] => snapshot.chart_page_state,
            }
        }),
        map: changed_projection_patch(previous.map, current.map, || {
            projection_assignments! {
                ["map_layer_state"] => snapshot.map_layer_state,
                ["raster_map"] => snapshot.raster_map,
            }
        }),
        status: changed_projection_patch(previous.status, current.status, || {
            projection_assignments! {
                ["data_status_state"] => snapshot.data_status_state,
                ["data_status_page_state"] => snapshot.data_status_page_state,
                ["next_cycle_product_freshness_check_epoch_ms"] => snapshot
                    .next_cycle_product_freshness_check_epoch_ms,
            }
        }),
        settings: changed_projection_patch(previous.settings, current.settings, || {
            projection_assignments! {
                ["settings_page_state"] => snapshot.settings_page_state,
                ["display_policy"] => snapshot.display_policy,
                ["disclaimer_state"] => snapshot.disclaimer_state,
            }
        }),
        cloud: changed_projection_patch(previous.cloud, current.cloud, || {
            projection_assignments! {
                ["cloud_page_state"] => snapshot.cloud_page_state,
            }
        }),
        packages: changed_projection_patch(previous.packages, current.packages, || {
            projection_assignments! {
                ["offline_package_preferences_json"] => snapshot.offline_package_preferences_json,
            }
        }),
        home: changed_projection_patch(previous.home, current.home, || {
            projection_assignments! {
                ["home_page_state"] => snapshot.home_page_state,
            }
        }),
        debug: changed_projection_patch(previous.debug, current.debug, || {
            projection_assignments! {
                ["debug_state"] => snapshot.debug_state,
            }
        }),
    }
}

fn try_snapshot_for_session(
    session: &mut UiSession,
) -> Result<UiSessionSnapshot, SessionSnapshotProjectionError> {
    session
        .situation
        .refresh_ownship_at(session.coordinator.wall_clock_epoch_ms);
    let resources = forecast_atmosphere_snapshot_resources(session);
    if !resources.is_empty() {
        return Err(SessionSnapshotProjectionError::NeedResources(resources));
    }
    let total_started_at = crate::core_clock_ms();
    session
        .diagnostics
        .snapshot_projection_count
        .fetch_add(1, Ordering::Relaxed);
    let cloud_projection = project_cloud_for_session(session);
    sync_cloud_status_record(session, cloud_projection.status_record.clone());
    if session.weather.runtime().metar_payload.is_some()
        || session.weather.runtime().taf_payload.is_some()
    {
        ensure_weather_station_airport_aliases_loaded(session)?;
    }
    enqueue_ownship_agl_terrain_effect(session);
    let app_ui_started_at = crate::core_clock_ms();
    let weather_projection = project_weather_for_session(session);
    let situation_started_at = crate::core_clock_ms();
    let situation_projection = project_situation_for_session(session);
    let situation_ms = elapsed_ms(situation_started_at);
    let mut app_ui_state =
        project_session_app_ui_state(session, &weather_projection, &situation_projection)?;
    session
        .diagnostics
        .app_ui_projection_count
        .fetch_add(1, Ordering::Relaxed);
    let app_ui_ms = elapsed_ms(app_ui_started_at);
    let debug_started_at = crate::core_clock_ms();
    let debug_state = session.coordinator.debug_state.clone();
    let debug_ms = elapsed_ms(debug_started_at);
    let playback_panel_state = situation_projection.playback_panel_state;
    let playback_ui_state = situation_projection.playback_ui_state;
    let map_follow_ui_state = situation_projection.map_follow_ui_state;
    let map_follow_target_viewport = situation_projection.map_follow_target_viewport;
    let clone_started_at = crate::core_clock_ms();
    let chart_page_state = session.coordinator.chart_page_state.clone();
    let raster_started_at = crate::core_clock_ms();
    let map_projection = session.map.project();
    if map_projection.rebuilt {
        session
            .diagnostics
            .map_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    let map_layer_state = project_map_layer_state_for_debug(
        &map_projection.projection.layer_state,
        &session.coordinator.debug_state,
    );
    let raster_map = map_projection.projection.raster_map;
    let raster_ms = elapsed_ms(raster_started_at);
    let data_status_projection = session.data_status.project_state();
    if data_status_projection.rebuilt {
        session
            .diagnostics
            .data_status_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    let data_status_state = data_status_projection.state;
    let data_status_page_input = data_status_page_input(session, &cloud_projection);
    let data_status_page_projection = session.data_status.project_page(data_status_page_input);
    if data_status_page_projection.rebuilt {
        session
            .diagnostics
            .data_status_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    let data_status_page_state = data_status_page_projection.state;
    let display_policy_available = session
        .coordinator
        .platform_capabilities
        .display_policy
        .is_some();
    let settings_projection = session.settings.project(
        display_policy_available,
        &app_ui_state.flight_data_banner,
        &session.coordinator.debug_state,
    );
    if settings_projection.rebuilt {
        session
            .diagnostics
            .settings_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    let SettingsProjection {
        settings_page_state,
        display_policy,
        disclaimer_state,
        flight_data_banner,
    } = settings_projection.projection;
    app_ui_state.flight_data_banner = flight_data_banner;
    let cloud_page_state = cloud_projection.page_state;
    let package_projection = session
        .packages
        .project()
        .map_err(|error| HadReadError::Fatal(error.message))?;
    if package_projection.rebuilt {
        session
            .diagnostics
            .package_projection_count
            .fetch_add(1, Ordering::Relaxed);
    }
    let offline_package_preferences_json = package_projection.offline_package_preferences_json;
    let home_page_state = project_home_page_state(&session.coordinator.platform_capabilities);
    let clone_ms = elapsed_ms(clone_started_at);
    let total_ms = elapsed_ms(total_started_at);
    crate::core_perf_debug_log("session.snapshot.core", || {
        serde_json::json!({
            "total_ms": total_ms,
            "app_ui_ms": app_ui_ms,
            "debug_ms": debug_ms,
            "situation_ms": situation_ms,
            "clone_ms": clone_ms,
            "raster_ms": raster_ms,
            "projections": ["app_ui", "flight_plan", "situation", "weather", "settings", "map", "packages", "cloud"],
            "status_boxes": data_status_state.boxes.len(),
            "status_page_rows": data_status_page_state.rows.len(),
            "settings_page_rows": settings_page_state.rows.len()
                + settings_page_state.sections.iter().map(|section| section.rows.len()).sum::<usize>(),
            "map_families": raster_map.as_ref().map(|state| state.family_options.len()).unwrap_or(0),
        })
    });
    let next_nav_db_maintenance_epoch_ms = next_nav_db_maintenance_epoch_ms(session);
    let snapshot = UiSessionSnapshot {
        ui_contract_version: app_ui_contracts::UI_WIRE_CONTRACT_VERSION,
        session_revision: session.coordinator.session_revision,
        flight_plan_route_revision: session.flight_plan.route_revision(),
        nav_data_epoch: session.nav_data.epoch(),
        active_nav_db: session.nav_data.active_identity(),
        next_nav_db_maintenance_epoch_ms,
        next_session_snapshot_refresh_epoch_ms: session
            .situation
            .ownship()
            .controls
            .next_refresh_epoch_ms
            .map(|deadline| {
                deadline.min(crate::next_time_display_refresh_epoch_ms(
                    session.coordinator.wall_clock_epoch_ms,
                ))
            })
            .unwrap_or_else(|| {
                crate::next_time_display_refresh_epoch_ms(session.coordinator.wall_clock_epoch_ms)
            }),
        app_state: app_state_for_session(session),
        app_ui_state,
        playback_ui_state,
        playback_panel_state,
        map_follow_ui_state,
        map_follow_target_viewport,
        chart_page_state,
        map_layer_state,
        data_status_state,
        data_status_page_state,
        settings_page_state,
        cloud_page_state,
        offline_package_preferences_json,
        home_page_state,
        display_policy,
        disclaimer_state,
        debug_state,
        raster_map,
        next_cycle_product_freshness_check_epoch_ms: session
            .coordinator
            .cycle_product_freshness
            .next_check_epoch_ms,
    };
    refresh_session_projection_versions(session, &snapshot, next_nav_db_maintenance_epoch_ms);
    Ok(snapshot)
}

fn app_state_for_session(session: &UiSession) -> AppState {
    AppState {
        active_plan: session.flight_plan.active_plan().cloned(),
        ownship: session.situation.ownship().clone(),
        content_policy: session.coordinator.content_policy,
        last_content_report: session.coordinator.last_content_report.clone(),
    }
}

fn register_default_situation_sources(app_state: AppState) -> AppResult<AppState> {
    let app_state = state::reduce(
        &app_state,
        AppEvent::RegisterOwnshipSource(crate::OwnshipSourceRegistration {
            source_id: crate::OwnshipSourceId(DIRECT_SITUATION_SOURCE_ID.to_string()),
            source_kind: crate::OwnshipSourceKind::FlightPlanSimulator,
            display_name: "Plan Preview".to_string(),
            selectable: true,
            auto_eligible: false,
            stale_after_ms: None,
            power_state: None,
        }),
    )?;
    let app_state = state::reduce(
        &app_state,
        AppEvent::RegisterOwnshipSource(crate::OwnshipSourceRegistration {
            source_id: crate::OwnshipSourceId(PLAYBACK_SOURCE_ID.to_string()),
            source_kind: crate::OwnshipSourceKind::AdsbTrackPlayback,
            display_name: "Replay".to_string(),
            selectable: true,
            auto_eligible: false,
            stale_after_ms: None,
            power_state: None,
        }),
    )?;
    let app_state = state::reduce(
        &app_state,
        AppEvent::RegisterOwnshipSource(crate::OwnshipSourceRegistration {
            source_id: crate::OwnshipSourceId(crate::adsb::INTERNET_ADSB_SOURCE_ID.to_string()),
            source_kind: crate::OwnshipSourceKind::LiveNetworkTrack,
            display_name: "Internet ADS-B".to_string(),
            selectable: true,
            auto_eligible: false,
            stale_after_ms: Some(crate::adsb::OWNSHIP_STALE_AFTER_MS),
            power_state: None,
        }),
    )?;
    state::reduce(
        &app_state,
        AppEvent::UpdateOwnshipSourceStatus(crate::OwnshipSourceStatusUpdate {
            source_id: crate::OwnshipSourceId(crate::adsb::INTERNET_ADSB_SOURCE_ID.to_string()),
            connection_state: crate::SourceConnectionState::Unavailable,
            enabled: true,
            status_label: "Enter an aircraft registration".to_string(),
        }),
    )
}

fn adsb_ownship_selected(session: &UiSession) -> bool {
    matches!(
        &session.situation.ownship().policy.selection,
        crate::OwnshipSelectionPolicy::Manual { source_id }
            if source_id.0 == crate::adsb::INTERNET_ADSB_SOURCE_ID
    )
}

fn set_adsb_ownship_status(
    session: &mut UiSession,
    connection_state: crate::SourceConnectionState,
    status_label: String,
) -> AppResult<()> {
    session
        .situation
        .update_source_status(crate::OwnshipSourceStatusUpdate {
            source_id: crate::OwnshipSourceId(crate::adsb::INTERNET_ADSB_SOURCE_ID.to_string()),
            connection_state,
            enabled: true,
            status_label,
        });
    Ok(())
}

fn apply_adsb_ownship_update(
    session: &mut UiSession,
    update: crate::adsb::AdsbOwnshipUpdate,
) -> AppResult<()> {
    set_adsb_ownship_status(session, update.connection_state, update.status_label)?;
    if let Some(sample) = update.sample {
        apply_ownship_sample(session, sample)?;
    }
    sync_adsb_ownship_status_record(session);
    Ok(())
}

fn prepare_adsb_ownship_effect(session: &mut UiSession) {
    if !session.coordinator.debug_state.internet_adsb || !adsb_ownship_selected(session) {
        return;
    }
    let wall_clock_epoch_ms = session.coordinator.wall_clock_epoch_ms;
    if let Some(resource) = session
        .runtime
        .adsb
        .prepare_ownship_request(wall_clock_epoch_ms)
    {
        enqueue_session_resource_effect(
            session,
            resource,
            [
                UiInvalidation::SessionSnapshot,
                UiInvalidation::MapOverlay,
                UiInvalidation::TerrainOverlay,
                UiInvalidation::FlightPlanRoute,
            ],
        );
    }
}

fn register_bad_autopilot_source(app_state: AppState) -> AppResult<AppState> {
    let app_state = state::reduce(
        &app_state,
        AppEvent::RegisterOwnshipSource(crate::OwnshipSourceRegistration {
            source_id: crate::OwnshipSourceId(BAD_AUTOPILOT_SOURCE_ID.to_string()),
            source_kind: crate::OwnshipSourceKind::BadAutopilot,
            display_name: "Bad AP".to_string(),
            selectable: true,
            auto_eligible: true,
            stale_after_ms: None,
            power_state: None,
        }),
    )?;
    state::reduce(
        &app_state,
        AppEvent::UpdateOwnshipSourceStatus(crate::OwnshipSourceStatusUpdate {
            source_id: crate::OwnshipSourceId(BAD_AUTOPILOT_SOURCE_ID.to_string()),
            connection_state: crate::SourceConnectionState::Connected,
            enabled: true,
            status_label: "Ready".to_string(),
        }),
    )
}

fn project_home_page_state(capabilities: &PlatformCapabilities) -> UiHomePageState {
    let offline_packages_enabled = capabilities.offline_packages.is_some();
    let button = |destination: UiHomeDestination, label: &str| UiHomePageButton {
        destination,
        label: label.to_string(),
        enabled: true,
        disabled_reason: None,
    };
    let mut buttons = vec![
        button(UiHomeDestination::Chart, "CHART"),
        button(UiHomeDestination::Plate, "PLATE"),
        button(UiHomeDestination::FlightPlan, "FLIGHT\nPLAN"),
        button(UiHomeDestination::AltitudePlanner, "ALTITUDE\nPLANNER"),
        button(UiHomeDestination::DataStatus, "STATUS"),
        button(UiHomeDestination::Settings, "SETTINGS"),
    ];
    if capabilities.cloud.is_some() {
        buttons.push(button(UiHomeDestination::Cloud, "CLOUD"));
    }
    buttons.extend([
        UiHomePageButton {
            destination: UiHomeDestination::OfflinePackages,
            label: "OFFLINE\nPACKAGES".to_string(),
            enabled: offline_packages_enabled,
            disabled_reason: (!offline_packages_enabled).then(|| {
                "This client fetches data as needed and does not support managing Offline Packages."
                    .to_string()
            }),
        },
        button(UiHomeDestination::About, "ABOUT"),
    ]);
    UiHomePageState { buttons }
}

fn load_session_persistence_from_storage(session: &mut UiSession) -> AppResult<()> {
    let Some(storage) = session.coordinator.persistence_storage.as_ref() else {
        return Ok(());
    };
    let Some(bytes) = storage.read_settings()? else {
        return Ok(());
    };
    let document = decode_session_persistence(&bytes);
    session.settings.restore_preferences(document.preferences);
    session.cloud = CloudController::new(document.cloud);
    restore_package_preferences_from_cloud(session)?;
    if let Some(plan) = session.cloud.cached_flight_plan() {
        replace_session_flight_plan(session, plan)?;
    }
    Ok(())
}

fn write_session_persistence_to_storage(session: &UiSession) -> AppResult<()> {
    let Some(storage) = session.coordinator.persistence_storage.as_ref() else {
        return Ok(());
    };
    let bytes = encode_session_persistence(session)?;
    storage.write_settings(&bytes)
}

fn decode_session_persistence(bytes: &[u8]) -> SettingsPersistenceDocument {
    if bytes.is_empty() {
        return default_session_persistence();
    }
    serde_json::from_slice::<SettingsPersistenceDocument>(bytes)
        .ok()
        .filter(|document| document.version == SETTINGS_PERSISTENCE_VERSION)
        .unwrap_or_else(default_session_persistence)
}

fn default_session_persistence() -> SettingsPersistenceDocument {
    SettingsPersistenceDocument {
        version: SETTINGS_PERSISTENCE_VERSION,
        preferences: SettingsPreferences::default(),
        cloud: CloudPersistentState::default(),
    }
}

fn encode_session_persistence(session: &UiSession) -> AppResult<Vec<u8>> {
    serde_json::to_vec(&SettingsPersistenceDocument {
        version: SETTINGS_PERSISTENCE_VERSION,
        preferences: session.settings.persistent_preferences(),
        cloud: session.cloud.persistent().clone(),
    })
    .map_err(|err| AppError {
        kind: AppErrorKind::Internal,
        message: err.to_string(),
    })
}

fn default_debug_state() -> UiDebugState {
    UiDebugState {
        tile_labels: false,
        nexrad_tile_labels: false,
        fast_tiles: false,
        offline_simulated_clock_buttons: false,
        sequencing_finish_lines: false,
        plate_flight_plan: false,
        bad_autopilot: false,
        internet_adsb: false,
        gps_capture: false,
        debug_log_to_developer_server: false,
    }
}

fn project_map_layer_state_for_debug(
    map_layer_state: &UiMapLayerState,
    debug_state: &UiDebugState,
) -> UiMapLayerState {
    let mut projected = map_layer_state.clone();
    if !debug_state.internet_adsb {
        projected
            .options
            .retain(|option| option.layer_id != MapLayerId::Traffic);
        projected.traffic.visible = false;
        projected.traffic.enabled = false;
        projected.traffic.disabled_reason =
            Some("Internet ADS-B is experimental; enable it in DBG to use it.".to_string());
    }
    projected
}

fn disable_internet_adsb(session: &mut UiSession) -> AppResult<()> {
    session.map.set_layer_visibility(MapLayerId::Traffic, false);
    clear_data_status_record(session, ADSB_TRAFFIC_STATUS_ID);
    clear_data_status_record(session, ADSB_OWNSHIP_STATUS_ID);
    session
        .runtime
        .pending_resource_effects
        .retain(|effect| !crate::adsb::AdsbSessionState::handles_resource(&effect.resource.id));
    session.runtime.adsb = crate::adsb::AdsbSessionState::default();
    if adsb_ownship_selected(session) {
        session
            .situation
            .select_source(crate::OwnshipSelectionCommand::Auto);
    }
    Ok(())
}

