    fn session_update_from_outcome(outcome: HadOperationOutcome) -> UiSessionUpdate {
        let HadOperationOutcome::Complete { result, .. } = outcome else {
            panic!("session operation unexpectedly needed resources: {outcome:?}");
        };
        serde_json::from_value(result).expect("session update")
    }

    fn projection_assignment_paths(patch: &UiSessionProjectionPatch) -> BTreeSet<String> {
        patch
            .assignments
            .iter()
            .map(|assignment| assignment.path.join("/"))
            .collect()
    }

    fn apply_projection_assignment_for_test(
        snapshot: &mut serde_json::Value,
        assignment: &UiSessionProjectionAssignment,
    ) {
        let (field, parent_path) = assignment
            .path
            .split_last()
            .expect("nonempty assignment path");
        let mut parent = snapshot;
        for segment in parent_path {
            parent = match parent {
                serde_json::Value::Object(object) => object.get_mut(segment).unwrap_or_else(|| {
                    panic!("missing assignment parent {}", assignment.path.join("/"))
                }),
                serde_json::Value::Array(array) => array
                    .get_mut(segment.parse::<usize>().expect("array path index"))
                    .unwrap_or_else(|| {
                        panic!("missing assignment parent {}", assignment.path.join("/"))
                    }),
                _ => panic!(
                    "non-container assignment parent {}",
                    assignment.path.join("/")
                ),
            };
        }
        match parent {
            serde_json::Value::Object(object) => {
                let target = object.get_mut(field).unwrap_or_else(|| {
                    panic!("missing assignment target {}", assignment.path.join("/"))
                });
                *target = assignment.value.clone();
            }
            serde_json::Value::Array(array) => {
                let target = array
                    .get_mut(field.parse::<usize>().expect("array target index"))
                    .unwrap_or_else(|| {
                        panic!("missing assignment target {}", assignment.path.join("/"))
                    });
                *target = assignment.value.clone();
            }
            _ => panic!(
                "non-container assignment target {}",
                assignment.path.join("/")
            ),
        }
    }

    fn first_json_difference(
        left: &serde_json::Value,
        right: &serde_json::Value,
        path: &str,
    ) -> Option<String> {
        match (left, right) {
            (serde_json::Value::Object(left), serde_json::Value::Object(right)) => {
                for key in left.keys().chain(right.keys()).collect::<BTreeSet<_>>() {
                    let next_path = format!("{path}/{key}");
                    let (Some(left), Some(right)) = (left.get(key), right.get(key)) else {
                        return Some(next_path);
                    };
                    if let Some(difference) = first_json_difference(left, right, &next_path) {
                        return Some(difference);
                    }
                }
                None
            }
            (serde_json::Value::Array(left), serde_json::Value::Array(right)) => {
                if left.len() != right.len() {
                    return Some(format!("{path}/length"));
                }
                for (index, (left, right)) in left.iter().zip(right).enumerate() {
                    if let Some(difference) =
                        first_json_difference(left, right, &format!("{path}/{index}"))
                    {
                        return Some(difference);
                    }
                }
                None
            }
            _ if left == right => None,
            _ => Some(path.to_string()),
        }
    }

    #[test]
    fn creation_snapshot_accepts_every_assignment_in_the_first_revision() {
        let init = create_ui_session(FlightPlan::default(), &[], None, None)
            .expect("create bootstrap session");
        let mut accumulated =
            serde_json::to_value(&init.snapshot).expect("serialize creation snapshot");
        let update = session_update_from_outcome(
            super::set_resource_policy_in_session(init.handle, CoreResourcePolicy::PublicUnpacked)
                .expect("first revision"),
        );
        let accumulated_object = accumulated
            .as_object_mut()
            .expect("creation snapshot object");
        *accumulated_object
            .get_mut("ui_contract_version")
            .expect("creation contract version") = serde_json::json!(update.ui_contract_version);
        *accumulated_object
            .get_mut("session_revision")
            .expect("creation session revision") = serde_json::json!(update.session_revision);

        for (_, patch) in update.projection_patches() {
            let Some(patch) = patch else { continue };
            for assignment in &patch.assignments {
                apply_projection_assignment_for_test(&mut accumulated, assignment);
            }
        }

        let slot = session_slot(init.handle).expect("first revision session slot");
        let mut guard = slot.lock_running().expect("first revision session lock");
        let expected = serde_json::to_value(
            try_snapshot_for_session(&mut guard).expect("first revision projection"),
        )
        .expect("serialize first revision projection");
        assert_eq!(
            first_json_difference(&accumulated, &expected, ""),
            None,
            "accumulated first revision differs from core snapshot",
        );
    }

    #[test]
    fn session_update_groups_partition_production_snapshot_fields() {
        let mut session = isolated_test_session(None);
        let snapshot = try_snapshot_for_session(&mut session).expect("initial snapshot");
        let previous = session.projection_versions.versions();
        let current = SessionProjectionVersions {
            envelope: previous.envelope.saturating_add(1),
            nav_data: previous.nav_data.saturating_add(1),
            application_shell: previous.application_shell.saturating_add(1),
            flight_plan: previous.flight_plan.saturating_add(1),
            ownship: previous.ownship.saturating_add(1),
            flight_data: previous.flight_data.saturating_add(1),
            situation: previous.situation.saturating_add(1),
            charts: previous.charts.saturating_add(1),
            map: previous.map.saturating_add(1),
            status: previous.status.saturating_add(1),
            settings: previous.settings.saturating_add(1),
            cloud: previous.cloud.saturating_add(1),
            packages: previous.packages.saturating_add(1),
            home: previous.home.saturating_add(1),
            debug: previous.debug.saturating_add(1),
        };
        let update = assemble_session_update(&snapshot, previous, current);
        let groups = [
            ("nav_data", update.nav_data.as_ref().expect("nav data")),
            (
                "application_shell",
                update
                    .application_shell
                    .as_ref()
                    .expect("application shell"),
            ),
            (
                "flight_plan",
                update.flight_plan.as_ref().expect("flight plan"),
            ),
            ("ownship", update.ownship.as_ref().expect("ownship")),
            (
                "flight_data",
                update.flight_data.as_ref().expect("flight data"),
            ),
            ("situation", update.situation.as_ref().expect("situation")),
            ("charts", update.charts.as_ref().expect("charts")),
            ("map", update.map.as_ref().expect("map")),
            ("status", update.status.as_ref().expect("status")),
            ("settings", update.settings.as_ref().expect("settings")),
            ("cloud", update.cloud.as_ref().expect("cloud")),
            ("packages", update.packages.as_ref().expect("packages")),
            ("home", update.home.as_ref().expect("home")),
            ("debug", update.debug.as_ref().expect("debug")),
        ];
        let expected = BTreeMap::from([
            (
                "nav_data",
                BTreeSet::from([
                    "active_nav_db",
                    "nav_data_epoch",
                    "next_nav_db_maintenance_epoch_ms",
                ]),
            ),
            (
                "application_shell",
                BTreeSet::from([
                    "app_ui_state/content_policy",
                    "app_ui_state/last_content_report",
                ]),
            ),
            (
                "flight_plan",
                BTreeSet::from([
                    "app_ui_state/active_plan",
                    "app_ui_state/aircraft_plan_view_path",
                    "flight_plan_route_revision",
                ]),
            ),
            ("ownship", BTreeSet::from(["app_ui_state/ownship"])),
            (
                "flight_data",
                BTreeSet::from([
                    "app_ui_state/flight_data_banner",
                    "next_session_snapshot_refresh_epoch_ms",
                ]),
            ),
            (
                "situation",
                BTreeSet::from([
                    "map_follow_target_viewport",
                    "map_follow_ui_state",
                    "playback_panel_state",
                    "playback_ui_state",
                ]),
            ),
            ("charts", BTreeSet::from(["chart_page_state"])),
            ("map", BTreeSet::from(["map_layer_state", "raster_map"])),
            (
                "status",
                BTreeSet::from([
                    "data_status_page_state",
                    "data_status_state",
                    "next_cycle_product_freshness_check_epoch_ms",
                ]),
            ),
            (
                "settings",
                BTreeSet::from(["disclaimer_state", "display_policy", "settings_page_state"]),
            ),
            ("cloud", BTreeSet::from(["cloud_page_state"])),
            (
                "packages",
                BTreeSet::from(["offline_package_preferences_json"]),
            ),
            ("home", BTreeSet::from(["home_page_state"])),
            ("debug", BTreeSet::from(["debug_state"])),
        ]);
        let mut all_paths = BTreeSet::new();
        for (group, patch) in groups {
            let actual = projection_assignment_paths(patch);
            let expected_paths = expected[group]
                .iter()
                .map(|path| path.to_string())
                .collect::<BTreeSet<_>>();
            assert_eq!(actual, expected_paths, "{group} field membership changed");
            for path in actual {
                assert!(
                    all_paths.insert(path.clone()),
                    "snapshot path {path} belongs to more than one update group"
                );
            }
        }
        for left in &all_paths {
            for right in &all_paths {
                assert!(
                    left == right
                        || (!left.starts_with(&format!("{right}/"))
                            && !right.starts_with(&format!("{left}/"))),
                    "session assignment paths overlap: {left} and {right}",
                );
            }
        }
        let mut snapshot_fields = serde_json::to_value(snapshot)
            .expect("serialize snapshot")
            .as_object()
            .expect("snapshot object")
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        snapshot_fields.remove("ui_contract_version");
        snapshot_fields.remove("session_revision");
        snapshot_fields.remove("app_state");
        assert_eq!(
            all_paths
                .into_iter()
                .map(|path| path.split('/').next().expect("nonempty path").to_string())
                .collect::<BTreeSet<_>>(),
            snapshot_fields,
            "new production snapshot fields must be assigned to exactly one update group"
        );
    }

