    #[test]
    fn internet_adsb_is_hidden_until_debug_enabled_and_disable_cleans_up() {
        let init = create_ui_session_at_epoch_ms(FlightPlan::default(), &[], None, None, 10_000)
            .expect("create session");
        assert!(init
            .snapshot
            .app_ui_state
            .ownship
            .controls
            .sources
            .iter()
            .all(|source| source.source_id.0 != crate::adsb::INTERNET_ADSB_SOURCE_ID));
        assert!(init
            .snapshot
            .map_layer_state
            .options
            .iter()
            .all(|option| option.layer_id != MapLayerId::Traffic));
        let disabled_error = perform_ownship_text_action_in_session(
            init.handle,
            crate::adsb::FOLLOW_ADSB_TARGET_ACTION_ID,
            "N9124Y",
            10_000,
        )
        .expect_err("disabled ADS-B action must be rejected");
        assert_eq!(disabled_error.kind, AppErrorKind::UnsupportedOperation);

        let enabled = set_debug_flag_in_session(init.handle, DebugFlagId::InternetAdsb, true)
            .expect("enable internet ADS-B");
        assert!(enabled
            .app_ui_state
            .ownship
            .controls
            .sources
            .iter()
            .any(|source| source.source_id.0 == crate::adsb::INTERNET_ADSB_SOURCE_ID));
        assert!(enabled
            .map_layer_state
            .options
            .iter()
            .any(|option| option.layer_id == MapLayerId::Traffic));
        set_map_layer_visibility_in_session(init.handle, MapLayerId::Traffic, true)
            .expect("show traffic");
        perform_ownship_text_action_in_session(
            init.handle,
            crate::adsb::FOLLOW_ADSB_TARGET_ACTION_ID,
            "N9124Y",
            10_000,
        )
        .expect("follow target");
        assert!(!drain_session_resource_effects(init.handle)
            .expect("queued ADS-B effect")
            .is_empty());

        let disabled = set_debug_flag_in_session(init.handle, DebugFlagId::InternetAdsb, false)
            .expect("disable internet ADS-B");
        assert!(disabled
            .app_ui_state
            .ownship
            .controls
            .sources
            .iter()
            .all(|source| source.source_id.0 != crate::adsb::INTERNET_ADSB_SOURCE_ID));
        assert!(disabled
            .map_layer_state
            .options
            .iter()
            .all(|option| option.layer_id != MapLayerId::Traffic));
        assert!(!disabled.map_layer_state.traffic.visible);
        assert!(disabled
            .data_status_state
            .boxes
            .iter()
            .all(|status| status.id != ADSB_OWNSHIP_STATUS_ID));
        assert!(drain_session_resource_effects(init.handle)
            .expect("effects after disable")
            .is_empty());

        destroy_session(init.handle);
    }

    #[test]
    fn traffic_layer_uses_session_resource_effect_and_projects_core_normalized_aircraft() {
        let handle = NEXT_HANDLE.fetch_add(1, Ordering::Relaxed);
        let mut session = isolated_test_session(None);
        session.coordinator.debug_state.internet_adsb = true;
        session.map.set_layer_visibility(MapLayerId::Vectors, false);
        session.map.set_layer_visibility(MapLayerId::Metars, false);
        session.map.set_layer_visibility(MapLayerId::Traffic, true);
        session
            .map
            .set_layer_visibility(MapLayerId::OfflineRegions, false);
        session.coordinator.wall_clock_epoch_ms = 1_785_900_880_000;
        let generation = NEXT_SESSION_GENERATION.fetch_add(1, Ordering::Relaxed);
        lock_sessions().insert(
            handle,
            Arc::new(SessionSlot::new(handle, generation, session)),
        );
        let viewport = MapViewport {
            center: LatLon {
                lat: 47.45,
                lon: -122.31,
            },
            zoom: 9.0,
            rotation_deg: 0.0,
            pitch_deg: 0.0,
        };

        let first = get_map_overlay_in_session_at_epoch_ms(
            handle,
            viewport,
            800.0,
            600.0,
            1_785_900_880_000,
        )
        .expect("first overlay");
        let HadOperationOutcome::Complete { result, .. } = first else {
            panic!("traffic overlay unexpectedly requested paging: {first:?}");
        };
        let first_overlay: MapOverlayQueryResult =
            serde_json::from_value(result).expect("first overlay result");
        assert!(first_overlay.visible_traffic.is_empty());
        assert_eq!(first_overlay.traffic_next_refresh_epoch_ms, None);

        let effects = drain_session_resource_effects(handle).expect("traffic effect");
        assert_eq!(effects.len(), 1);
        assert_eq!(
            effects[0].completion_invalidations,
            vec![UiInvalidation::MapOverlay, UiInvalidation::SessionSnapshot]
        );
        assert!(effects[0]
            .resource
            .id
            .starts_with("adsb/airplanes_live/traffic/"));
        assert_eq!(
            effects[0].resource.max_response_bytes,
            Some(4 * 1024 * 1024)
        );
        let CoreResourceSource::PublicUrl { url } = &effects[0].resource.source else {
            panic!("traffic source was not a public URL");
        };
        assert!(url.starts_with("https://api.airplanes.live/v2/point/47.45000/-122.31000/"));

        ingest_resource_in_session_at_epoch_ms(
            handle,
            &effects[0].resource.id,
            br#"{
              "now": 1785900882001,
              "ac": [{
                "hex": "a757ae", "flight": "AAL727  ", "r": "N572UW",
                "alt_baro": 2250, "alt_geom": 2300, "track": 0.75,
                "lat": 47.451, "lon": -122.309, "seen_pos": 0.25
              }]
            }"#,
            1_785_900_882_100,
        )
        .expect("ingest traffic");

        let second = get_map_overlay_in_session_at_epoch_ms(
            handle,
            viewport,
            800.0,
            600.0,
            1_785_900_882_100,
        )
        .expect("second overlay");
        let HadOperationOutcome::Complete { result, .. } = second else {
            panic!("traffic overlay unexpectedly requested paging: {second:?}");
        };
        let second_overlay: MapOverlayQueryResult =
            serde_json::from_value(result).expect("second overlay result");
        assert_eq!(second_overlay.visible_traffic.len(), 1);
        assert_eq!(second_overlay.visible_traffic[0].label, "AAL727");
        assert_eq!(
            second_overlay.traffic_next_refresh_epoch_ms,
            Some(1_785_900_942_100)
        );

        destroy_session(handle);
    }

    #[test]
