    #[test]
    fn model_transaction_does_not_copy_or_replace_runtime_generations() {
        let mut session = isolated_test_session(None);
        session
            .map
            .runtime_mut()
            .terrain_source_tile_cache
            .insert("seed".to_string(), vec![0x5a; 2 * 1024 * 1024]);
        let runtime_address = std::ptr::addr_of!(session.runtime);
        let terrain_bytes_address =
            session.map.runtime().terrain_source_tile_cache["seed"].as_ptr();
        let publication_address = std::ptr::from_ref(session.packages.resolver());
        let live_feeds_address = Arc::as_ptr(session.weather.live_feeds_arc());

        let outcome = run_session_model_transaction(&mut session, |session| {
            session
                .packages
                .insert_installed_package_id("test-package".to_string());
            Ok(vec![UiInvalidation::SessionSnapshot])
        })
        .expect("model transaction");

        assert!(matches!(outcome, HadOperationOutcome::Complete { .. }));
        assert_eq!(std::ptr::addr_of!(session.runtime), runtime_address);
        assert_eq!(
            session.map.runtime().terrain_source_tile_cache["seed"].as_ptr(),
            terrain_bytes_address
        );
        assert_eq!(
            std::ptr::from_ref(session.packages.resolver()),
            publication_address
        );
        assert_eq!(
            Arc::as_ptr(session.weather.live_feeds_arc()),
            live_feeds_address
        );
    }

    #[test]
    fn model_transaction_rolls_back_model_without_disturbing_runtime() {
        let mut session = isolated_test_session(None);
        session
            .map
            .runtime_mut()
            .terrain_source_tile_cache
            .insert("seed".to_string(), vec![0x33; 1024]);
        let terrain_bytes_address =
            session.map.runtime().terrain_source_tile_cache["seed"].as_ptr();

        let outcome = run_session_model_transaction(&mut session, |session| {
            session
                .packages
                .insert_installed_package_id("must-roll-back".to_string());
            session
                .weather
                .set_current_refresh(LiveFeedCurrentRefreshState::Requested);
            session.situation.plan_preview_mut().pointer = Some(PlanPreviewPointer {
                row_uid: "must-roll-back".to_string(),
                offset_nm: 4.0,
            });
            let mut plan = FlightPlan::default();
            plan.name = "must-roll-back".to_string();
            session
                .flight_plan
                .replace_plan(plan)
                .expect("install plan");
            Err(HadReadError::NeedPages(vec![42]).into())
        })
        .expect("paging outcome");

        assert!(matches!(outcome, HadOperationOutcome::NeedResources { .. }));
        assert!(!session
            .packages
            .installed_package_ids()
            .contains("must-roll-back"));
        assert_eq!(
            session.weather.current_refresh(),
            LiveFeedCurrentRefreshState::Idle
        );
        assert_eq!(session.weather.revision(), 0);
        assert_eq!(session.situation.revision(), 0);
        assert!(session.situation.plan_preview().pointer.is_none());
        assert_eq!(session.flight_plan.revision(), 0);
        assert!(session.flight_plan.active_plan().is_none());
        assert_eq!(
            session.map.runtime().terrain_source_tile_cache["seed"].as_ptr(),
            terrain_bytes_address
        );
    }

    struct RejectingSettingsStorage;

    impl SettingsStorage for RejectingSettingsStorage {
        fn read_settings(&self) -> AppResult<Option<Vec<u8>>> {
            Ok(None)
        }

        fn write_settings(&self, _bytes: &[u8]) -> AppResult<()> {
            Err(AppError {
                kind: AppErrorKind::Internal,
                message: "injected settings write failure".to_string(),
            })
        }
    }

    struct RejectingSettingsReadStorage;

    impl SettingsStorage for RejectingSettingsReadStorage {
        fn read_settings(&self) -> AppResult<Option<Vec<u8>>> {
            Err(AppError {
                kind: AppErrorKind::Internal,
                message: "injected settings read failure".to_string(),
            })
        }

        fn write_settings(&self, _bytes: &[u8]) -> AppResult<()> {
            Ok(())
        }
    }

    #[test]
    fn model_transaction_rolls_back_model_and_queued_effects_when_persistence_fails() {
        let mut session = isolated_test_session(None);
        session.coordinator.persistence_storage = Some(Arc::new(RejectingSettingsStorage));
        let prior_revision = session.coordinator.session_revision;
        let prior_projection_versions = observe_projection_versions(&mut session);

        let error = run_session_model_transaction(&mut session, |session| {
            session
                .packages
                .insert_installed_package_id("must-roll-back".to_string());
            enqueue_session_resource_effect(
                session,
                CoreResourceRequest::public_url("test", "/test", false),
                [UiInvalidation::MapOverlay],
            );
            Ok(vec![UiInvalidation::SessionSnapshot])
        })
        .expect_err("persistence failure must abort transaction");

        assert!(error.message.contains("injected settings write failure"));
        assert_eq!(session.coordinator.session_revision, prior_revision);
        assert_eq!(
            session.projection_versions.versions(),
            prior_projection_versions
        );
        assert!(!session
            .packages
            .installed_package_ids()
            .contains("must-roll-back"));
        assert!(session.runtime.pending_resource_effects.is_empty());
        assert_eq!(
            session
                .diagnostics
                .transaction_rollback_count
                .load(Ordering::Relaxed),
            1
        );
    }

    #[test]
    fn closing_session_rejects_new_work_and_waits_for_accepted_work() {
        let handle = u32::MAX;
        let slot = Arc::new(SessionSlot::new(handle, 99, isolated_test_session(None)));
        let guard = slot.lock_running().expect("accepted operation");

        assert!(slot.begin_close());
        assert_eq!(slot.phase(), UiSessionPhase::Closing);
        assert!(slot.lock_running().is_err());

        let closing_slot = Arc::clone(&slot);
        let (closed_tx, closed_rx) = std::sync::mpsc::channel();
        let closer = std::thread::spawn(move || {
            closing_slot.finish_close();
            closed_tx.send(()).expect("report closed");
        });
        assert!(closed_rx
            .recv_timeout(std::time::Duration::from_millis(50))
            .is_err());

        drop(guard);
        closed_rx
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("close completes after accepted operation");
        closer.join().expect("closer thread");
        assert_eq!(slot.phase(), UiSessionPhase::Closed);
        assert!(slot.lock_running().is_err());
    }

    #[test]
    fn holding_one_session_does_not_block_another_session() {
        let first = create_ui_session(FlightPlan::default(), &[], None, None)
            .expect("create first session");
        let second = create_ui_session(FlightPlan::default(), &[], None, None)
            .expect("create second session");
        let first_slot = session_slot(first.handle).expect("first slot");
        let first_guard = first_slot.lock_running().expect("hold first session");
        let (result_tx, result_rx) = std::sync::mpsc::channel();

        let second_handle = second.handle;
        let query = std::thread::spawn(move || {
            result_tx
                .send(super::get_session_snapshot(second_handle))
                .expect("send second-session result");
        });
        let result = result_rx
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("second session must not wait for first session");
        assert!(result.is_ok());

        drop(first_guard);
        query.join().expect("second-session query");
        destroy_session(first.handle);
        destroy_session(second.handle);
    }

