    macro_rules! snapshot_wrapper {
        ($name:ident(handle: u32 $(, $arg:ident: $arg_type:ty)* $(,)?)) => {
            #[allow(dead_code)]
            fn $name(handle: u32 $(, $arg: $arg_type)*) -> AppResult<UiSessionSnapshot> {
                super::$name(handle $(, $arg)*)?;
                get_session_snapshot(handle)
            }
        };
    }

