    #[test]
    fn debug_settings_rows_cover_every_flag_and_use_the_shared_mutation_path() {
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let initial = get_session_snapshot(init.handle).expect("initial snapshot");
        let debug = &initial.settings_page_state.sections[0];
        let action_ids = debug
            .rows
            .iter()
            .map(|row| row.action_id.as_str())
            .collect::<BTreeSet<_>>();
        let expected_action_ids = [
            "debug_flag.tile_labels",
            "debug_flag.nexrad_tile_labels",
            "debug_flag.fast_tiles",
            "debug_flag.offline_simulated_clock_buttons",
            "debug_flag.sequencing_finish_lines",
            "debug_flag.plate_flight_plan",
            "debug_flag.bad_autopilot",
            "debug_flag.internet_adsb",
            "debug_flag.gps_capture",
            "debug_flag.debug_log_to_developer_server",
        ];
        assert_eq!(action_ids.len(), expected_action_ids.len());
        for action_id in expected_action_ids {
            assert!(action_ids.contains(action_id));
        }

        let enabled = perform_settings_action_in_session(
            init.handle,
            UiSettingsAction {
                action_id: "debug_flag.plate_flight_plan".to_string(),
                value_id: "on".to_string(),
            },
        )
        .expect("enable plate flight-plan diagnostics");
        assert!(enabled.debug_state.plate_flight_plan);
        let row = enabled.settings_page_state.sections[0]
            .rows
            .iter()
            .find(|row| row.id == "debug_plate_flight_plan")
            .expect("plate flight-plan settings row");
        assert_eq!(row.value_id, "on");

        let disabled = set_debug_flag_in_session(init.handle, DebugFlagId::PlateFlightPlan, false)
            .expect("disable through direct debug command");
        assert!(!disabled.debug_state.plate_flight_plan);
        let row = disabled.settings_page_state.sections[0]
            .rows
            .iter()
            .find(|row| row.id == "debug_plate_flight_plan")
            .expect("plate flight-plan settings row");
        assert_eq!(row.value_id, "off");
    }

    #[test]
    fn display_dim_setting_uses_core_owned_storage() {
        let storage: SettingsStorageHandle = Arc::new(MemorySettingsStorage::default());
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let snapshot = configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities {
                display_policy: Some(PlatformDisplayPolicyCapability::default()),
                ..PlatformCapabilities::default()
            },
            Some(storage.clone()),
        )
        .expect("configure platform capabilities");

        assert_eq!(snapshot.settings_page_state.rows.len(), 2);
        assert_eq!(snapshot.settings_page_state.rows[1].value_id, "2m");
        assert_eq!(
            snapshot
                .display_policy
                .as_ref()
                .and_then(|policy| policy.dim_after_ms),
            Some(120_000)
        );

        let snapshot = perform_settings_action_in_session(
            init.handle,
            UiSettingsAction {
                action_id: "display_dim_timeout".to_string(),
                value_id: "30s".to_string(),
            },
        )
        .expect("perform settings action");
        assert_eq!(snapshot.settings_page_state.rows[1].value_id, "30s");
        assert_eq!(
            snapshot
                .display_policy
                .as_ref()
                .and_then(|policy| policy.dim_after_ms),
            Some(30_000)
        );

        let persisted = storage
            .read_settings()
            .expect("read settings")
            .expect("persisted bytes");
        let persisted_json: serde_json::Value =
            serde_json::from_slice(&persisted).expect("persisted json");
        assert_eq!(persisted_json["version"], 1);
        assert_eq!(persisted_json["preferences"]["display_dim_timeout"], "30s");

        let next =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let next_snapshot = configure_platform_capabilities_in_session(
            next.handle,
            PlatformCapabilities {
                display_policy: Some(PlatformDisplayPolicyCapability::default()),
                ..PlatformCapabilities::default()
            },
            Some(storage),
        )
        .expect("configure platform capabilities");
        assert_eq!(next_snapshot.settings_page_state.rows[1].value_id, "30s");
        assert_eq!(
            next_snapshot
                .display_policy
                .as_ref()
                .and_then(|policy| policy.dim_after_ms),
            Some(30_000)
        );
    }

    #[test]
    fn settings_action_leaves_live_model_unchanged_when_storage_rejects_write() {
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let before = configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities {
                display_policy: Some(PlatformDisplayPolicyCapability::default()),
                ..PlatformCapabilities::default()
            },
            Some(Arc::new(RejectingSettingsStorage)),
        )
        .expect("configure rejecting storage");
        assert_eq!(before.settings_page_state.rows[1].value_id, "2m");

        let error = super::perform_settings_action_in_session(
            init.handle,
            UiSettingsAction {
                action_id: "display_dim_timeout".to_string(),
                value_id: "30s".to_string(),
            },
        )
        .expect_err("failed persistence must reject setting");
        assert!(error.message.contains("injected settings write failure"));

        let after = get_session_snapshot(init.handle).expect("snapshot retained setting");
        assert_eq!(after.session_revision, before.session_revision);
        assert_eq!(after.settings_page_state.rows[1].value_id, "2m");
        assert_eq!(
            after
                .display_policy
                .as_ref()
                .and_then(|policy| policy.dim_after_ms),
            Some(120_000)
        );
        let diagnostics = session_diagnostics(init.handle).expect("diagnostics");
        assert_eq!(diagnostics.transaction_rollback_count, 1);
        assert_eq!(diagnostics.settings_revision, 0);
        destroy_session(init.handle);
    }

    #[test]
    fn platform_configuration_rolls_back_when_settings_read_fails() {
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let error = super::configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities {
                display_policy: Some(PlatformDisplayPolicyCapability::default()),
                ..PlatformCapabilities::default()
            },
            Some(Arc::new(RejectingSettingsReadStorage)),
        )
        .expect_err("failed settings read must reject configuration");
        assert!(error.message.contains("injected settings read failure"));

        let snapshot = get_session_snapshot(init.handle).expect("retained initial snapshot");
        assert_eq!(snapshot.session_revision, 0);
        assert!(snapshot.display_policy.is_none());
        assert!(snapshot.settings_page_state.rows.len() == 1);
        let diagnostics = session_diagnostics(init.handle).expect("diagnostics");
        assert_eq!(diagnostics.transaction_rollback_count, 1);
        destroy_session(init.handle);
    }

    #[test]
    fn offline_package_profile_is_core_persisted_across_session_restart() {
        let storage: SettingsStorageHandle = Arc::new(MemorySettingsStorage::default());
        let first =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        configure_platform_capabilities_in_session(
            first.handle,
            PlatformCapabilities::default(),
            Some(storage.clone()),
        )
        .expect("configure storage");

        let preferences = serde_json::json!({
            "regions": {"nw": "pause"},
            "products": {"terrain": "unselected"}
        })
        .to_string();
        let outcome =
            record_offline_package_preferences_in_session(first.handle, &preferences, 100)
                .expect("record package profile");
        let HadOperationOutcome::Complete {
            result,
            invalidations,
        } = outcome
        else {
            panic!("package preference update unexpectedly needed resources");
        };
        let projected_preferences = result["packages"]["assignments"]
            .as_array()
            .expect("package assignments")
            .iter()
            .find(|assignment| {
                assignment["path"] == serde_json::json!(["offline_package_preferences_json"])
            })
            .and_then(|assignment| assignment["value"].as_str())
            .expect("projected preferences JSON");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(projected_preferences).unwrap(),
            serde_json::from_str::<serde_json::Value>(&preferences).unwrap()
        );
        assert!(result["packages"].is_object());
        assert!(result.get("cloud").is_none());
        assert!(invalidations.contains(&UiInvalidation::SessionSnapshot));
        let snapshot = get_session_snapshot(first.handle).expect("snapshot package profile");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&snapshot.offline_package_preferences_json)
                .unwrap(),
            serde_json::from_str::<serde_json::Value>(&preferences).unwrap()
        );
        destroy_session(first.handle);

        let restarted =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("restart session");
        let restored = configure_platform_capabilities_in_session(
            restarted.handle,
            PlatformCapabilities::default(),
            Some(storage),
        )
        .expect("restore storage");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&restored.offline_package_preferences_json)
                .unwrap(),
            serde_json::from_str::<serde_json::Value>(&preferences).unwrap()
        );
        let sessions = lock_sessions();
        let session = session_ref(&sessions, restarted.handle).expect("restored session");
        assert_eq!(
            session.packages.preferences(),
            &session
                .cloud
                .offline_package_preferences()
                .expect("cloud package preferences")
        );
        drop(session);
        drop(sessions);
        destroy_session(restarted.handle);
    }

    #[test]
    fn offline_package_profile_rolls_back_controller_and_cloud_when_persistence_fails() {
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities::default(),
            Some(Arc::new(RejectingSettingsStorage)),
        )
        .expect("configure rejecting storage");
        let before = get_session_snapshot(init.handle).expect("initial snapshot");
        let before_diagnostics = session_diagnostics(init.handle).expect("initial diagnostics");
        let preferences = serde_json::json!({
            "regions": {"nw": "pause"},
            "products": {"terrain": "unselected"}
        })
        .to_string();

        let error = record_offline_package_preferences_in_session(init.handle, &preferences, 100)
            .expect_err("persistence failure must reject package preferences");

        assert!(error.message.contains("injected settings write failure"));
        let after = get_session_snapshot(init.handle).expect("rolled-back snapshot");
        let after_diagnostics = session_diagnostics(init.handle).expect("rolled-back diagnostics");
        assert_eq!(after.session_revision, before.session_revision);
        assert_eq!(
            after_diagnostics.cloud_revision,
            before_diagnostics.cloud_revision
        );
        assert_eq!(
            after.offline_package_preferences_json,
            before.offline_package_preferences_json
        );
        let sessions = lock_sessions();
        let session = session_ref(&sessions, init.handle).expect("session");
        assert_eq!(
            session.packages.preferences(),
            &crate::OfflinePackagePreferences::default()
        );
        assert_eq!(
            session
                .cloud
                .offline_package_preferences()
                .expect("cloud package preferences"),
            crate::OfflinePackagePreferences::default()
        );
        drop(session);
        drop(sessions);
        destroy_session(init.handle);
    }

    #[test]
    fn flight_data_visibility_setting_filters_snapshot_and_persists() {
        let storage: SettingsStorageHandle = Arc::new(MemorySettingsStorage::default());
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let snapshot = configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities::default(),
            Some(storage.clone()),
        )
        .expect("configure platform capabilities");
        assert_eq!(snapshot.app_ui_state.flight_data_banner.cells.len(), 14);

        let snapshot = perform_settings_action_in_session(
            init.handle,
            UiSettingsAction {
                action_id: "flight_data_visibility".to_string(),
                value_id: "clock".to_string(),
            },
        )
        .expect("disable clock cell");
        assert!(!snapshot
            .app_ui_state
            .flight_data_banner
            .cells
            .iter()
            .any(|cell| cell.id == "clock"));
        let settings_item = snapshot.settings_page_state.rows[0]
            .items
            .iter()
            .find(|item| item.cell.id == "clock")
            .expect("clock settings item");
        assert!(!settings_item.enabled);

        let persisted = storage
            .read_settings()
            .expect("read settings")
            .expect("persisted bytes");
        let persisted_json: serde_json::Value =
            serde_json::from_slice(&persisted).expect("persisted json");
        assert_eq!(
            persisted_json["preferences"]["disabled_flight_data_cell_ids"][0],
            "clock"
        );

        let next =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let next_snapshot = configure_platform_capabilities_in_session(
            next.handle,
            PlatformCapabilities::default(),
            Some(storage),
        )
        .expect("load persisted preferences");
        assert!(!next_snapshot
            .app_ui_state
            .flight_data_banner
            .cells
            .iter()
            .any(|cell| cell.id == "clock"));

        let restored_snapshot = perform_settings_action_in_session(
            next.handle,
            UiSettingsAction {
                action_id: "flight_data_visibility".to_string(),
                value_id: "clock".to_string(),
            },
        )
        .expect("re-enable clock cell");
        assert!(restored_snapshot
            .app_ui_state
            .flight_data_banner
            .cells
            .iter()
            .any(|cell| cell.id == "clock"));
    }

    #[test]
    fn disclaimer_agreement_uses_core_owned_storage() {
        let storage: SettingsStorageHandle = Arc::new(MemorySettingsStorage::default());
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let snapshot = configure_platform_capabilities_in_session(
            init.handle,
            PlatformCapabilities::default(),
            Some(storage.clone()),
        )
        .expect("configure platform capabilities");

        assert!(snapshot.disclaimer_state.required);
        assert_eq!(snapshot.disclaimer_state.agreement_id, "no-warranty-v1");
        assert!(snapshot.disclaimer_state.text.contains("NO WARRANTY"));

        let snapshot =
            accept_disclaimer_in_session(init.handle, "no-warranty-v1").expect("accept disclaimer");
        assert!(!snapshot.disclaimer_state.required);

        let persisted = storage
            .read_settings()
            .expect("read settings")
            .expect("persisted bytes");
        let persisted_json: serde_json::Value =
            serde_json::from_slice(&persisted).expect("persisted json");
        assert_eq!(
            persisted_json["preferences"]["accepted_disclaimer_agreement_ids"][0],
            "no-warranty-v1"
        );

        let next =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        let next_snapshot = configure_platform_capabilities_in_session(
            next.handle,
            PlatformCapabilities::default(),
            Some(storage),
        )
        .expect("configure platform capabilities");
        assert!(!next_snapshot.disclaimer_state.required);
    }

    struct TestObstacleHad {
        manifest: serde_json::Value,
        root_bytes: Vec<u8>,
        pages: Vec<Vec<u8>>,
        state_sha256: String,
    }

    fn build_test_obstacle_had(
        viewport: &MapViewport,
        version: &str,
        record_id: &str,
    ) -> TestObstacleHad {
        let obstacle_manifest_base = serde_json::json!({
            "schema_version": 1,
            "product_id": "obstacles",
            "version_label": version,
            "encoding": format!("had-nav-kv-v{}", had_nav_kv::VERSION),
            "root": "root",
            "page_path_template": "page_{page:04}",
            "point_layers": {
                "obstacle": {
                    "min_zoom": 8,
                    "max_zoom": 8,
                    "available_zooms": [8],
                    "zoom_levels": [{
                        "zoom": 8,
                        "filtered": false,
                        "min_agl_ft": 0
                    }]
                }
            }
        });
        let obstacle_layer =
            obstacle_layer_config_from_live_manifest_value(obstacle_manifest_base.clone())
                .expect("obstacle layer config");
        let obstacle_tile =
            visible_obstacle_tile_window(&obstacle_layer, viewport, 240.0, 240.0, None, 1.0)
                .into_iter()
                .next()
                .expect("visible obstacle tile");
        let tile_payload = PointTilePayload {
            schema_version: 1,
            layer: "obstacle".to_string(),
            z: obstacle_tile.z,
            x: obstacle_tile.x,
            y: obstacle_tile.y,
            records: vec![PointVectorRecord {
                id: record_id.to_string(),
                kind: "obstacle".to_string(),
                lat: viewport.center.lat,
                lon: viewport.center.lon,
                label: "".to_string(),
                location_label: None,
                style_class: "obstacle".to_string(),
                towered: None,
                fuel_available: None,
                public_use: None,
                private_use: None,
                has_paved_runway: None,
                heliport: None,
                has_water_runway: None,
                longest_runway_length_ft: None,
                longest_runway_heading_true_deg: None,
                elevation_msl_ft: None,
                obstacle: Some(crate::map_overlay::ObstaclePointSemantics {
                    height_agl_ft: 300.0,
                    elevation_msl_ft: 500.0,
                    top_msl_ft: 800.0,
                    is_tall: false,
                }),
            }],
        };
        let obstacle_key = nav_kv_key_for_query(&NavKvQuery::ObstacleTile {
            z: obstacle_tile.z,
            x: obstacle_tile.x,
            y: obstacle_tile.y,
        })
        .expect("obstacle tile key");
        let pairs = vec![had_nav_kv::NavKvPair {
            key: obstacle_key,
            value: serde_json::to_vec(&tile_payload).expect("tile json"),
        }];
        let built =
            had_nav_kv::build_nav_kv_sorted(pairs.clone(), 1024).expect("build obstacle HAD");
        let state_sha256 = had_nav_kv::nav_kv_canonical_sha256_from_pairs(&pairs);
        let mut manifest = obstacle_manifest_base;
        manifest["page_count"] = serde_json::json!(built.pages.len());
        manifest["page_size"] = serde_json::json!(built.page_size);
        manifest["state_sha256"] = serde_json::json!(state_sha256);

        TestObstacleHad {
            manifest,
            root_bytes: built.root_bytes,
            pages: built.pages,
            state_sha256,
        }
    }

    fn ingest_test_live_obstacle_state(handle: u32, version: &str, obstacle_had: &TestObstacleHad) {
        let state_url = format!("states/obstacles/{version}/manifest.json");
        ingest_resource_in_session(
            handle,
            "live_feeds/current",
            &live_current_manifest_for_test(BTreeMap::from([(
                "obstacles".to_string(),
                live_current_product_for_test(
                    "obstacles",
                    version,
                    &state_url,
                    &obstacle_had.state_sha256,
                    Vec::new(),
                ),
            )])),
        )
        .expect("current manifest");
        ingest_resource_in_session(
            handle,
            &format!("live_feeds/version/obstacles/{version}"),
            &live_version_manifest_for_test(
                "obstacles",
                version,
                "nav_kv",
                &state_url,
                &obstacle_had.state_sha256,
            ),
        )
        .expect("version manifest");
        ingest_resource_in_session(
            handle,
            &format!("live_feeds/state/obstacles/{version}"),
            &serde_json::to_vec(&obstacle_had.manifest).expect("manifest json"),
        )
        .expect("state manifest");
    }

    fn load_test_live_obstacle_had_pages(
        handle: u32,
        version: &str,
        obstacle_had: &TestObstacleHad,
        metrics: &MapSurfaceMetrics,
    ) {
        {
            let mut sessions = lock_sessions();
            let mut session = session_mut(&mut sessions, handle).expect("session");
            let statuses = ensure_live_obstacle_inputs_loaded(&mut session, metrics);
            assert_eq!(statuses.len(), 1);
        }
        let effects = drain_session_resource_effects(handle).expect("root effects");
        let effects = effects
            .into_iter()
            .filter(|effect| {
                effect
                    .resource
                    .id
                    .starts_with(&format!("live_obstacle_had/{version}/"))
            })
            .collect::<Vec<_>>();
        assert_eq!(effects.len(), 1);
        assert_eq!(
            effects[0].resource.id,
            format!("live_obstacle_had/{version}/root")
        );
        ingest_resource_in_session(
            handle,
            &format!("live_obstacle_had/{version}/root"),
            &obstacle_had.root_bytes,
        )
        .expect("ingest root");

        {
            let mut sessions = lock_sessions();
            let mut session = session_mut(&mut sessions, handle).expect("session");
            let statuses = ensure_live_obstacle_inputs_loaded(&mut session, metrics);
            assert_eq!(statuses.len(), 1);
        }
        let page_effects = drain_session_resource_effects(handle)
            .expect("page effects")
            .into_iter()
            .filter(|effect| {
                effect
                    .resource
                    .id
                    .starts_with(&format!("live_obstacle_had/{version}/"))
            })
            .collect::<Vec<_>>();
        assert!(!page_effects.is_empty());
        for effect in &page_effects {
            let page_text = effect
                .resource
                .id
                .strip_prefix(&format!("live_obstacle_had/{version}/page/"))
                .expect("page resource id");
            let page_index = page_text.parse::<usize>().expect("page index");
            ingest_resource_in_session(
                handle,
                &effect.resource.id,
                &obstacle_had.pages[page_index],
            )
            .expect("ingest page");
        }
    }

    fn query_obstacle_feature_ids(handle: u32, metrics: &MapSurfaceMetrics) -> Vec<String> {
        let (config, obstacle_cache) = {
            let mut sessions = lock_sessions();
            let mut session = session_mut(&mut sessions, handle).expect("session");
            let statuses = ensure_live_obstacle_inputs_loaded(&mut session, metrics);
            assert!(statuses.is_empty());
            (
                session.map.overlay_config().clone(),
                session.weather.runtime().obstacle_tile_cache.clone(),
            )
        };
        let overlay = crate::query_map_overlay_for_surface(
            metrics,
            &config,
            true,
            false,
            &[],
            None,
            &HashMap::new(),
            &obstacle_cache,
            &HashMap::new(),
            None,
            None,
            &HashMap::new(),
            None,
            &[],
        );
        overlay
            .visible_features
            .into_iter()
            .map(|feature| feature.id)
            .collect()
    }

