    #[test]
    fn altitude_planner_departure_editor_parses_text_and_is_clearable_to_now() {
        let init = create_current_test_session();
        let departure = utc("2026-05-21T15:30:00Z").timestamp_millis();

        perform_flight_plan_command_in_session(
            init.handle,
            FlightPlanSessionCommand::SetAltitudePlannerDepartureInput {
                field: crate::AltitudePlannerDepartureInputField::Time,
                input: "1530Z".to_string(),
            },
            utc("2026-05-21T12:00:30Z").timestamp_millis(),
        )
        .expect("set planned departure");
        {
            let sessions = lock_sessions();
            let session = session_ref(&sessions, init.handle).expect("session");
            assert_eq!(
                session
                    .flight_plan
                    .active_plan()
                    .and_then(|plan| plan.planned_departure_time_epoch_ms),
                Some(departure),
            );
            assert_eq!(
                session.coordinator.time_display_mode,
                crate::TimeDisplayMode::Utc,
            );
        }

        perform_time_display_action_in_session(
            init.handle,
            crate::TOGGLE_TIME_DISPLAY_MODE_ACTION_ID.to_string(),
        )
        .expect("toggle departure display to local time");
        {
            let sessions = lock_sessions();
            let session = session_ref(&sessions, init.handle).expect("session");
            assert_eq!(
                session.coordinator.time_display_mode,
                crate::TimeDisplayMode::Local,
            );
            assert_eq!(
                session
                    .flight_plan
                    .active_plan()
                    .and_then(|plan| plan.planned_departure_time_epoch_ms),
                Some(departure),
            );
        }

        perform_flight_plan_command_in_session(
            init.handle,
            FlightPlanSessionCommand::SetAltitudePlannerDepartureInput {
                field: crate::AltitudePlannerDepartureInputField::When,
                input: "-3".to_string(),
            },
            utc("2026-05-21T12:01:00Z").timestamp_millis(),
        )
        .expect("set past departure by relative offset");
        {
            let sessions = lock_sessions();
            assert_eq!(
                session_ref(&sessions, init.handle)
                    .expect("session")
                    .flight_plan
                    .active_plan()
                    .and_then(|plan| plan.planned_departure_time_epoch_ms),
                Some(utc("2026-05-21T09:01:00Z").timestamp_millis()),
            );
        }

        perform_flight_plan_command_in_session(
            init.handle,
            FlightPlanSessionCommand::SetAltitudePlannerDepartureInput {
                field: crate::AltitudePlannerDepartureInputField::When,
                input: "now".to_string(),
            },
            utc("2026-05-21T12:01:15Z").timestamp_millis(),
        )
        .expect("restore depart-now mode");
        let sessions = lock_sessions();
        assert_eq!(
            session_ref(&sessions, init.handle)
                .expect("session")
                .flight_plan
                .active_plan()
                .and_then(|plan| plan.planned_departure_time_epoch_ms),
            None
        );
    }

    fn data_status_box<'a>(
        snapshot: &'a UiSessionSnapshot,
        id: &str,
    ) -> &'a crate::data_status::UiDataStatusBox {
        snapshot
            .data_status_state
            .boxes
            .iter()
            .find(|box_| box_.id == id)
            .unwrap_or_else(|| panic!("missing status box {id}"))
    }

    fn has_data_status_box(snapshot: &UiSessionSnapshot, id: &str) -> bool {
        snapshot
            .data_status_state
            .boxes
            .iter()
            .any(|box_| box_.id == id)
    }

