        {
            let mut sessions = lock_sessions();
            let mut session = session_mut(&mut sessions, init.handle).expect("session");
            install_vector_manifest_config(&mut session, minimal_vector_manifest_json())
                .expect("vector manifest");
            session.map.set_layer_visibility(MapLayerId::Vectors, true);
        }
        ingest_resource_in_session(
            init.handle,
            "live_feeds/current",
            &live_current_manifest_for_test(BTreeMap::from([(
                "obstacles".to_string(),
                live_current_product_for_test(
                    "obstacles",
                    "v1",
                    "states/obstacles/v1/manifest.json",
                    &state_sha256,
                    Vec::new(),
                ),
            )])),
        )
        .expect("current manifest");
        ingest_resource_in_session(
            init.handle,
            "live_feeds/version/obstacles/v1",
            &live_version_manifest_for_test(
                "obstacles",
                "v1",
                "nav_kv",
                "states/obstacles/v1/manifest.json",
                &state_sha256,
            ),
        )
        .expect("version manifest");
