    #[test]
    fn sequencing_atomically_advances_snapshot_and_route_projection() {
        let init = create_ui_session(short_lat_lon_preview_plan(), &[], None, None)
            .expect("create session");
        let store = crate::navkv::nav_kv_store_for_test(&[], 256);
        attach_isolated_test_nav_kv_store(init.handle, &store);

        let initial_route =
            project_flight_plan_route_in_session(init.handle).expect("project initial route");
        let HadOperationOutcome::Complete { result, .. } = initial_route else {
            panic!("initial route unexpectedly needed resources");
        };
        let initial_projection: crate::FlightPlanRouteProjection =
            serde_json::from_value(result).expect("initial route projection");
        assert_eq!(initial_projection.flight_plan_route_revision, 0);
        assert_eq!(
            initial_projection
                .segments
                .iter()
                .map(|segment| segment.status.clone())
                .collect::<Vec<_>>(),
            vec![
                crate::FlightPlanRouteSegmentStatus::Active,
                crate::FlightPlanRouteSegmentStatus::Remaining,
            ]
        );

        let outcome = super::sequence_active_leg_in_session(init.handle)
            .expect("sequence active flight-plan leg");
        let HadOperationOutcome::Complete {
            result,
            invalidations,
        } = outcome
        else {
            panic!("sequencing unexpectedly needed resources");
        };
        let update: UiSessionUpdate = serde_json::from_value(result).expect("sequenced update");
        let snapshot = get_session_snapshot(init.handle).expect("sequenced snapshot");
        assert!(invalidations.contains(&UiInvalidation::SessionSnapshot));
        assert!(invalidations.contains(&UiInvalidation::FlightPlanRoute));
        assert!(invalidations.contains(&UiInvalidation::MapOverlay));
        assert_eq!(update.session_revision, snapshot.session_revision);
        assert_eq!(snapshot.flight_plan_route_revision, 1);

        let route =
            project_flight_plan_route_in_session(init.handle).expect("project sequenced route");
        let HadOperationOutcome::Complete { result, .. } = route else {
            panic!("sequenced route unexpectedly needed resources");
        };
        let projection: crate::FlightPlanRouteProjection =
            serde_json::from_value(result).expect("sequenced route projection");
        assert_eq!(
            projection.flight_plan_route_revision,
            snapshot.flight_plan_route_revision
        );
        assert_ne!(
            projection.flight_plan_route_revision,
            initial_projection.flight_plan_route_revision
        );
        assert_eq!(
            projection
                .segments
                .iter()
                .map(|segment| segment.status.clone())
                .collect::<Vec<_>>(),
            vec![
                crate::FlightPlanRouteSegmentStatus::Completed,
                crate::FlightPlanRouteSegmentStatus::Active,
            ]
        );

        let active_leg_index = snapshot
            .app_state
            .active_plan
            .as_ref()
            .and_then(|plan| plan.guidance.as_ref())
            .map(|guidance| guidance.active_leg_index)
            .expect("active core leg");
        let expected_active_leg_id = &snapshot
            .app_state
            .active_plan
            .as_ref()
            .expect("active plan")
            .resolved_legs[active_leg_index]
            .id;
        let active_segments = projection
            .segments
            .iter()
            .filter(|segment| segment.status == crate::FlightPlanRouteSegmentStatus::Active)
            .collect::<Vec<_>>();
        assert_eq!(active_segments.len(), 1);
        assert_eq!(&active_segments[0].leg_id, expected_active_leg_id);
    }

    #[test]
    fn manual_sequence_cannot_leave_rendered_route_on_previous_active_leg() {
        let init = create_ui_session(short_lat_lon_preview_plan(), &[], None, None)
            .expect("create session");
        let initial_snapshot = get_session_snapshot(init.handle).expect("initial snapshot");
        let mut rendered_route_plan = initial_snapshot
            .app_state
            .active_plan
            .clone()
            .expect("initial active plan");

        let outcome = super::sequence_active_leg_in_session(init.handle)
            .expect("sequence active flight-plan leg");
        let HadOperationOutcome::Complete {
            result,
            invalidations,
        } = outcome
        else {
            panic!("sequencing unexpectedly needed resources");
        };
        let update: UiSessionUpdate = serde_json::from_value(result).expect("sequenced update");
        let snapshot = get_session_snapshot(init.handle).expect("sequenced snapshot");
        assert_eq!(update.session_revision, snapshot.session_revision);

        if invalidations.contains(&UiInvalidation::FlightPlanRoute) {
            rendered_route_plan = snapshot
                .app_state
                .active_plan
                .clone()
                .expect("refreshed route plan");
        }

        let active_leg_index = snapshot
            .app_state
            .active_plan
            .as_ref()
            .and_then(|plan| plan.guidance.as_ref())
            .map(|guidance| guidance.active_leg_index)
            .expect("core snapshot active leg");
        let expected_active_leg_id = &snapshot
            .app_state
            .active_plan
            .as_ref()
            .expect("active plan")
            .resolved_legs[active_leg_index]
            .id;
        let rendered_active_leg_ids = rendered_route_plan
            .resolved_legs
            .iter()
            .zip(self_contained_route_statuses(&rendered_route_plan))
            .filter_map(|(leg, status)| {
                (status == crate::FlightPlanRouteSegmentStatus::Active).then_some(leg.id.as_str())
            })
            .collect::<Vec<_>>();

        assert_eq!(
            rendered_active_leg_ids,
            vec![expected_active_leg_id.as_str()],
            "the rendered magenta route must identify the FP snapshot's active leg"
        );
    }

    #[test]
    fn manual_sequence_display_endpoint_is_not_a_sequencing_finish_line() {
        let mut plan = short_procedure_display_path_plan();
        let provenance = plan.resolved_legs[0]
            .procedure_provenance
            .as_mut()
            .expect("procedure provenance");
        provenance.kind = ProcedureKind::Sid;
        provenance.path_termination = PathTermination::HeadingToAltitude;
        provenance.discontinuity_after = Some(ProcedureDiscontinuity::Vectors);
        let guidance = plan.guidance.as_mut().expect("guidance");
        guidance.active_detail_index = Some(1);
        guidance.sequencing_mode = SequencingMode::Suspended;
        guidance.suspend_reason = Some(crate::planning::SuspendReason::Boundary);

        let route = crate::project_flight_plan_route_with_resolver(&plan, |_, _| {
            Err("manual-sequence fixture is self-contained")
        })
        .expect("project manual-sequence display path");
        let geometry_by_id = crate::flight_plan_materialization::geometry_map_from_route(&route);

        assert!(
            crate::flight_plan_controller::active_detail_finish_criterion_for_test(
                &plan,
                1,
                &geometry_by_id,
                false,
            )
            .is_none(),
            "the finite chevron extension is display geometry, not a sequencing target"
        );
    }

    #[test]
    fn session_revision_advances_on_mutation_not_read() {
        let init =
            create_ui_session(FlightPlan::default(), &[], None, None).expect("create session");
        assert_eq!(init.snapshot.session_revision, 0);

        let initial_read = get_session_snapshot(init.handle).expect("read snapshot");
        assert_eq!(initial_read.session_revision, 0);

        let first_mutation = set_debug_flag_in_session(init.handle, DebugFlagId::TileLabels, true)
            .expect("set debug flag");
        assert_eq!(first_mutation.session_revision, 1);

        let post_mutation_read = get_session_snapshot(init.handle).expect("read snapshot again");
        assert_eq!(
            post_mutation_read.session_revision,
            first_mutation.session_revision
        );

        let second_mutation =
            set_debug_flag_in_session(init.handle, DebugFlagId::TileLabels, false)
                .expect("clear debug flag");
        assert_eq!(second_mutation.session_revision, 2);
    }

    #[test]
    fn map_selection_direct_to_requires_ownship_position() {
        let selection = MapSelectionQueryResult {
            click_lat: 47.49,
            click_lon: -122.76,
            initial_selected_item_id: Some("airport:KPWT".to_string()),
            categories: vec![MapSelectionCategory {
                id: "points".to_string(),
                label: "Points".to_string(),
                items: vec![MapSelectionItem {
                    id: "airport:KPWT".to_string(),
                    label: "KPWT".to_string(),
                    sublabel: "Airport".to_string(),
                    description: None,
                    distance: None,
                    secondary_description: None,
                    position: None,
                    elevation_msl_ft: None,
                    detail_text: None,
                    highlight: MapSelectionHighlight::Spot {
                        lat: 47.49,
                        lon: -122.76,
                    },
                    nav_ref: Some(NavRef::Airport("KPWT".to_string())),
                    symbol_feature: None,
                    metar_feature: None,
                    pirep_feature: None,
                    airspace_icon: None,
                    actions: vec![MapSelectionAction {
                        id: "direct_to".to_string(),
                        label: "Direct".to_string(),
                        enabled: true,
                        display_only: false,
                        detail_text: None,
                        detail_title: None,
                        detail_status: None,
                        disabled_reason: None,
                        weather_detail: None,
                        airport_info_airport_id: None,
                        airspace_limit: None,
                        session_action: Some("direct-to-action".to_string()),
                        flight_plan_row_action: None,
                        navigation: None,
                    }],
                }],
            }],
        };

        let unavailable = map_selection_with_session_action_availability(selection.clone(), false);
        let action = &unavailable.categories[0].items[0].actions[0];
        assert!(!action.enabled);
        assert_eq!(
            action.disabled_reason.as_deref(),
            Some(crate::planning::DIRECT_TO_OWNSHIP_POSITION_DISABLED_REASON)
        );
        assert_eq!(action.detail_text, None);
        assert!(action.session_action.is_none());
        assert!(action.flight_plan_row_action.is_none());

        let available = map_selection_with_session_action_availability(selection, true);
        let action = &available.categories[0].items[0].actions[0];
        assert!(action.enabled);
        assert_eq!(action.session_action.as_deref(), Some("direct-to-action"));
        assert!(action.flight_plan_row_action.is_none());
    }

